INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3195d94e-02ec-4277-8cd9-6afff518cb82', '春怨', '春怨', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["音書杜絕白狼西，桃李無顏黃鳥啼。","寒雁春深歸去盡，出門腸斷草萋萋。"]', '["音书杜絕白狼西，桃李無顏黄鸟啼。","寒雁春深归去尽，出门腸斷草萋萋。"]', '诗', 'shi', '', NULL, '春怨 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e4a693d-49d2-4791-bb34-f49ddd202d49', '句', '句', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["朝薦抱良策，獨倚江城樓。","昨從金陵邑，遠謫沅溪濱。","娟魄已三孕。","駕幸溫泉日，嚴霜子月初。","長亭酒未醒，千里風動地。","蒼荻寒滄江，石頭岸邊飲。","天仗森森練雪凝，身騎鐵驄自臂鷹。"]', '["朝薦抱良策，独倚江城楼。","昨從金陵邑，远謫沅溪濱。","娟魄已三孕。","駕幸溫泉日，嚴霜子月初。","长亭酒未醒，千里风动地。","蒼荻寒滄江，石头岸邊饮。","天仗森森練雪凝，身騎鐵驄自臂鷹。"]', '诗', 'shi', '', NULL, '句 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c83eace-eff6-404e-9186-bb5407c4a0bb', '送陸擢', '送陸擢', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["聖代多才俊，陸生何考槃。","南山高松樹，不合空摧殘。","九月湖上別，北風秋雨寒。","殷勤歎孤鳳，早食金琅玕。"]', '["聖代多才俊，陸生何考槃。","南山高松樹，不合空摧殘。","九月湖上別，北风秋雨寒。","殷勤歎孤鳳，早食金琅玕。"]', '诗', 'shi', '', NULL, '送陸擢 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5db693e-8b72-43e3-aefa-2d56bf112d61', '送李十一尉臨溪', '送李十一尉臨溪', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["泠泠花下琴，君唱渡江吟。","天際一帆影，預懸離別心。","以言神仙尉，因致瑤華音。","回軫撫商調，越溪澄碧林。"]', '["泠泠花下琴，君唱渡江吟。","天際一帆影，預懸離別心。","以言神仙尉，因致瑤华音。","回軫撫商調，越溪澄碧林。"]', '诗', 'shi', '', NULL, '送李十一尉臨溪 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c965b46-4730-40b0-9b01-f117a107cfb7', '江上琴興', '江上琴兴', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["江上調玉琴，一弦清一心。","泠泠七弦遍，萬木澄幽陰。","能使江月白，又令江水深。","始知梧桐枝，可以徽黃金。"]', '["江上調玉琴，一弦清一心。","泠泠七弦遍，万木澄幽陰。","能使江月白，又令江水深。","始知梧桐枝，可以徽黄金。"]', '诗', 'shi', '', NULL, '江上琴興 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ce9062d-4aed-4cb1-9dd7-ad3c723be7c7', '湖中晚霽', '湖中晚霽', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["湖廣舟自輕，江天欲澄霽。","是時清楚望，氣色猶霾曀。","踟躕金霞白，波上日初麗。","煙虹落鏡中，樹木生天際。","杳杳涯欲辨，蒙蒙雲復閉。","言乘星漢明，又覩寰瀛勢。","微興從此愜，悠然不知歲。","試歌滄浪清，遂覺乾坤細。","豈念客衣薄，將期永投袂。","遲回漁父間，一鴈聲嘹唳。"]', '["湖廣舟自轻，江天欲澄霽。","是时清楚望，氣色猶霾曀。","踟躕金霞白，波上日初丽。","煙虹落镜中，樹木生天際。","杳杳涯欲辨，蒙蒙云复閉。","言乘星漢明，又覩寰瀛勢。","微兴從此愜，悠然不知歲。","試歌滄浪清，遂覺乾坤細。","豈念客衣薄，將期永投袂。","遲回漁父间，一鴈声嘹唳。"]', '诗', 'shi', '', NULL, '湖中晚霽 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c854a853-b015-4848-823b-a786659d33b3', '宿王昌齡隱居', '宿王昌齡隐居', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["清溪深不測，隱處唯孤雲。","松際露微月，清光猶爲君。","茅亭宿花影，藥院滋苔紋。","余亦謝時去，西山鸞鶴羣。"]', '["清溪深不測，隐处唯孤云。","松際露微月，清光猶爲君。","茅亭宿花影，藥院滋苔紋。","余亦謝时去，西山鸾鹤羣。"]', '诗', 'shi', '', NULL, '宿王昌齡隱居 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cd46838-b0ae-4a8a-bc10-4366c585f4a1', '送楚十少府', '送楚十少府', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["微風吹霜氣，寒影明前除。","落日未能別，蕭蕭林木虛。","愁煙閉千里，仙尉其何如。","因送別鶴操，贈之雙鯉魚。","鯉魚在金盤，別鶴哀有餘。","心事則如此，請君開素書。"]', '["微风吹霜氣，寒影明前除。","落日未能別，蕭蕭林木虛。","愁煙閉千里，仙尉其何如。","因送別鹤操，贈之雙鯉鱼。","鯉鱼在金盤，別鹤哀有餘。","心事則如此，請君开素书。"]', '诗', 'shi', '', NULL, '送楚十少府 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b393f0d7-de43-49ae-8ebb-37f0b3efc919', '張山人彈琴', '張山人彈琴', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["君去芳草綠，西峰彈玉琴。","豈惟丘中賞，兼得清煩襟。","朝從山口還，出嶺聞清音。","了然雲霞氣，照見天地心。","玄鶴下澄空，翩翩舞松林。","改弦扣商聲，又聽飛龍吟。","稍覺此身妄，漸知仙事深。","其將鍊金鼎，永矣投吾簪。"]', '["君去芳草綠，西峰彈玉琴。","豈惟丘中賞，兼得清煩襟。","朝從山口還，出嶺闻清音。","了然云霞氣，照见天地心。","玄鹤下澄空，翩翩舞松林。","改弦扣商声，又听飞龙吟。","稍覺此身妄，漸知仙事深。","其將鍊金鼎，永矣投吾簪。"]', '诗', 'shi', '', NULL, '張山人彈琴 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab1c7011-0dd3-4efc-8996-56c111c4a260', '白湖寺後溪宿雲門', '白湖寺後溪宿云门', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["落日山水清，亂流鳴淙淙。","舊蒲雨抽節，新花水對窓。","溪中日已沒，歸鳥多爲雙。","杉松引直路，出谷臨前湖。","洲渚晚色靜，又觀花與蒲。","入溪復登嶺，草淺寒流速。","圓月明高峰，春山因獨宿。","松陰澄初夜，曙色分遠目。","日出城南隅，青青媚川陸。","亂花覆東郭，碧氣銷長林。","四郊一清影，千里歸寸心。","前瞻王程促，却戀雲門深。","畢景有餘興，到家彈玉琴。"]', '["落日山水清，亂流鳴淙淙。","旧蒲雨抽節，新花水对窓。","溪中日已沒，归鸟多爲雙。","杉松引直路，出谷臨前湖。","洲渚晚色静，又观花與蒲。","入溪复登嶺，草淺寒流速。","圓月明高峰，春山因独宿。","松陰澄初夜，曙色分远目。","日出城南隅，青青媚川陸。","亂花覆东郭，碧氣銷长林。","四郊一清影，千里归寸心。","前瞻王程促，却戀云门深。","畢景有餘兴，到家彈玉琴。"]', '诗', 'shi', '', NULL, '白湖寺後溪宿雲門 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c16709fd-1a50-42d7-82b9-92f204491289', '閑齋臥病行藥至山館稍次湖亭二首 一', '闲斋臥病行藥至山館稍次湖亭二首 一', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["旬時結陰霖，簾外初白日。","齋沐清病容，心魂畏虛室。","閑梅照前戶，明鏡悲舊質。"]', '["旬时結陰霖，簾外初白日。","斋沐清病容，心魂畏虛室。","闲梅照前戶，明镜悲旧質。"]', '诗', 'shi', '', NULL, '閑齋臥病行藥至山館稍次湖亭二首 一 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8e319c5-6407-4397-b9c9-67f29068497b', '閑齋臥病行藥至山館稍次湖亭二首 二', '闲斋臥病行藥至山館稍次湖亭二首 二', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["行藥至石壁，東風變萌芽。","主人門外綠，小隱湖中花。","時物堪獨往，春帆宜別家。","辭君嚮滄海，爛熳從天涯。"]', '["行藥至石壁，东风变萌芽。","主人门外綠，小隐湖中花。","时物堪独往，春帆宜別家。","辞君嚮滄海，爛熳從天涯。"]', '诗', 'shi', '', NULL, '閑齋臥病行藥至山館稍次湖亭二首 二 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95bccdb8-832d-43cf-a33c-2f92f757af1b', '塞上曲', '塞上曲', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["翩翩雲中使，來問太原卒。","百戰苦不歸，刀頭怨明月。","塞雲隨陣落，寒日傍城沒。","城下有寡妻，哀哀哭枯骨。"]', '["翩翩云中使，来问太原卒。","百戰苦不归，刀头怨明月。","塞云隨陣落，寒日傍城沒。","城下有寡妻，哀哀哭枯骨。"]', '诗', 'shi', '', NULL, '塞上曲 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('113e4509-3dcf-4327-92a2-40f723af7a8a', '仙谷遇毛女意知是秦宮人', '仙谷遇毛女意知是秦宮人', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["溪口水石淺，泠泠明藥叢。","入溪雙峰峻，松栝疎幽風。","垂嶺枝嫋嫋，翳泉花濛濛。","夤緣霽人目，路盡心彌通。","盤石橫陽崖，前流殊未窮。","回潭清雲影，瀰漫長天空。","水邊一神女，千歲爲玉童。","羽毛經漢代，珠翠逃秦宮。","目覿神已寓，鶴飛言未終。","祈君青雲祕，願謁黃仙翁。","嘗以耕玉田，龍鳴西頂中。","金梯與天接，幾日來相逢。"]', '["溪口水石淺，泠泠明藥叢。","入溪雙峰峻，松栝疎幽风。","垂嶺枝嫋嫋，翳泉花濛濛。","夤緣霽人目，路尽心彌通。","盤石橫陽崖，前流殊未窮。","回潭清云影，瀰漫长天空。","水邊一神女，千歲爲玉童。","羽毛經漢代，珠翠逃秦宮。","目覿神已寓，鹤飞言未終。","祈君青云祕，願謁黄仙翁。","嘗以耕玉田，龙鳴西頂中。","金梯與天接，幾日来相逢。"]', '诗', 'shi', '', NULL, '仙谷遇毛女意知是秦宮人 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e65e92d4-a81f-40e1-9ba3-dad53597f220', '夢太白西峰', '梦太白西峰', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["夢寐昇九崖，杳靄逢元君。","遺我太白峰，寥寥辭垢氛。","結宇在星漢，宴林閉氤氳。","簷楹覆餘翠，巾舄生片雲。","時往溪水間，孤亭晝仍曛。","松峰引天影，石瀨清霞文。","恬目緩舟趣，霽心投鳥羣。","春風又搖櫂，潭島花紛紛。"]', '["梦寐昇九崖，杳靄逢元君。","遺我太白峰，寥寥辞垢氛。","結宇在星漢，宴林閉氤氳。","簷楹覆餘翠，巾舄生片云。","时往溪水间，孤亭晝仍曛。","松峰引天影，石瀨清霞文。","恬目緩舟趣，霽心投鸟羣。","春风又搖櫂，潭島花紛紛。"]', '诗', 'shi', '', NULL, '夢太白西峰 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b149e1ae-86b7-4843-a1e2-f02fa57f6ea3', '鄂渚招王昌齡張僨', '鄂渚招王昌齡張僨', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["刈蘆曠野中，沙土飛黃雲。","天晦無精光，茫茫悲遠君。","楚山隔湘水，湖畔落日曛。","春鴈又北飛，音書固難聞。","謫居未爲歎，讒枉何由分。","午日逐蛟龍，宜爲弔冤文。","翻覆古共然，名宦安足云。","貧士任枯槁，捕魚清江濆。","有時荷鉏犂，曠野自耕耘。","不然春山隱，溪澗花氤氳。","山鹿自有場，賢達亦顧羣。","二賢歸去來，世上徒紛紛。"]', '["刈蘆曠野中，沙土飞黄云。","天晦無精光，茫茫悲远君。","楚山隔湘水，湖畔落日曛。","春鴈又北飞，音书固难闻。","謫居未爲歎，讒枉何由分。","午日逐蛟龙，宜爲弔冤文。","翻覆古共然，名宦安足云。","貧士任枯槁，捕鱼清江濆。","有时荷鉏犂，曠野自耕耘。","不然春山隐，溪澗花氤氳。","山鹿自有場，賢達亦顧羣。","二賢归去来，世上徒紛紛。"]', '诗', 'shi', '', NULL, '鄂渚招王昌齡張僨 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c8d2ff2-b449-4af8-93d5-d8f6abd96362', '春詞二首 一', '春词二首 一', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["菀菀黃柳絲，濛濛雜花垂。","日高紅妝臥，倚對春光遲。","寧知傍淇水，騕褭黃金羈。"]', '["菀菀黄柳絲，濛濛杂花垂。","日高紅妝臥，倚对春光遲。","寧知傍淇水，騕褭黄金羈。"]', '诗', 'shi', '', NULL, '春詞二首 一 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b308cc03-0433-4d04-b6a3-8f5664fa87a8', '春詞二首 二', '春词二首 二', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["翳翳陌上桑，南枝交北堂。","美人金梯出，素手自提筐。","非但畏蠶飢，盈盈嬌路傍。"]', '["翳翳陌上桑，南枝交北堂。","美人金梯出，素手自提筐。","非但畏蠶飢，盈盈嬌路傍。"]', '诗', 'shi', '', NULL, '春詞二首 二 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('720a581a-cbaa-49ae-ad44-65eace499018', '晦日馬鐙曲稍次中流作', '晦日马鐙曲稍次中流作', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["夜寒宿蘆葦，曉色明西林。","初日在川上，便澄遊子心。","秦天無纖翳，郊野浮春陰。","波靜隨釣魚，舟小綠水深。","出浦見千里，曠然諧遠尋。","扣船應漁父，因唱滄浪吟。"]', '["夜寒宿蘆葦，晓色明西林。","初日在川上，便澄游子心。","秦天無纖翳，郊野浮春陰。","波静隨釣鱼，舟小綠水深。","出浦见千里，曠然諧远尋。","扣船應漁父，因唱滄浪吟。"]', '诗', 'shi', '', NULL, '晦日馬鐙曲稍次中流作 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ad90448-eba6-4c79-9092-3f17e2807f09', '古意', '古意', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["牧馬古道傍，道傍多古墓。","蕭條愁殺人，蟬鳴白楊樹。","迴頭望京邑，合沓生塵霧。","富貴安可常，歸來保貞素。"]', '["牧马古道傍，道傍多古墓。","蕭條愁殺人，蟬鳴白楊樹。","迴头望京邑，合沓生塵霧。","富貴安可常，归来保貞素。"]', '诗', 'shi', '', NULL, '古意 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6225c38b-8e85-4f74-b5b8-34cd1038a85b', '宿五度溪仙人得道處', '宿五度溪仙人得道处', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["五度溪上花，生根依兩崖。","二月尋片雲，願宿秦人家。","上見懸崖崩，下見白水湍。","仙人彈碁處，石上青蘿盤。","無處求玉童，翳翳唯林巒。","前溪遇新月，聊取玉琴彈。"]', '["五度溪上花，生根依兩崖。","二月尋片云，願宿秦人家。","上见懸崖崩，下见白水湍。","仙人彈碁处，石上青蘿盤。","無处求玉童，翳翳唯林巒。","前溪遇新月，聊取玉琴彈。"]', '诗', 'shi', '', NULL, '宿五度溪仙人得道處 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4ef2905-143e-4c53-84c1-aeb7a87fcdb9', '西山', '西山', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["一身爲輕舟，落日西山際。","常隨去帆影，遠接長天勢。","物象歸餘清，林巒分夕麗。","亭亭碧流暗，日入孤霞繼。","渚日遠陰映，湖雲尚明霽。","林昏楚色來，岸遠荆門閉。","至夜轉清逈，蕭蕭北風厲。","沙邊鴈鷺泊，宿處蒹葭蔽。","圓月逗前浦，孤琴又搖曳。","泠然夜遂深，白露霑人袂。"]', '["一身爲轻舟，落日西山際。","常隨去帆影，远接长天勢。","物象归餘清，林巒分夕丽。","亭亭碧流暗，日入孤霞繼。","渚日远陰映，湖云尚明霽。","林昏楚色来，岸远荆门閉。","至夜轉清逈，蕭蕭北风厲。","沙邊鴈鷺泊，宿处蒹葭蔽。","圓月逗前浦，孤琴又搖曳。","泠然夜遂深，白露霑人袂。"]', '诗', 'shi', '', NULL, '西山 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07095ed9-e671-48e1-9255-75aaafff2bd7', '春詞', '春词', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["階下草猶短，牆頭梨花白。","織女高樓上，停梭顧行客。","問君在何所，青鳥舒錦翮。"]', '["階下草猶短，牆头梨花白。","织女高楼上，停梭顧行客。","问君在何所，青鸟舒錦翮。"]', '诗', 'shi', '', NULL, '春詞 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e4bd839-4acb-4834-82ac-e13d881ab964', '贈三侍御', '贈三侍御', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["高山臨大澤，正月蘆花乾。","陽色薰兩崖，不改青松寒。","士賢守孤貞，古來皆共難。","明君錯甚才，臺上飛三鸞。","操與霜雪明，量與江海寬。","束身視天涯，安能窮波瀾。","孤鶴在枳棘，一枝非所安。","逸翮望絕霄，見欲凌雲端。","層臺何其高，山石流洪湍。","固知非天池，鳴躍同所歡。","誰念獨枯槁，四十長江干。","責躬貴知己，效拙從一官。","折翮悲高風，苦飢候朝飡。","湖月映大海，天空何漫漫。","托身未知所，謀道庶不刊。","吟彼喬木詩，一夕常三歎。"]', '["高山臨大澤，正月蘆花乾。","陽色薰兩崖，不改青松寒。","士賢守孤貞，古来皆共难。","明君錯甚才，台上飞三鸾。","操與霜雪明，量與江海寬。","束身視天涯，安能窮波瀾。","孤鹤在枳棘，一枝非所安。","逸翮望絕霄，见欲凌云端。","層台何其高，山石流洪湍。","固知非天池，鳴躍同所歡。","誰念独枯槁，四十长江干。","責躬貴知己，效拙從一官。","折翮悲高风，苦飢候朝飡。","湖月映大海，天空何漫漫。","托身未知所，謀道庶不刊。","吟彼喬木诗，一夕常三歎。"]', '诗', 'shi', '', NULL, '贈三侍御 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad65dba-7a25-45a7-8d7e-63d3c3eba0f6', '第三峰', '第三峰', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["西山第三頂，茅宇依雙松。","杳杳欲至天，雲梯升幾重。","瑩魄澄玉虛，以求鸞鶴蹤。","逶迤非天人，執節乘赤龍。","旁映白日光，縹緲輕霞容。","孤輝上煙霧，餘影明心胸。","願與黃麒麟，欲飛而莫從。","因寂清萬象，輕雲自中峰。","山暝學棲鳥，月來隨暗蛬。","尋空靜餘響，嫋嫋雲溪鐘。"]', '["西山第三頂，茅宇依雙松。","杳杳欲至天，云梯升幾重。","瑩魄澄玉虛，以求鸾鹤蹤。","逶迤非天人，執節乘赤龙。","旁映白日光，縹緲轻霞容。","孤輝上煙霧，餘影明心胸。","願與黄麒麟，欲飞而莫從。","因寂清万象，轻云自中峰。","山暝学棲鸟，月来隨暗蛬。","尋空静餘响，嫋嫋云溪鐘。"]', '诗', 'shi', '', NULL, '第三峰 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8f715e7-913e-4f72-b64b-f7fee66c4e06', '古興', '古兴', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["漢上逢老翁，江口爲僵屍。","白髮沾黃泥，遺骸集烏鴟。","機巧自此忘，精魄今何之。","風吹釣竿折，魚躍安能施。","白水明汀洲，菰蒲冒深陂。","唯留扁舟影，繫在長江湄。","突兀枯松枝，悠揚女蘿絲。","託身難憑依，生死焉相知。","徧觀今時人，舉世皆爾爲。","將軍死重圍，漢卒猶爭馳。","百馬同一銜，萬輪同一規。","名與身孰親，君子宜固思。"]', '["漢上逢老翁，江口爲僵屍。","白髮沾黄泥，遺骸集烏鴟。","機巧自此忘，精魄今何之。","风吹釣竿折，鱼躍安能施。","白水明汀洲，菰蒲冒深陂。","唯留扁舟影，繫在长江湄。","突兀枯松枝，悠揚女蘿絲。","託身难憑依，生死焉相知。","徧观今时人，舉世皆爾爲。","將軍死重圍，漢卒猶爭驰。","百马同一銜，万輪同一規。","名與身孰親，君子宜固思。"]', '诗', 'shi', '', NULL, '古興 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ce260b0-4dc4-43aa-b99a-c8dfc898d16d', '高樓夜彈箏', '高楼夜彈箏', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["高樓百餘尺，直上江水平。","明月照人苦，開簾彈玉箏。","山高猿狖急，天靜鴻鴈鳴。","曲度猶未終，東峰霞半生。"]', '["高楼百餘尺，直上江水平。","明月照人苦，开簾彈玉箏。","山高猿狖急，天静鴻鴈鳴。","曲度猶未終，东峰霞半生。"]', '诗', 'shi', '', NULL, '高樓夜彈箏 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c821bad8-1488-4a70-a291-3194bdf98869', '客有自燕而歸哀其老而贈之', '客有自燕而归哀其老而贈之', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["羸馬朝自燕，一身爲二連。","憶親拜孤冢，移葬雙陵前。","幽願從此畢，劒心因獲全。","孟冬寒氣盛，撫轡告言旋。","碣石海北門，餘寇惟朝鮮。","離離一寒騎，嫋嫋馳白天。","生別皆自取，況爲士卒先。","寸心漁陽興，落日旌竿懸。"]', '["羸马朝自燕，一身爲二連。","憶親拜孤冢，移葬雙陵前。","幽願從此畢，劒心因獲全。","孟冬寒氣盛，撫轡告言旋。","碣石海北门，餘寇惟朝鲜。","離離一寒騎，嫋嫋驰白天。","生別皆自取，況爲士卒先。","寸心漁陽兴，落日旌竿懸。"]', '诗', 'shi', '', NULL, '客有自燕而歸哀其老而贈之 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ad743d3-64f7-4c13-b8a7-b6bba3223219', '白龍窟汎舟寄天台學道者', '白龙窟汎舟寄天台学道者', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["夕映翠山深，餘暉在龍窟。","扁舟滄浪意，澹澹花影沒。","西浮入天色，南望對雲闕。","因憶莓苔峰，初陽濯玄髮。","泉蘿兩幽映，松鶴間清越。","碧海瑩子神，玉膏澤人骨。","忽然爲枯木，微興遂如兀。","應寂中有天，明心外無物。","環迴從所汎，夜靜猶不歇。","澹然意無限，身與波上月。"]', '["夕映翠山深，餘暉在龙窟。","扁舟滄浪意，澹澹花影沒。","西浮入天色，南望对云闕。","因憶莓苔峰，初陽濯玄髮。","泉蘿兩幽映，松鹤间清越。","碧海瑩子神，玉膏澤人骨。","忽然爲枯木，微兴遂如兀。","應寂中有天，明心外無物。","环迴從所汎，夜静猶不歇。","澹然意無限，身與波上月。"]', '诗', 'shi', '', NULL, '白龍窟汎舟寄天台學道者 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed156f96-68db-4e04-a18c-661ebc02fcb8', '張天師草堂', '張天師草堂', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["靈溪宴清宇，傍倚枯松根。","花藥繞方丈，瀑泉飛至門。","四氣閉炎熱，兩崖改明昏。","夜深月蹔皎，亭午朝始暾。","信是天人居，幽幽寂無喧。","萬壑應鳴磬，諸峰接一魂。","遂登仙子谷，因醉田生樽。","時節開玉書，窅映飛天言。","心化便無影，目精焉累煩。","忽而與霄漢，寥落空南軒。"]', '["靈溪宴清宇，傍倚枯松根。","花藥繞方丈，瀑泉飞至门。","四氣閉炎熱，兩崖改明昏。","夜深月蹔皎，亭午朝始暾。","信是天人居，幽幽寂無喧。","万壑應鳴磬，諸峰接一魂。","遂登仙子谷，因醉田生樽。","时節开玉书，窅映飞天言。","心化便無影，目精焉累煩。","忽而與霄漢，寥落空南軒。"]', '诗', 'shi', '', NULL, '張天師草堂 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46d184bf-6716-4148-a817-ddae0ece7ef0', '古意三首 一', '古意三首 一', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["二妃方訪舜，萬里南方懸。","遠道隔江漢，孤舟無歲年。","不知蒼梧處，氣盡呼青天。","愁淚變楚竹，蛾眉喪湘川。","後人立爲廟，累世稱其賢。","過客設祠祭，孤狸來坐邊。","懷古未忍還，猿吟徹空山。"]', '["二妃方訪舜，万里南方懸。","远道隔江漢，孤舟無歲年。","不知蒼梧处，氣尽呼青天。","愁泪变楚竹，蛾眉喪湘川。","後人立爲廟，累世稱其賢。","過客設祠祭，孤狸来坐邊。","懷古未忍還，猿吟徹空山。"]', '诗', 'shi', '', NULL, '古意三首 一 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afa12db7-68c8-42f5-8338-9878438f8237', '古意三首 二', '古意三首 二', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["明月照高閣，綵女褰羅幕。","歌舞臨碧雲，簫聲沸珠箔。","青鸞臨南海，天上雙白鶴。","萬里齊翼飛，意求君門樂。","玉霄九重閉，金鎖夜不開。","兩翅自無力，愁鳴雲外來。","態深入空貴，世屈無良媒。","俛仰顧中禁，東飛白玉臺。"]', '["明月照高閣，綵女褰羅幕。","歌舞臨碧云，簫声沸珠箔。","青鸾臨南海，天上雙白鹤。","万里齊翼飞，意求君门乐。","玉霄九重閉，金鎖夜不开。","兩翅自無力，愁鳴云外来。","態深入空貴，世屈無良媒。","俛仰顧中禁，东飞白玉台。"]', '诗', 'shi', '', NULL, '古意三首 二 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a922a9e2-666a-4682-8f6d-f715262fb373', '古意三首 三', '古意三首 三', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["楚王竟何去，獨自留巫山。","偏使世人見，迢迢江漢間。","駐舟春溪裏，皆願拜靈顏。","寤寐見神女，金沙鳴珮環。","閑豔絕世姿，令人氣力微。","含笑竟不語，化作朝雲飛。"]', '["楚王竟何去，独自留巫山。","偏使世人见，迢迢江漢间。","駐舟春溪裏，皆願拜靈顏。","寤寐见神女，金沙鳴珮环。","闲豔絕世姿，令人氣力微。","含笑竟不語，化作朝云飞。"]', '诗', 'shi', '', NULL, '古意三首 三 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89353814-9e6b-4241-9b7f-2110453c296b', '漁浦', '漁浦', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["春至百草綠，陂澤聞鶬鶊。","別家投釣翁，今世滄浪情。","漚紵爲緼袍，折麻爲長纓。","榮譽失本真，怪人浮此生。","碧水月自闊，安流淨而平。","扁舟與天際，獨往誰能名。"]', '["春至百草綠，陂澤闻鶬鶊。","別家投釣翁，今世滄浪情。","漚紵爲緼袍，折麻爲长纓。","榮譽失本真，怪人浮此生。","碧水月自闊，安流淨而平。","扁舟與天際，独往誰能名。"]', '诗', 'shi', '', NULL, '漁浦 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a94f81f-2c0d-4db5-bb7a-8ed7e791e7d5', '空靈山應田叟', '空靈山應田叟', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["湖南無村落，山舍多黃茆。","淳朴如太古，其人居鳥巢。","牧童唱巴歌，野老亦獻嘲。","泊舟問溪口，言語皆啞咬。","土俗不尚農，豈暇論肥磽。","莫傜射禽獸，浮客烹魚鮫。","余亦罘罝人，獲麋今尚苞。","敬君中國來，願以充其庖。","日入聞虎鬬，空山滿咆哮。","懷人雖共安，異域終難交。","白水可洗心，采薇可爲肴。","曳策背落日，江風鳴梢梢。"]', '["湖南無村落，山舍多黄茆。","淳朴如太古，其人居鸟巢。","牧童唱巴歌，野老亦獻嘲。","泊舟问溪口，言語皆啞咬。","土俗不尚農，豈暇論肥磽。","莫傜射禽獸，浮客烹鱼鮫。","余亦罘罝人，獲麋今尚苞。","敬君中国来，願以充其庖。","日入闻虎鬬，空山满咆哮。","懷人雖共安，異域終难交。","白水可洗心，采薇可爲肴。","曳策背落日，江风鳴梢梢。"]', '诗', 'shi', '', NULL, '空靈山應田叟 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e6396b5-568c-4eca-b3d1-dcf62290c62e', '太公哀晚遇', '太公哀晚遇', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["日出渭流白，文王畋獵時。","釣翁在蘆葦，川澤無熊羆。","詔書起遺賢，匹馬令致辭。","因稱江海人，臣老筋力衰。","遲遲詣天車，快快悟靈龜。","兵馬更不獵，君臣皆共怡。","同車至咸陽，心影無磷緇。","四牡玉墀下，一言爲帝師。","王侯擁朱門，軒蓋曜長逵。","古來榮華人，遭遇誰知之。","落日懸桑榆，光景有頓虧。","倏忽天地人，雖貴將何爲。"]', '["日出渭流白，文王畋獵时。","釣翁在蘆葦，川澤無熊羆。","詔书起遺賢，匹马令致辞。","因稱江海人，臣老筋力衰。","遲遲詣天车，快快悟靈龟。","兵马更不獵，君臣皆共怡。","同车至咸陽，心影無磷緇。","四牡玉墀下，一言爲帝師。","王侯擁朱门，軒蓋曜长逵。","古来榮华人，遭遇誰知之。","落日懸桑榆，光景有頓虧。","倏忽天地人，雖貴將何爲。"]', '诗', 'shi', '', NULL, '太公哀晚遇 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74a19b6a-1837-4633-bb06-5d8027229cb5', '昭君墓', '昭君墓', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["漢宮豈不死，異域傷獨沒。","萬里馱黃金，蛾眉爲枯骨。","迴車夜出塞，立馬皆不發。","共恨丹青人，墳上哭明月。"]', '["漢宮豈不死，異域傷独沒。","万里馱黄金，蛾眉爲枯骨。","迴车夜出塞，立马皆不發。","共恨丹青人，墳上哭明月。"]', '诗', 'shi', '', NULL, '昭君墓 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c773c84d-c788-4650-8772-df213d4c0bb0', '弔王將軍墓', '弔王將軍墓', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["嫖姚北伐時，深入強千里。","戰餘落日黃，軍敗鼓聲死。","嘗聞漢飛將，可奪單于壘。","今與山鬼鄰，殘兵哭遼水。"]', '["嫖姚北伐时，深入強千里。","戰餘落日黄，軍敗鼓声死。","嘗闻漢飞將，可奪單于壘。","今與山鬼鄰，殘兵哭遼水。"]', '诗', 'shi', '', NULL, '弔王將軍墓 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7f07caf-48e3-444b-bc41-d7dc56175fd8', '古意', '古意', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["井底玉冰洞地明，琥珀轆轤青絲索。","仙人騎鳳披彩霞，挽上銀瓶照天閣。","黃金作身雙飛龍，口銜明月噴芙蓉。","一時渡海望不見，曉上青樓十二重。"]', '["井底玉冰洞地明，琥珀轆轤青絲索。","仙人騎鳳披彩霞，挽上銀瓶照天閣。","黄金作身雙飞龙，口銜明月噴芙蓉。","一时渡海望不见，晓上青楼十二重。"]', '诗', 'shi', '', NULL, '古意 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d76ad288-4ed5-47df-b27d-09b8d84eb883', '古興', '古兴', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["轆轤井上雙梧桐，飛鳥銜花日將沒。","深閨女兒莫愁年，玉指泠泠怨金碧。","石榴裙裾蛺蝶飛，見人不語顰蛾眉。","青絲素絲紅綠絲，織成錦衾當爲誰。"]', '["轆轤井上雙梧桐，飞鸟銜花日將沒。","深閨女兒莫愁年，玉指泠泠怨金碧。","石榴裙裾蛺蝶飞，见人不語顰蛾眉。","青絲素絲紅綠絲，织成錦衾當爲誰。"]', '诗', 'shi', '', NULL, '古興 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('314fe39a-f774-497d-b473-d3e46252e1cf', '張公子行', '張公子行', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["日出乘釣舟，嫋嫋持釣竿。","涉淇傍荷花，驄馬閑金鞍。","俠客白雲中，腰間懸轆轤。","出門事嫖姚，爲君西擊胡。","胡兵漢騎相馳逐，轉戰孤軍西海北。","百尺旌竿沈黑雲，邊笳落日不堪聞。"]', '["日出乘釣舟，嫋嫋持釣竿。","涉淇傍荷花，驄马闲金鞍。","俠客白云中，腰间懸轆轤。","出门事嫖姚，爲君西擊胡。","胡兵漢騎相驰逐，轉戰孤軍西海北。","百尺旌竿沈黑云，邊笳落日不堪闻。"]', '诗', 'shi', '', NULL, '張公子行 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5540f756-f737-4bbd-82da-4a3cc9ca1681', '題破山寺後禪院', '題破山寺後禪院', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["清晨入古寺，初日照高林。","竹逕通幽處，禪房花木深。","山光悅鳥性，潭影空人心。","萬籟此都寂，但餘鐘磬音。"]', '["清晨入古寺，初日照高林。","竹逕通幽处，禪房花木深。","山光悅鸟性，潭影空人心。","万籟此都寂，但餘鐘磬音。"]', '诗', 'shi', '', NULL, '題破山寺後禪院 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd7452c9-5a5f-4f8e-95b4-bc6298581eed', '送李大都護', '送李大都護', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["單于雖不戰，都護事邊深。","君執幕中秘，能爲高士心。","海頭近初月，磧裏多愁陰。","西望郭猶子，將分淚滿襟。"]', '["單于雖不戰，都護事邊深。","君執幕中秘，能爲高士心。","海头近初月，磧裏多愁陰。","西望郭猶子，將分泪满襟。"]', '诗', 'shi', '', NULL, '送李大都護 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee8adc18-110d-4f91-9664-dea75f1d9034', '潭州留別', '潭州留別', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["賢達不相識，偶然交已深。","宿帆謁郡佐，悵別依禪林。","湘水流入海，楚雲千里心。","望君杉松夜，山月清猿吟。"]', '["賢達不相識，偶然交已深。","宿帆謁郡佐，悵別依禪林。","湘水流入海，楚云千里心。","望君杉松夜，山月清猿吟。"]', '诗', 'shi', '', NULL, '潭州留別 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d341a95-4bf3-47c5-8582-a9338a141ce9', '聽琴秋夜贈寇尊師', '听琴秋夜贈寇尊師', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["琴當秋夜聽，況是洞中人。","一指指應法，一聲聲爽神。","寒蟲臨砌急，清吹褭燈頻。","何必鍾期耳，高閑自可親。"]', '["琴當秋夜听，況是洞中人。","一指指應法，一声声爽神。","寒蟲臨砌急，清吹褭灯頻。","何必鍾期耳，高闲自可親。"]', '诗', 'shi', '', NULL, '聽琴秋夜贈寇尊師 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e4f3eca-126b-4c57-9e4d-f99ca89a1590', '泊舟盱眙', '泊舟盱眙', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["泊舟淮水次，霜降夕流清。","夜久潮侵岸，天寒月近城。","平沙依鴈宿，候館聽雞鳴。","鄉國雲霄外，誰堪羈旅情。"]', '["泊舟淮水次，霜降夕流清。","夜久潮侵岸，天寒月近城。","平沙依鴈宿，候館听雞鳴。","乡国云霄外，誰堪羈旅情。"]', '诗', 'shi', '', NULL, '泊舟盱眙 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07dae002-049f-4304-bf8f-d63b531a804d', '江行', '江行', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["平湖四無際，此夜泛孤舟。","明月異方意，吳歌令客愁。","鄉園碧雲外，兄弟淥江頭。","萬里無歸信，傷心看斗牛。"]', '["平湖四無際，此夜泛孤舟。","明月異方意，吳歌令客愁。","乡园碧云外，兄弟淥江头。","万里無归信，傷心看斗牛。"]', '诗', 'shi', '', NULL, '江行 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d51ad8f-fc5c-4858-b56a-6301110f7581', '燕居', '燕居', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["青苔常滿路，流水復入林。","遠與市朝隔，日聞雞犬深。","寥寥丘中想，渺渺湖上心。","嘯傲轉無欲，不知成陸沈。"]', '["青苔常满路，流水复入林。","远與市朝隔，日闻雞犬深。","寥寥丘中想，渺渺湖上心。","嘯傲轉無欲，不知成陸沈。"]', '诗', 'shi', '', NULL, '燕居 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('919f52f1-ac12-45ff-8e7b-5eab356e2851', '送宇文六', '送宇文六', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["花映垂楊漢水清，微風林裏一枝輕。","即今江北還如此，愁殺江南離別情。"]', '["花映垂楊漢水清，微风林裏一枝轻。","即今江北還如此，愁殺江南離別情。"]', '诗', 'shi', '', NULL, '送宇文六 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59c1e828-a843-4397-8704-683245fc63c7', '落第長安', '落第长安', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["家園好在尚留秦，耻作明時失路人。","恐逢故里鶯花笑，且向長安度一春。"]', '["家园好在尚留秦，耻作明时失路人。","恐逢故里鶯花笑，且向长安度一春。"]', '诗', 'shi', '', NULL, '落第長安 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a41d66f5-0ea7-4958-a87e-3bb677936fec', '塞下', '塞下', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["鐵馬胡裘出漢營，分麾百道救龍城。","左賢未遁旌竿折，過在將軍不在兵。"]', '["鐵马胡裘出漢營，分麾百道救龙城。","左賢未遁旌竿折，過在將軍不在兵。"]', '诗', 'shi', '', NULL, '塞下 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f21311f0-f008-4418-b7d0-8077797c809c', '題法院', '題法院', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["勝景門閑對遠山，竹深松老半含煙。","皓月殿中三度磬，水晶宮裏一僧禪。"]', '["勝景门闲对远山，竹深松老半含煙。","皓月殿中三度磬，水晶宮裏一僧禪。"]', '诗', 'shi', '', NULL, '題法院 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e42b317-cf60-444c-acce-85a2337fcd79', '嶺猿', '嶺猿', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["杳杳褭褭清且切，鷓鴣飛處又斜陽。","相思嶺上相思淚，不到三聲合斷腸。"]', '["杳杳褭褭清且切，鷓鴣飞处又斜陽。","相思嶺上相思泪，不到三声合斷腸。"]', '诗', 'shi', '', NULL, '嶺猿 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b720c5ef-f568-4560-8cef-07504b9bf710', '三日尋李九莊', '三日尋李九莊', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["雨歇楊林東渡頭，永和三日盪輕舟。","故人家在桃花岸，直到門前溪水流。"]', '["雨歇楊林东渡头，永和三日盪轻舟。","故人家在桃花岸，直到门前溪水流。"]', '诗', 'shi', '', NULL, '三日尋李九莊 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e024d8a0-f723-4e71-afaa-0ad5b3cab9cb', '塞下曲四首 一', '塞下曲四首 一', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["玉帛朝回望帝鄉，烏孫歸去不稱王。","天涯靜處無征戰，兵氣銷爲日月光。"]', '["玉帛朝回望帝乡，烏孫归去不稱王。","天涯静处無征戰，兵氣銷爲日月光。"]', '诗', 'shi', '', NULL, '塞下曲四首 一 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('853b888e-e5c3-4e81-817f-231e2a0268eb', '塞下曲四首 二', '塞下曲四首 二', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["北海陰風動地來，明君祠上望龍堆。","髑髏皆是長城卒，日暮沙場飛作灰。"]', '["北海陰风动地来，明君祠上望龙堆。","髑髏皆是长城卒，日暮沙場飞作灰。"]', '诗', 'shi', '', NULL, '塞下曲四首 二 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b100bff8-009f-40b8-83bd-9b8a7baa80c3', '塞下曲四首 三', '塞下曲四首 三', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["龍鬬雌雄勢已分，山崩鬼哭恨將軍。","黃河直北千餘里，冤氣蒼茫成黑雲。"]', '["龙鬬雌雄勢已分，山崩鬼哭恨將軍。","黄河直北千餘里，冤氣蒼茫成黑云。"]', '诗', 'shi', '', NULL, '塞下曲四首 三 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc45c575-e72c-4018-bc4c-283d06fe3ac2', '塞下曲四首 四', '塞下曲四首 四', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["因嫁單于怨在邊，蛾眉萬古葬胡天。","漢家此去三千里，青冢常無草木煙。"]', '["因嫁單于怨在邊，蛾眉万古葬胡天。","漢家此去三千里，青冢常無草木煙。"]', '诗', 'shi', '', NULL, '塞下曲四首 四 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('633a03fa-64cf-445f-bb15-375f23a1fb03', '戲題湖上', '戲題湖上', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["湖上老人坐磯頭，湖裏桃花水却流。","竹竿嫋嫋白波際，不知何者吞吾鈎。"]', '["湖上老人坐磯头，湖裏桃花水却流。","竹竿嫋嫋白波際，不知何者吞吾鈎。"]', '诗', 'shi', '', NULL, '戲題湖上 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83763f28-847b-4d87-bc73-806a44aceeab', '吳故宮', '吳故宮', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["越女歌長君且聽，芙蓉香滿水邊城。","豈知一日終非主，猶自如今有怨聲。"]', '["越女歌长君且听，芙蓉香满水邊城。","豈知一日終非主，猶自如今有怨声。"]', '诗', 'shi', '', NULL, '吳故宮 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0998d479-5f24-4e6f-b765-4e844c616c87', '從軍行', '從軍行', 'b0b1df55-b885-4329-abbd-f559bf77a4ec', '唐', '["秋草馬蹄輕，角弓持弦急。","去爲龍城候，正值胡兵襲。","軍氣橫大荒，戰酣日將入。","長風金鼓動，白露鐵衣濕。","四起愁邊聲，南轅時佇立。","斷蓬孤自轉，寒雁飛相及。","萬里雲沙漲，平川冰霰溢。","夜聞漢使歸，獨向刀環泣。"]', '["秋草马蹄轻，角弓持弦急。","去爲龙城候，正值胡兵襲。","軍氣橫大荒，戰酣日將入。","长风金鼓动，白露鐵衣濕。","四起愁邊声，南轅时佇立。","斷蓬孤自轉，寒雁飞相及。","万里云沙漲，平川冰霰溢。","夜闻漢使归，独向刀环泣。"]', '诗', 'shi', '', NULL, '從軍行 杜頠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02ff3c25-350b-473d-9a94-33a8d394510a', '故絳行', '故絳行', 'b0b1df55-b885-4329-abbd-f559bf77a4ec', '唐', '["君不見銅鞮觀，數里城池已蕪漫。","君不見虒祁宮，幾重臺榭亦微濛。","介馬兵車全盛時，歌童舞女妖豔姿。","一代繁華皆共絕，九原唯望冢纍纍。"]', '["君不见銅鞮观，數里城池已蕪漫。","君不见虒祁宮，幾重台榭亦微濛。","介马兵车全盛时，歌童舞女妖豔姿。","一代繁华皆共絕，九原唯望冢纍纍。"]', '诗', 'shi', '', NULL, '故絳行 杜頠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10d575b4-bb09-484e-9d32-6764aceb5431', '少年行三首 一', '少年行三首 一', 'e70c2a3f-d1d9-4ef3-b56a-f276ecf53e0d', '唐', '["十八羽林郎，戎衣侍漢王。","臂鷹金殿側，挾彈玉輿傍。","馳道春風起，陪游出建章。"]', '["十八羽林郎，戎衣侍漢王。","臂鷹金殿側，挾彈玉輿傍。","驰道春风起，陪游出建章。"]', '诗', 'shi', '', NULL, '少年行三首 一 李嶷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea4d86e4-7e99-4404-8373-20ab148106ff', '少年行三首 二', '少年行三首 二', 'e70c2a3f-d1d9-4ef3-b56a-f276ecf53e0d', '唐', '["侍獵長楊下，承恩更射飛。","塵生馬影滅，箭落雁行稀。","薄暮隨天仗，聯翩入瑣闈。"]', '["侍獵长楊下，承恩更射飞。","塵生马影滅，箭落雁行稀。","薄暮隨天仗，聯翩入瑣闈。"]', '诗', 'shi', '', NULL, '少年行三首 二 李嶷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ad8c14b-6ff5-4140-8ef0-2293c9019aa0', '少年行三首 三', '少年行三首 三', 'e70c2a3f-d1d9-4ef3-b56a-f276ecf53e0d', '唐', '["玉劒膝邊橫，金杯馬上傾。","朝遊茂陵道，夜宿鳳凰城。","豪吏多猜忌，無勞問姓名。"]', '["玉劒膝邊橫，金杯马上傾。","朝游茂陵道，夜宿鳳凰城。","豪吏多猜忌，無勞问姓名。"]', '诗', 'shi', '', NULL, '少年行三首 三 李嶷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d3a6bc0-2f88-486c-9c67-389315f8cf44', '淮南秋夜呈周偘', '淮南秋夜呈周偘', 'e70c2a3f-d1d9-4ef3-b56a-f276ecf53e0d', '唐', '["天淨河漢高，夜閑砧杵發。","清秋忽如此，離恨應難歇。","風亂池上萍，露光竹間月。","與君共遊處，勿作他鄉別。"]', '["天淨河漢高，夜闲砧杵發。","清秋忽如此，離恨應难歇。","风亂池上萍，露光竹间月。","與君共游处，勿作他乡別。"]', '诗', 'shi', '', NULL, '淮南秋夜呈周偘 李嶷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faf772a9-2cb6-4a3c-b785-6a0c98cad64e', '林園秋夜作', '林园秋夜作', 'e70c2a3f-d1d9-4ef3-b56a-f276ecf53e0d', '唐', '["林臥避殘暑，白雲長在天。","賞心既如此，對酒非徒然。","月色徧秋露，竹聲兼夜泉。","涼風懷袖裏，茲意與誰傳。"]', '["林臥避殘暑，白云长在天。","賞心既如此，对酒非徒然。","月色徧秋露，竹声兼夜泉。","涼风懷袖裏，茲意與誰傳。"]', '诗', 'shi', '', NULL, '林園秋夜作 李嶷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65fa0e28-d352-4d6e-8960-6da901fa11e6', '讀前漢外戚傳', '读前漢外戚傳', 'e70c2a3f-d1d9-4ef3-b56a-f276ecf53e0d', '唐', '["人錄尚書事，家臨御路傍。","鑿池通渭水，避暑借明光。","印綬妻封邑，軒車子拜郎。","寵因宮掖裏，勢極必先亡。"]', '["人錄尚书事，家臨御路傍。","鑿池通渭水，避暑借明光。","印綬妻封邑，軒车子拜郎。","寵因宮掖裏，勢極必先亡。"]', '诗', 'shi', '', NULL, '讀前漢外戚傳 李嶷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02e8f924-0c33-4a86-9266-2a13abe5c696', '春怨', '春怨', 'cf9db0e4-502d-4d03-97c4-4ac73bc5f660', '唐', '["夜盡夢初驚，紗窗早霧明。","曉妝脂粉薄，春服綺羅輕。","妾有今朝恨，君無舊日情。","愁來理弦管，皆是斷腸聲。"]', '["夜尽梦初驚，紗窗早霧明。","晓妝脂粉薄，春服綺羅轻。","妾有今朝恨，君無旧日情。","愁来理弦管，皆是斷腸声。"]', '诗', 'shi', '', NULL, '春怨 崔亘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8578a667-3a00-467d-bac5-9221d94d826c', '古歌二首 一', '古歌二首 一', '0e30b565-f26f-431d-9663-d37a03ded31e', '唐', '["美人怨何深，含情倚金閣。","不嚬復不語，紅淚雙雙落。"]', '["美人怨何深，含情倚金閣。","不嚬复不語，紅泪雙雙落。"]', '诗', 'shi', '', NULL, '古歌二首 一 蔣維翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2af05db1-1539-4f04-bd9e-e0edb8c2c383', '古歌二首 二', '古歌二首 二', '0e30b565-f26f-431d-9663-d37a03ded31e', '唐', '["美人閉紅燭，獨作裁新錦。","頻放剪刀聲，夜寒知未寢。"]', '["美人閉紅燭，独作裁新錦。","頻放剪刀声，夜寒知未寢。"]', '诗', 'shi', '', NULL, '古歌二首 二 蔣維翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4718069-a1f2-4fb2-8616-155260b0953f', '春夜裁縫', '春夜裁縫', '0e30b565-f26f-431d-9663-d37a03ded31e', '唐', '["珠箔因風起，飛蛾入最能。","不教人夜作，方便殺明燈。"]', '["珠箔因风起，飞蛾入最能。","不教人夜作，方便殺明灯。"]', '诗', 'shi', '', NULL, '春夜裁縫 蔣維翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('127fe4ff-3d28-41fa-adb7-7f0822e1c30c', '春女怨', '春女怨', '0e30b565-f26f-431d-9663-d37a03ded31e', '唐', '["白玉堂前一樹梅，今朝忽見數花開。","兒家門戶尋常閉，春色因何入得來。"]', '["白玉堂前一樹梅，今朝忽见數花开。","兒家门戶尋常閉，春色因何入得来。"]', '诗', 'shi', '', NULL, '春女怨 蔣維翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a54dc2be-9c56-4723-8f35-1d358cfc3ea6', '怨歌', '怨歌', '0e30b565-f26f-431d-9663-d37a03ded31e', '唐', '["百尺珠樓臨狹斜，新妝能唱美人車。","皆言賤妾紅顏好，要自狂夫不憶家。"]', '["百尺珠楼臨狹斜，新妝能唱美人车。","皆言賤妾紅顏好，要自狂夫不憶家。"]', '诗', 'shi', '', NULL, '怨歌 蔣維翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e10145cb-2c2f-43bc-bdf6-bb94e0c7a40f', '小山歌', '小山歌', 'a8bfe887-75c5-4523-a22b-b414739a35c1', '唐', '["人說淮南有小山，淮王昔日此登仙。","城中雞犬皆飛去，山上壇場今宛然。","世人貴身不貴壽，共笑華陽洞天口。","不知金石變長年，謾在人間戀攜手。","君能舉帆至淮南，家住盱眙余先諳。","桐柏亂流平入海，茱萸一曲沸成潭。","憶記來時魂悄悄，想見仙山衆峰小。","今日長歌思不堪，君行爲報三青鳥。"]', '["人说淮南有小山，淮王昔日此登仙。","城中雞犬皆飞去，山上壇場今宛然。","世人貴身不貴壽，共笑华陽洞天口。","不知金石变长年，謾在人间戀携手。","君能舉帆至淮南，家住盱眙余先諳。","桐柏亂流平入海，茱萸一曲沸成潭。","憶記来时魂悄悄，想见仙山衆峰小。","今日长歌思不堪，君行爲報三青鸟。"]', '诗', 'shi', '', NULL, '小山歌 萬楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e8a3b21-2b60-4a23-9aaa-2c25e113518a', '題江潮莊壁', '題江潮莊壁', 'a8bfe887-75c5-4523-a22b-b414739a35c1', '唐', '["田家喜秋熟，歲[晏]林葉稀。","禾黍積場圃，𣙁梨垂戶扉。","野閑犬時吠，日暮牛自歸。","時復落花酒，茅齋堪解衣。"]', '["田家喜秋熟，歲[晏]林葉稀。","禾黍積場圃，𣙁梨垂戶扉。","野闲犬时吠，日暮牛自归。","时复落花酒，茅斋堪解衣。"]', '诗', 'shi', '', NULL, '題江潮莊壁 萬楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bcc5817-9e08-4811-a05f-a9b346151cd8', '詠簾', '詠簾', 'a8bfe887-75c5-4523-a22b-b414739a35c1', '唐', '["玳瑁昔稱華，玲瓏薄絳紗。","鉤銜門勢曲，節亂水紋斜。","日弄長飛鳥，風搖不卷花。","自當分內外，非是爲驕奢。"]', '["玳瑁昔稱华，玲瓏薄絳紗。","鉤銜门勢曲，節亂水紋斜。","日弄长飞鸟，风搖不卷花。","自當分內外，非是爲驕奢。"]', '诗', 'shi', '', NULL, '詠簾 萬楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f110f0c4-fbae-4e1b-80bb-52ee4bbe33b6', '茱萸女', '茱萸女', 'a8bfe887-75c5-4523-a22b-b414739a35c1', '唐', '["山陰柳家女，九日采茱萸。","復得東鄰伴，雙爲陌上姝。","插枝著高髻，結子置長裾。","作性常遲緩，非關詫丈夫。","平明折林樾，日入返城隅。","俠客要羅袖，行人挑短書。","蛾眉自有主，年少莫踟躕。"]', '["山陰柳家女，九日采茱萸。","复得东鄰伴，雙爲陌上姝。","插枝著高髻，結子置长裾。","作性常遲緩，非关詫丈夫。","平明折林樾，日入返城隅。","俠客要羅袖，行人挑短书。","蛾眉自有主，年少莫踟躕。"]', '诗', 'shi', '', NULL, '茱萸女 萬楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97365d11-edc4-47aa-aa05-78654603b652', '五日觀妓', '五日观妓', 'a8bfe887-75c5-4523-a22b-b414739a35c1', '唐', '["西施謾道浣春紗，碧玉今時鬬麗華。","眉黛奪將萱草色，紅裙妬殺石榴花。","新歌一曲令人豔，醉舞雙眸斂鬢斜。","誰道五絲能續命，却令今日死君家。"]', '["西施謾道浣春紗，碧玉今时鬬丽华。","眉黛奪將萱草色，紅裙妬殺石榴花。","新歌一曲令人豔，醉舞雙眸斂鬢斜。","誰道五絲能續命，却令今日死君家。"]', '诗', 'shi', '', NULL, '五日觀妓 萬楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b69822f-7c9f-4aab-8f7e-274dbd3b229e', '驄馬', '驄马', 'a8bfe887-75c5-4523-a22b-b414739a35c1', '唐', '["金絡青驄白玉鞍，長鞭紫陌野遊盤。","朝驅東道塵恆滅，暮到河源日未闌。","汗血每隨邊地苦，蹄傷不憚隴陰寒。","君能一飲長城窟，爲報天山行路難。"]', '["金絡青驄白玉鞍，长鞭紫陌野游盤。","朝驱东道塵恆滅，暮到河源日未闌。","汗血每隨邊地苦，蹄傷不憚隴陰寒。","君能一饮长城窟，爲報天山行路难。"]', '诗', 'shi', '', NULL, '驄馬 萬楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22862542-4b60-49e2-984e-5f3a2fd3a45b', '題情人藥欄', '題情人藥欄', 'a8bfe887-75c5-4523-a22b-b414739a35c1', '唐', '["斂眉語芳草，何許太無情。","正見離人別，春心相向生。"]', '["斂眉語芳草，何許太無情。","正见離人別，春心相向生。"]', '诗', 'shi', '', NULL, '題情人藥欄 萬楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8641e63f-7257-4bb4-aea0-eddbdd97f4f5', '河上逢落花', '河上逢落花', 'a8bfe887-75c5-4523-a22b-b414739a35c1', '唐', '["河水浮落花，花流東不息。","應見浣紗人，爲道長相憶。"]', '["河水浮落花，花流东不息。","應见浣紗人，爲道长相憶。"]', '诗', 'shi', '', NULL, '河上逢落花 萬楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9eb0282-e880-4f7b-8044-f4fd06c529b0', '寧王山池', '寧王山池', '89cd1f7d-8e01-4f43-803d-a8e323855de7', '唐', '["水勢臨階轉，峰形對路開。","槎從天上得，石是海邊來。","瑞草分叢種，祥花間色栽。","舊傳詞賦客，唯見有鄒枚。"]', '["水勢臨階轉，峰形对路开。","槎從天上得，石是海邊来。","瑞草分叢種，祥花间色栽。","旧傳词賦客，唯见有鄒枚。"]', '诗', 'shi', '', NULL, '寧王山池 范朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('395eb911-96a8-4ef7-a2f6-7b052971a729', '題石甕寺', '題石甕寺', '89cd1f7d-8e01-4f43-803d-a8e323855de7', '唐', '["勝境宜長望，遲春好散愁。","關連四塞起，河帶八川流。","複磴承香閣，重巖映彩樓。","爲臨溫液近，偏美聖君遊。"]', '["勝境宜长望，遲春好散愁。","关連四塞起，河带八川流。","複磴承香閣，重巖映彩楼。","爲臨溫液近，偏美聖君游。"]', '诗', 'shi', '', NULL, '題石甕寺 范朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98d7814c-254a-45cd-a24f-fc41ad3bc777', '田家', '田家', '7258ac59-60bb-47d0-ba78-bb28fc7d56a2', '唐', '["小園足生事，尋勝日傾壺。","蒔蔬利於鬻，纔青摘已無。","四鄰依野竹，日夕采其枯。","田家心適時，春色徧桑榆。"]', '["小园足生事，尋勝日傾壺。","蒔蔬利於鬻，纔青摘已無。","四鄰依野竹，日夕采其枯。","田家心適时，春色徧桑榆。"]', '诗', 'shi', '', NULL, '田家 楊顔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f54ee0d6-5962-49a4-8f61-f7b237d3ba82', '後庭怨', '後庭怨', 'c28c3c75-e5e0-48bc-a68d-4061acac97c4', '唐', '["君不見紅閨少女端正時，夭夭桃李仙容姿。","幸得君王憐巧笑，披香殿裏薦蛾眉。","蛾眉雙雙人共進，常恐妾身從此擯。","甄妃爲妬出層宮，班女因猜下長信。","長信宮門閉不開，昭陽歌吹風送來。","夢中魂魄猶言是，覺後精神尚未迴。","念君嬌愛無終始，使妾長啼後庭裏。","獨立每看斜日盡，孤眠直至殘燈死。","秋日聞蟲翡翠簾，春晴照面鴛鴦水。","紅顏舊來花不勝，白髮如今雪相似。","傳聞紈扇恩未歇，預想蛾眉上初月。","如君貴僞不貴真，還同棄妾逐新人。","借問南山松葉意，何如北砌槿花新。"]', '["君不见紅閨少女端正时，夭夭桃李仙容姿。","幸得君王怜巧笑，披香殿裏薦蛾眉。","蛾眉雙雙人共進，常恐妾身從此擯。","甄妃爲妬出層宮，班女因猜下长信。","长信宮门閉不开，昭陽歌吹风送来。","梦中魂魄猶言是，覺後精神尚未迴。","念君嬌愛無終始，使妾长啼後庭裏。","独立每看斜日尽，孤眠直至殘灯死。","秋日闻蟲翡翠簾，春晴照面鴛鴦水。","紅顏旧来花不勝，白髮如今雪相似。","傳闻紈扇恩未歇，預想蛾眉上初月。","如君貴僞不貴真，還同棄妾逐新人。","借问南山松葉意，何如北砌槿花新。"]', '诗', 'shi', '', NULL, '後庭怨 王諲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef8d91e8-d06c-47e0-8aeb-3fa9196ef1d1', '夜坐看搊箏', '夜坐看搊箏', 'c28c3c75-e5e0-48bc-a68d-4061acac97c4', '唐', '["調箏夜坐燈光裏，却挂羅帷露纖指。","朱弦一一聲不同，玉柱連連影相似。","不知何處學新聲？曲曲彈來未覩名。","應是石家金谷裏，流傳未滿洛陽城。"]', '["調箏夜坐灯光裏，却挂羅帷露纖指。","朱弦一一声不同，玉柱連連影相似。","不知何处学新声？曲曲彈来未覩名。","應是石家金谷裏，流傳未满洛陽城。"]', '诗', 'shi', '', NULL, '夜坐看搊箏 王諲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc951b61-f1d8-4037-8b21-7f171ec28657', '長信怨', '长信怨', 'c28c3c75-e5e0-48bc-a68d-4061acac97c4', '唐', '["飛燕倚身輕，爭人巧笑名。","生君棄妾意，增妾怨君情。","日落昭陽壁，秋來長信城。","寥寥金殿裏，歌吹夜無聲。"]', '["飞燕倚身轻，爭人巧笑名。","生君棄妾意，增妾怨君情。","日落昭陽壁，秋来长信城。","寥寥金殿裏，歌吹夜無声。"]', '诗', 'shi', '', NULL, '長信怨 王諲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8da1a43c-1095-4175-9699-33b78b07e39c', '閨情', '閨情', 'c28c3c75-e5e0-48bc-a68d-4061acac97c4', '唐', '["日暮裁縫歇，深嫌氣力微。","纔能收篋笥，嬾起下簾帷。","怨坐空然燭，愁眠不解衣。","昨來頻夢見，夫婿莫應知。"]', '["日暮裁縫歇，深嫌氣力微。","纔能收篋笥，嬾起下簾帷。","怨坐空然燭，愁眠不解衣。","昨来頻梦见，夫婿莫應知。"]', '诗', 'shi', '', NULL, '閨情 王諲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27592e5e-c5f9-4826-abdd-d4da555ef66f', '十五夜觀燈', '十五夜观灯', 'c28c3c75-e5e0-48bc-a68d-4061acac97c4', '唐', '["暫得金吾夜，通看火樹春。","停車傍明月，走馬入紅塵。","妓雜歌偏勝，場移舞更新。","應須盡記取，說向不來人。"]', '["暫得金吾夜，通看火樹春。","停车傍明月，走马入紅塵。","妓杂歌偏勝，場移舞更新。","應須尽記取，说向不来人。"]', '诗', 'shi', '', NULL, '十五夜觀燈 王諲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('492011a3-1deb-45e8-a491-d80057e14f2b', '除夜', '除夜', 'c28c3c75-e5e0-48bc-a68d-4061acac97c4', '唐', '["今歲今宵盡，明年明日催。","寒隨一夜去，春逐五更來。","氣色空中改，容顏暗裏回。","風光人不覺，已著後園梅。"]', '["今歲今宵尽，明年明日催。","寒隨一夜去，春逐五更来。","氣色空中改，容顏暗裏回。","风光人不覺，已著後园梅。"]', '诗', 'shi', '', NULL, '除夜 王諲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bcb3ce0-c2e3-46e6-8e84-4979ad19e132', '聞漏', '闻漏', 'a30d10da-31e1-431c-90e2-5cdc4d8e5f1d', '唐', '["建禮含香處，重城待漏臣。","徐聞傳鳳詔，曉唱辨雞人。","銀箭殘將盡，銅壺漏更新。","催籌當午夜，移刻及三辰。","杳杳從天遠，泠泠出禁頻。","直疑殘漏曙，肅肅對鉤陳。"]', '["建禮含香处，重城待漏臣。","徐闻傳鳳詔，晓唱辨雞人。","銀箭殘將尽，銅壺漏更新。","催籌當午夜，移刻及三辰。","杳杳從天远，泠泠出禁頻。","直疑殘漏曙，肅肅对鉤陳。"]', '诗', 'shi', '', NULL, '聞漏 王岳靈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('703071c8-eb54-4f94-ad73-a20ed9b37969', '送沈芳謁李觀察求仕進', '送沈芳謁李观察求仕進', 'b8960780-f103-4089-bfda-212270a79f7c', '唐', '["往日長安路，歡遊不惜年。","爲貪盧女曲，用盡沈郎錢。","身老方投刺，途窮始著鞭。","猶聞有知己，此去不徒然。"]', '["往日长安路，歡游不惜年。","爲貪盧女曲，用尽沈郎錢。","身老方投刺，途窮始著鞭。","猶闻有知己，此去不徒然。"]', '诗', 'shi', '', NULL, '送沈芳謁李觀察求仕進 周萬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08f269ce-00ef-4850-9c43-ba832d916b5d', '古塞下曲', '古塞下曲', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["進軍飛狐北，窮寇勢將變。","日落沙塵昏，背河更一戰。","騂馬黃金勒，琱弓白羽箭。","射殺左賢王，歸奏未央殿。","欲言塞下事，天子不召見。","東出咸陽門，哀哀淚如霰。"]', '["進軍飞狐北，窮寇勢將变。","日落沙塵昏，背河更一戰。","騂马黄金勒，琱弓白羽箭。","射殺左賢王，归奏未央殿。","欲言塞下事，天子不召见。","东出咸陽门，哀哀泪如霰。"]', '诗', 'shi', '', NULL, '古塞下曲 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b679a77-603e-41c6-af12-2d19d36027e5', '燕歌行', '燕歌行', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["請君留楚調，聽我吟燕歌。","家在遼水頭，邊風意氣多。","出身爲漢將，正值戎未和。","雪中凌天山，冰上渡交河。","大小百餘戰，封侯竟蹉跎。","歸來灞陵下，故舊無相過。","雄劒委塵匣，空門垂雀羅。","玉簪還趙女，寶瑟付齊娥。","昔日不爲樂，時哉今奈何。"]', '["請君留楚調，听我吟燕歌。","家在遼水头，邊风意氣多。","出身爲漢將，正值戎未和。","雪中凌天山，冰上渡交河。","大小百餘戰，封侯竟蹉跎。","归来灞陵下，故旧無相過。","雄劒委塵匣，空门垂雀羅。","玉簪還趙女，寶瑟付齊娥。","昔日不爲乐，时哉今奈何。"]', '诗', 'shi', '', NULL, '燕歌行 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('288028bb-696b-41c1-b0f8-70445a11f6ab', '望太華贈盧司倉', '望太华贈盧司倉', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["行吏到西華，乃觀三峯壯。","削成元氣中，傑出天河上。","如有飛動色，不知青冥狀。","巨靈安在哉，厥跡猶可望。","方此顧行旅，末由飭仙裝。","葱蘢記星壇，明滅數雲嶂。","良友垂真契，宿心所微尚。","敢投歸山吟，霞徑一相訪。"]', '["行吏到西华，乃观三峯壯。","削成元氣中，傑出天河上。","如有飞动色，不知青冥狀。","巨靈安在哉，厥跡猶可望。","方此顧行旅，末由飭仙裝。","葱蘢記星壇，明滅數云嶂。","良友垂真契，宿心所微尚。","敢投归山吟，霞徑一相訪。"]', '诗', 'shi', '', NULL, '望太華贈盧司倉 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c3b235a-5cff-4fe7-9be3-4fe8bd4223d7', '贈鄭員外', '贈鄭員外', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["驄馬拂繡裳，按兵遼水陽。","西分鴈門騎，北逐樓煩王。","聞道五軍集，相邀百戰場。","風沙暗天起，虜騎森已行。","儒服揖諸將，雄謀吞大荒。","金門來見謁，朱紱生輝光。","數年侍御史，稍遷尚書郎。","人生志氣立，所貴功業昌。","何必守章句，終年事鉛黃。","同時獻賦客，尚在東陵傍。"]', '["驄马拂繡裳，按兵遼水陽。","西分鴈门騎，北逐楼煩王。","闻道五軍集，相邀百戰場。","风沙暗天起，虜騎森已行。","儒服揖諸將，雄謀吞大荒。","金门来见謁，朱紱生輝光。","數年侍御史，稍遷尚书郎。","人生志氣立，所貴功業昌。","何必守章句，終年事鉛黄。","同时獻賦客，尚在东陵傍。"]', '诗', 'shi', '', NULL, '贈鄭員外 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e97baf7-35e2-49e3-8031-262737c209a4', '贈房侍御', '贈房侍御', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["志士固不羈，與道常周旋。","進則天下仰，已之能晏然。","褐衣東府召，執簡南臺先。","雄義每特立，犯顏豈圖全。","謫居東南遠，逸氣吟芳荃。","適會寥廓趣，清波更夤緣。","扁舟入五湖，發纜洞庭前。","浩蕩臨海曲，迢遙濟江壖。","徵奇忽忘返，遇興將彌年。","乃悟范生智，足明漁父賢。","郡臨新安渚，佳賞此城偏。","日夕對層岫，雲霞映晴川。","閑居戀秋色，偃臥含貞堅。","倚伏聊自化，行藏互推遷。","君其振羽翮，歲晏將沖天。"]', '["志士固不羈，與道常周旋。","進則天下仰，已之能晏然。","褐衣东府召，執簡南台先。","雄義每特立，犯顏豈圖全。","謫居东南远，逸氣吟芳荃。","適會寥廓趣，清波更夤緣。","扁舟入五湖，發纜洞庭前。","浩蕩臨海曲，迢遙濟江壖。","徵奇忽忘返，遇兴將彌年。","乃悟范生智，足明漁父賢。","郡臨新安渚，佳賞此城偏。","日夕对層岫，云霞映晴川。","闲居戀秋色，偃臥含貞堅。","倚伏聊自化，行藏互推遷。","君其振羽翮，歲晏將沖天。"]', '诗', 'shi', '', NULL, '贈房侍御 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88ff36cb-5849-4f22-be1d-afb31aae2464', '晚出伊闕寄河南裴中丞', '晚出伊闕寄河南裴中丞', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["退無偃息資，進無當代策。","冉冉時將暮，坐爲周南客。","前登闕塞門，永眺伊城陌。","長川黯已空，千里寒氣白。","家本渭水西，異日同所適。","秉志師禽尚，微言祖莊易。","一辭林壑間，共繫風塵役。","交朋忽先進，天道何紛劇。","豈念嘉遯時，依依偶沮溺。"]', '["退無偃息資，進無當代策。","冉冉时將暮，坐爲周南客。","前登闕塞门，永眺伊城陌。","长川黯已空，千里寒氣白。","家本渭水西，異日同所適。","秉志師禽尚，微言祖莊易。","一辞林壑间，共繫风塵役。","交朋忽先進，天道何紛劇。","豈念嘉遯时，依依偶沮溺。"]', '诗', 'shi', '', NULL, '晚出伊闕寄河南裴中丞 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aeb1e03-bf9c-4f60-b55e-15bdba02e071', '送朱大出關', '送朱大出关', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["楚客西上書，十年不得意。","平生相知者，晚節心各異。","長揖五侯門，拂衣謝中貴。","丈夫多別離，各有四方事。","拔劒因高歌，蕭蕭北風至。","故人有斗酒，是夜共君醉。","努立強加餐，當年莫相棄。"]', '["楚客西上书，十年不得意。","平生相知者，晚節心各異。","长揖五侯门，拂衣謝中貴。","丈夫多別離，各有四方事。","拔劒因高歌，蕭蕭北风至。","故人有斗酒，是夜共君醉。","努立強加餐，當年莫相棄。"]', '诗', 'shi', '', NULL, '送朱大出關 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77a9db1a-843a-4f1e-893b-eff8de2e942f', '宿天竺寺', '宿天竺寺', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["松柏亂巖口，山西微徑通。","天開一峯見，宮闕生虛空。","正殿倚霞壁，千樓標石叢。","夜來猨鳥靜，鐘梵響雲中。","岑翠映湖月，泉聲亂溪風。","心超諸境外，了與懸解同。","明發唯改視，朝日長崖東。","湖色濃蕩漾，海光漸曈朦。","葛仙迹尚在，許氏道猶崇。","獨往古來事，幽懷期二公。"]', '["松柏亂巖口，山西微徑通。","天开一峯见，宮闕生虛空。","正殿倚霞壁，千楼標石叢。","夜来猨鸟静，鐘梵响云中。","岑翠映湖月，泉声亂溪风。","心超諸境外，了與懸解同。","明發唯改視，朝日长崖东。","湖色濃蕩漾，海光漸曈朦。","葛仙迹尚在，許氏道猶崇。","独往古来事，幽懷期二公。"]', '诗', 'shi', '', NULL, '宿天竺寺 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52798823-905e-4f6f-8ef6-31a922343af2', '出蕭關懷古', '出蕭关懷古', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["驅馬擊長劒，行役至蕭關。","悠悠五原上，永眺關河前。","北虜三十萬，此中常控弦。","秦城亙宇宙，漢帝理旌旃。","刁斗鳴不息，羽書日夜傳。","五軍計莫就，三策議空全。","大漠橫萬里，蕭條絕人煙。","孤城當瀚海，落日照[祁]連。","愴矣苦寒奏，懷哉式微篇。","更悲秦樓月，夜夜出胡天。"]', '["驱马擊长劒，行役至蕭关。","悠悠五原上，永眺关河前。","北虜三十万，此中常控弦。","秦城亙宇宙，漢帝理旌旃。","刁斗鳴不息，羽书日夜傳。","五軍計莫就，三策議空全。","大漠橫万里，蕭條絕人煙。","孤城當瀚海，落日照[祁]連。","愴矣苦寒奏，懷哉式微篇。","更悲秦楼月，夜夜出胡天。"]', '诗', 'shi', '', NULL, '出蕭關懷古 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c45ade-6b80-40a6-a621-3e157955d09a', '南楚懷古', '南楚懷古', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["南國久蕪漫，我來空鬱陶。","君看章華宮，處處生黃蒿。","但見陵與谷，豈知賢與豪。","精魂托古木，寶玉捐江臯。","倚棹下晴景，迴舟隨晚濤。","碧雲暮寥落，湖上秋天高。","往事那堪問，此心徒自勞。","獨餘湘水上，千載聞離騷。"]', '["南国久蕪漫，我来空鬱陶。","君看章华宮，处处生黄蒿。","但见陵與谷，豈知賢與豪。","精魂托古木，寶玉捐江臯。","倚棹下晴景，迴舟隨晚濤。","碧云暮寥落，湖上秋天高。","往事那堪问，此心徒自勞。","独餘湘水上，千載闻離騷。"]', '诗', 'shi', '', NULL, '南楚懷古 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('181c920a-cef9-4ffc-a3ba-febc3f6cf910', '經殺子谷', '經殺子谷', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["扶蘇秦帝子，舉代稱其賢。","百萬猶在握，可爭天下權。","束身就一劒，壯志皆棄捐。","塞下有遺跡，千齡人共傳。","疎蕪盡荒草，寂歷空寒煙。","到此盡垂淚，非我獨潸然。"]', '["扶蘇秦帝子，舉代稱其賢。","百万猶在握，可爭天下權。","束身就一劒，壯志皆棄捐。","塞下有遺跡，千齡人共傳。","疎蕪尽荒草，寂歷空寒煙。","到此尽垂泪，非我独潸然。"]', '诗', 'shi', '', NULL, '經殺子谷 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74cf4e44-0bf1-41af-8198-fe5d5c07f6d2', '早過臨淮', '早過臨淮', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["夜來三渚風，晨過臨淮島。","湖中海氣白，城上楚雲早。","鱗鱗魚浦帆，漭漭蘆洲草。","川路日浩蕩，惄焉心如擣。","且言任倚伏，何暇念枯槁。","范子名屢移，蘧公志常保。","古人去已久，此理今難道。"]', '["夜来三渚风，晨過臨淮島。","湖中海氣白，城上楚云早。","鱗鱗鱼浦帆，漭漭蘆洲草。","川路日浩蕩，惄焉心如擣。","且言任倚伏，何暇念枯槁。","范子名屢移，蘧公志常保。","古人去已久，此理今难道。"]', '诗', 'shi', '', NULL, '早過臨淮 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2642d673-aed4-4bf6-bb15-cbb312fcaaba', '乘潮至漁浦作', '乘潮至漁浦作', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["艤棹乘早潮，潮來如風雨。","樟臺忽已隱，界峯莫及覩。","崩騰心爲失，浩蕩目無主。","豗𢟸浪始聞，漾漾入魚浦。","雲景共澄霽，江山相吞吐。","偉哉造化工，此事從終古。","流沫誠足誡，商歌調易苦。","頗因忠信全，客心猶栩栩。"]', '["艤棹乘早潮，潮来如风雨。","樟台忽已隐，界峯莫及覩。","崩腾心爲失，浩蕩目無主。","豗𢟸浪始闻，漾漾入鱼浦。","云景共澄霽，江山相吞吐。","偉哉造化工，此事從終古。","流沫誠足誡，商歌調易苦。","頗因忠信全，客心猶栩栩。"]', '诗', 'shi', '', NULL, '乘潮至漁浦作 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4a21dc1-a089-4f9b-be25-fa0e4e2ce12b', '秋山夕興', '秋山夕兴', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["山月松篠下，月明山景鮮。","聊爲高秋酌，復此清夜弦。","晤語方獲志，栖心亦彌年。","尚言興未逸，更理逍遙篇。"]', '["山月松篠下，月明山景鲜。","聊爲高秋酌，复此清夜弦。","晤語方獲志，栖心亦彌年。","尚言兴未逸，更理逍遙篇。"]', '诗', 'shi', '', NULL, '秋山夕興 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01e8361e-5f66-487f-8291-d4075a3f5808', '送集賢學士伊闕史少府敕放歸江東覲省', '送集賢学士伊闕史少府敕放归江东覲省', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["墨客鍾張侶，材高吳越珍。","千門來謁帝，駟馬去榮親。","吏邑沿清洛，鄉山指白蘋。","歸期應不遠，當及未央春。"]', '["墨客鍾張侶，材高吳越珍。","千门来謁帝，駟马去榮親。","吏邑沿清洛，乡山指白蘋。","归期應不远，當及未央春。"]', '诗', 'shi', '', NULL, '送集賢學士伊闕史少府敕放歸江東覲省 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b4bc0ca-877b-4720-897d-5df888c3cead', '送金卿歸新羅', '送金卿归新羅', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["奉義朝中國，殊恩及遠臣。","鄉心遙渡海，客路再經春。","落日誰同望，孤舟獨可親。","拂波銜木鳥，偶宿泣珠人。","禮樂夷風變，衣冠漢制新。","青雲已干呂，知汝重來賓。"]', '["奉義朝中国，殊恩及远臣。","乡心遙渡海，客路再經春。","落日誰同望，孤舟独可親。","拂波銜木鸟，偶宿泣珠人。","禮乐夷风变，衣冠漢制新。","青云已干呂，知汝重来賓。"]', '诗', 'shi', '', NULL, '送金卿歸新羅 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca85e40d-6a68-4409-b6de-7b11f643606a', '柳陌聽早鶯', '柳陌听早鶯', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["忽來枝上囀，還似谷中聲。","乍使香閨靜，偏傷遠客情。","間關難辨處，斷續若頻驚。","玉勒留將久，青樓夢不成。","千門候曉發，萬井報春生。","徒有知音賞，慙非臯鶴鳴。"]', '["忽来枝上囀，還似谷中声。","乍使香閨静，偏傷远客情。","间关难辨处，斷續若頻驚。","玉勒留將久，青楼梦不成。","千门候晓發，万井報春生。","徒有知音賞，慙非臯鹤鳴。"]', '诗', 'shi', '', NULL, '柳陌聽早鶯 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eac7283-4608-4d88-b0cb-ee7411c518c3', '逢雪宿芙蓉山主人', '逢雪宿芙蓉山主人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["日暮蒼山遠，天寒白屋貧。","柴門聞犬吠，風雪夜歸人。"]', '["日暮蒼山远，天寒白屋貧。","柴门闻犬吠，风雪夜归人。"]', '诗', 'shi', '', NULL, '逢雪宿芙蓉山主人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c301003b-b4ff-43b3-9da0-05b10a9058a6', '送張起崔載華之閩中', '送張起崔載华之閩中', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["朝無寒士達，家在舊山貧。","相送天涯裏，憐君更遠人。"]', '["朝無寒士達，家在旧山貧。","相送天涯裏，怜君更远人。"]', '诗', 'shi', '', NULL, '送張起崔載華之閩中 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b197c18b-b43e-413a-b016-8b6c599de9d0', '贈秦系徵君', '贈秦系徵君', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["羣公誰讓位，五柳獨知貧。","惆悵青山路，煙霞老此人。"]', '["羣公誰讓位，五柳独知貧。","惆悵青山路，煙霞老此人。"]', '诗', 'shi', '', NULL, '贈秦系徵君 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61660bb7-421b-49fe-b7c1-2e48c81dec48', '秦系頃以家事獲謗因出舊山每荷觀察崔公見知欲歸未遂感其流寓詩以贈之', '秦系頃以家事獲謗因出旧山每荷观察崔公见知欲归未遂感其流寓诗以贈之', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["初迷武陵路，復出孟嘗門。","迴首江南岸，青山與舊恩。"]', '["初迷武陵路，复出孟嘗门。","迴首江南岸，青山與旧恩。"]', '诗', 'shi', '', NULL, '秦系頃以家事獲謗因出舊山每荷觀察崔公見知欲歸未遂感其流寓詩以贈之 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('393cf16f-f815-4ddb-b5ec-a9133286c25f', '夜中對雪贈秦系時秦初與謝氏離婚謝氏在越', '夜中对雪贈秦系时秦初與謝氏離婚謝氏在越', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["月明花滿地，君自憶山陰。","誰遣因風起，紛紛亂此心。"]', '["月明花满地，君自憶山陰。","誰遣因风起，紛紛亂此心。"]', '诗', 'shi', '', NULL, '夜中對雪贈秦系時秦初與謝氏離婚謝氏在越 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48920104-8336-4488-8f02-08070809571f', '湘妃', '湘妃', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["帝子不可見，秋風來暮思。","嬋娟湘江月，千載空蛾眉。"]', '["帝子不可见，秋风来暮思。","嬋娟湘江月，千載空蛾眉。"]', '诗', 'shi', '', NULL, '湘妃 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('506ffe5f-35eb-4cd1-b50a-de2401932b65', '斑竹', '斑竹', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["蒼梧千載後，斑竹對湘沅。","欲識湘妃怨，枝枝滿淚痕。"]', '["蒼梧千載後，斑竹对湘沅。","欲識湘妃怨，枝枝满泪痕。"]', '诗', 'shi', '', NULL, '斑竹 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78f444fc-fa03-47bc-aab9-e48a544a6e20', '春草宮懷古', '春草宮懷古', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["君王不可見，芳草舊宮春。","猶帶羅裙色，青青向楚人。"]', '["君王不可见，芳草旧宮春。","猶带羅裙色，青青向楚人。"]', '诗', 'shi', '', NULL, '春草宮懷古 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce4c0235-dbbf-49ba-9014-f7a8e24d3399', '正朝覽鏡作', '正朝覽镜作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["憔悴逢新歲，茅扉見舊春。","朝來明鏡裏，不忍白頭人。"]', '["憔悴逢新歲，茅扉见旧春。","朝来明镜裏，不忍白头人。"]', '诗', 'shi', '', NULL, '正朝覽鏡作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d302830-ff62-41d8-a918-a0d810b8f62b', '瓜洲道中送李端公南渡後歸揚州道中寄', '瓜洲道中送李端公南渡後归揚州道中寄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["片帆何處去，匹馬獨歸遲。","惆悵江南北，青山欲暮時。"]', '["片帆何处去，匹马独归遲。","惆悵江南北，青山欲暮时。"]', '诗', 'shi', '', NULL, '瓜洲道中送李端公南渡後歸揚州道中寄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('539e03bc-d6e5-4053-bf4b-6ea177c61ffa', '送張十八歸桐廬', '送張十八归桐廬', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["歸人乘野艇，帶月過江村。","正落寒潮水，相隨夜到門。"]', '["归人乘野艇，带月過江村。","正落寒潮水，相隨夜到门。"]', '诗', 'shi', '', NULL, '送張十八歸桐廬 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fe29a18-8fa8-455e-83d7-ddb29a625ce0', '過白鶴觀尋岑秀才不遇', '過白鹤观尋岑秀才不遇', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["不知方外客，何事鎖空房。","應向桃源裏，教他喚阮郎。"]', '["不知方外客，何事鎖空房。","應向桃源裏，教他喚阮郎。"]', '诗', 'shi', '', NULL, '過白鶴觀尋岑秀才不遇 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72aab9ef-65a9-4a8a-b36b-61932c09ce85', '聽彈琴', '听彈琴', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["泠泠七絲上，靜聽松風寒。","古調雖自愛，今人多不彈。"]', '["泠泠七絲上，静听松风寒。","古調雖自愛，今人多不彈。"]', '诗', 'shi', '', NULL, '聽彈琴 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3ee12cc-1478-41a5-9cdc-f82a70fa90fb', '遊南園偶見在陰牆下葵因以成詠', '游南园偶见在陰牆下葵因以成詠', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["此地常無日，青青獨在陰。","太陽偏不及，非是未傾心。"]', '["此地常無日，青青独在陰。","太陽偏不及，非是未傾心。"]', '诗', 'shi', '', NULL, '遊南園偶見在陰牆下葵因以成詠 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d2bec9-272c-4d5e-aa67-548ff92c576d', '入百丈澗見桃花晚開', '入百丈澗见桃花晚开', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["百丈深澗裏，過時花欲妍。","應緣地勢下，遂使春風偏。"]', '["百丈深澗裏，過时花欲妍。","應緣地勢下，遂使春风偏。"]', '诗', 'shi', '', NULL, '入百丈澗見桃花晚開 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0bfa4bd-c34d-4630-a422-e01102755400', '送子壻崔真甫李穆往揚州四首 一', '送子壻崔真甫李穆往揚州四首 一', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["渡口發梅花，山中動泉脉。","蕪城春草生，君作揚州客。"]', '["渡口發梅花，山中动泉脉。","蕪城春草生，君作揚州客。"]', '诗', 'shi', '', NULL, '送子壻崔真甫李穆往揚州四首 一 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed49fd88-07ba-41d6-b957-c983633b2a06', '送子壻崔真甫李穆往揚州四首 二', '送子壻崔真甫李穆往揚州四首 二', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["半邏鶯滿樹，新年人獨還。","落花逐流水，共到茱萸灣。"]', '["半邏鶯满樹，新年人独還。","落花逐流水，共到茱萸灣。"]', '诗', 'shi', '', NULL, '送子壻崔真甫李穆往揚州四首 二 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7980b3d6-850a-4d8c-a4c0-890581f453d6', '送子壻崔真甫李穆往揚州四首 三', '送子壻崔真甫李穆往揚州四首 三', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["雁還空渚在，人去落潮翻。","臨水獨揮手，殘陽歸掩門。"]', '["雁還空渚在，人去落潮翻。","臨水独揮手，殘陽归掩门。"]', '诗', 'shi', '', NULL, '送子壻崔真甫李穆往揚州四首 三 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('359da2a4-ee32-42bf-ac5c-a397d47446a9', '送子壻崔真甫李穆往揚州四首 四', '送子壻崔真甫李穆往揚州四首 四', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["狎鳥攜稚子，釣魚終老身。","殷勤囑歸客，莫話桃源人。"]', '["狎鸟携稚子，釣鱼終老身。","殷勤囑归客，莫話桃源人。"]', '诗', 'shi', '', NULL, '送子壻崔真甫李穆往揚州四首 四 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40e43965-68d5-4638-ac93-4561874374de', '寄龍山道士許法稜', '寄龙山道士許法稜', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["悠悠白雲裏，獨住青山客。","林下晝焚香，桂花同寂寂。"]', '["悠悠白云裏，独住青山客。","林下晝焚香，桂花同寂寂。"]', '诗', 'shi', '', NULL, '寄龍山道士許法稜 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c26445b5-a433-4cd7-9020-435866b845f9', '送方外上人', '送方外上人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["孤雲將野鶴，豈向人間住。","莫買沃洲山，時人已知處。"]', '["孤云將野鹤，豈向人间住。","莫買沃洲山，时人已知处。"]', '诗', 'shi', '', NULL, '送方外上人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a746d1f0-a72c-44d2-8b1c-c5c990749257', '送靈澈上人', '送靈澈上人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["蒼蒼竹林寺，杳杳鐘聲晚。","荷笠帶夕陽，青山獨歸遠。"]', '["蒼蒼竹林寺，杳杳鐘声晚。","荷笠带夕陽，青山独归远。"]', '诗', 'shi', '', NULL, '送靈澈上人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e155e372-4f5a-4b99-8944-9143800a81f0', '茱萸灣北荅崔載華問', '茱萸灣北荅崔載华问', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["荒涼野店絕，迢遰人煙遠。","蒼蒼古木中，多是隋家苑。"]', '["荒涼野店絕，迢遰人煙远。","蒼蒼古木中，多是隋家苑。"]', '诗', 'shi', '', NULL, '茱萸灣北荅崔載華問 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d1a5800-b30e-4ebe-b0ed-6f4557de3b05', '赴楚州次自田途中阻淺問張南史', '赴楚州次自田途中阻淺问張南史', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["楚城今近遠，積靄寒塘暮。","水淺舟且遲，淮潮至何處。"]', '["楚城今近远，積靄寒塘暮。","水淺舟且遲，淮潮至何处。"]', '诗', 'shi', '', NULL, '赴楚州次自田途中阻淺問張南史 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('103e17e1-7535-448f-8fb0-1060f02881c4', '江中對月', '江中对月', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["空洲夕煙斂，望月秋江裏。","歷歷沙上人，月中孤渡水。"]', '["空洲夕煙斂，望月秋江裏。","歷歷沙上人，月中孤渡水。"]', '诗', 'shi', '', NULL, '江中對月 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90c3eac-cb5c-4664-bebc-2463efe084a1', '碧澗別墅喜皇甫侍御相訪', '碧澗別墅喜皇甫侍御相訪', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["荒村帶返照，落葉亂紛紛。","古路無行客，寒山獨見君。","野橋經雨斷，澗水向田分。","不爲憐同病，何人到白雲。"]', '["荒村带返照，落葉亂紛紛。","古路無行客，寒山独见君。","野橋經雨斷，澗水向田分。","不爲怜同病，何人到白云。"]', '诗', 'shi', '', NULL, '碧澗別墅喜皇甫侍御相訪 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ae2f0eb-a7d3-4adf-8f0a-5e65b693db70', '初到碧澗招明契上人', '初到碧澗招明契上人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["漸老知身累，初寒曝背眠。","白雲留永日，黃葉減餘年。","猨護窗前樹，泉澆谷後田。","沃洲能共隱，不用道林錢。"]', '["漸老知身累，初寒曝背眠。","白云留永日，黄葉減餘年。","猨護窗前樹，泉澆谷後田。","沃洲能共隐，不用道林錢。"]', '诗', 'shi', '', NULL, '初到碧澗招明契上人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('901dfaa4-18f1-41b4-9edb-ccbac8ee3081', '送少微上人遊天台', '送少微上人游天台', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["石橋人不到，獨往更迢迢。","乞食山家少，尋鐘野路遙。","松門風自埽，瀑布雪難消。","秋夜聞清梵，餘音逐海潮。"]', '["石橋人不到，独往更迢迢。","乞食山家少，尋鐘野路遙。","松门风自埽，瀑布雪难消。","秋夜闻清梵，餘音逐海潮。"]', '诗', 'shi', '', NULL, '送少微上人遊天台 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82fd73c6-4fa4-4858-a4ee-46069dc81ff4', '却歸睦州至七里灘下作', '却归睦州至七里灘下作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["南歸猶謫宦，獨上子陵灘。","江樹臨洲晚，沙禽對水寒。","山開斜照在，石淺亂流難。","惆悵梅花發，年年此地看。"]', '["南归猶謫宦，独上子陵灘。","江樹臨洲晚，沙禽对水寒。","山开斜照在，石淺亂流难。","惆悵梅花發，年年此地看。"]', '诗', 'shi', '', NULL, '却歸睦州至七里灘下作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c020d17-e4cd-4c03-8f61-07f1cff2c88e', '對酒寄嚴維', '对酒寄嚴維', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["陋巷喜陽和，衰顏對酒歌。","嬾從華髮亂，閑任白雲多。","郡簡容垂釣，家貧學弄梭。","門前七里瀨，早晚子陵過。"]', '["陋巷喜陽和，衰顏对酒歌。","嬾從华髮亂，闲任白云多。","郡簡容垂釣，家貧学弄梭。","门前七里瀨，早晚子陵過。"]', '诗', 'shi', '', NULL, '對酒寄嚴維 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6556f501-f5b9-4353-bde2-75ec0e1bb616', '新年作', '新年作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["鄉心新歲切，天畔獨潸然。","老至居人下，春歸在客先。","嶺猨同旦暮，江柳共風煙。","已是長沙傅，從今又幾年。"]', '["乡心新歲切，天畔独潸然。","老至居人下，春归在客先。","嶺猨同旦暮，江柳共风煙。","已是长沙傅，從今又幾年。"]', '诗', 'shi', '', NULL, '新年作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66162898-981e-4b88-842d-d6bf46fc9b92', '朱放自杭州與故里相使君立碑回因以奉簡吏部楊侍郎製文', '朱放自杭州與故里相使君立碑回因以奉簡吏部楊侍郎製文', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["片石羊公後，淒涼江水濱。","好辭千古事，墮淚萬家人。","鵩集占書久，鸞回刻篆新。","不堪相顧恨，文字日生塵。"]', '["片石羊公後，淒涼江水濱。","好辞千古事，墮泪万家人。","鵩集占书久，鸾回刻篆新。","不堪相顧恨，文字日生塵。"]', '诗', 'shi', '', NULL, '朱放自杭州與故里相使君立碑回因以奉簡吏部楊侍郎製文 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1784c06f-7cdd-4214-a558-fc0bf4ad50bd', '送宣尊師醮畢歸越', '送宣尊師醮畢归越', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["吹簫江上晚，惆悵別茅君。","踏火能飛雪，登刀入白雲。","晨香長日在，夜磬滿山聞。","揮手桐溪路，無情水亦分。"]', '["吹簫江上晚，惆悵別茅君。","踏火能飞雪，登刀入白云。","晨香长日在，夜磬满山闻。","揮手桐溪路，無情水亦分。"]', '诗', 'shi', '', NULL, '送宣尊師醮畢歸越 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dbdaf0e-f20f-44db-a6a1-335807ba034c', '送裴使君赴荆南充行軍司馬', '送裴使君赴荆南充行軍司马', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["盛府南門寄，前程積水中。","月明臨夏口，山晚望巴東。","故節辭江郡，寒笳發渚宮。","漢川風景好，遙羨逐羊公。"]', '["盛府南门寄，前程積水中。","月明臨夏口，山晚望巴东。","故節辞江郡，寒笳發渚宮。","漢川风景好，遙羨逐羊公。"]', '诗', 'shi', '', NULL, '送裴使君赴荆南充行軍司馬 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9309c4dd-fc94-495e-a69c-74a6d70d8812', '送裴郎中貶吉州', '送裴郎中貶吉州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["亂軍交白刃，一騎出黃塵。","漢節同歸闕，江帆共逐臣。","猨愁歧路晚，梅作異方春。","知己酇侯在，應憐脫粟人。"]', '["亂軍交白刃，一騎出黄塵。","漢節同归闕，江帆共逐臣。","猨愁歧路晚，梅作異方春。","知己酇侯在，應怜脫粟人。"]', '诗', 'shi', '', NULL, '送裴郎中貶吉州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a19fb3e-67b4-42a3-9074-e26aaff1340b', '酬皇甫侍御見寄時前相國姑臧公初臨郡', '酬皇甫侍御见寄时前相国姑臧公初臨郡', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["離別江南北，汀洲葉再黃。","路遙雲共水，砧迥月如霜。","歲儉依仁政，年衰憶故鄉。","佇看宣室召，漢法倚張綱。"]', '["離別江南北，汀洲葉再黄。","路遙云共水，砧迥月如霜。","歲儉依仁政，年衰憶故乡。","佇看宣室召，漢法倚張綱。"]', '诗', 'shi', '', NULL, '酬皇甫侍御見寄時前相國姑臧公初臨郡 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('500b3fa0-d2e8-4e1f-8242-da9be65d86e6', '月下呈章秀才', '月下呈章秀才', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["自古悲搖落，誰人奈此何。","夜蛬偏傍枕，寒鳥數移柯。","向老三年謫，當秋百感多。","家貧惟好月，空媿子猷過。"]', '["自古悲搖落，誰人奈此何。","夜蛬偏傍枕，寒鸟數移柯。","向老三年謫，當秋百感多。","家貧惟好月，空媿子猷過。"]', '诗', 'shi', '', NULL, '月下呈章秀才 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40f57a14-885c-4db2-84f5-fc635d723e3c', '酬張夏', '酬張夏', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["幾歲依窮海，頹年惜故陰。","劍寒空有氣，松老欲無心。","玩雪勞相訪，看山正獨吟。","孤舟且莫去，前路水雲深。"]', '["幾歲依窮海，頹年惜故陰。","劍寒空有氣，松老欲無心。","玩雪勞相訪，看山正独吟。","孤舟且莫去，前路水云深。"]', '诗', 'shi', '', NULL, '酬張夏 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba36b449-c5cc-4693-a2b9-3dd0abaf9f23', '送李使君貶連州', '送李使君貶連州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["獨過長沙去，誰堪此路愁。","秋風散千騎，寒雨泊孤舟。","賈誼辭明主，蕭何識故侯。","漢廷當自召，湘水但空流。"]', '["独過长沙去，誰堪此路愁。","秋风散千騎，寒雨泊孤舟。","賈誼辞明主，蕭何識故侯。","漢廷當自召，湘水但空流。"]', '诗', 'shi', '', NULL, '送李使君貶連州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff8c632e-2004-45cf-b225-535b5a49b4b8', '秋夜北山精舍觀體如師梵', '秋夜北山精舍观體如師梵', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["焚香奏仙唄，向夕遍空山。","清切兼秋遠，威儀對月閑。","靜分巖響荅，散逐海潮還。","幸得風吹去，隨人到世間。"]', '["焚香奏仙唄，向夕遍空山。","清切兼秋远，威儀对月闲。","静分巖响荅，散逐海潮還。","幸得风吹去，隨人到世间。"]', '诗', 'shi', '', NULL, '秋夜北山精舍觀體如師梵 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3f5b941-64bd-4a86-9537-3c57eb1def2f', '酬張夏雪夜赴州訪別途中苦寒作', '酬張夏雪夜赴州訪別途中苦寒作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["扁舟乘興客，不憚苦寒行。","晚暮相依分，江潮欲別情。","水聲冰下咽，砂路雪中平。","舊劒鋒鋩盡，應嫌贈脫輕。"]', '["扁舟乘兴客，不憚苦寒行。","晚暮相依分，江潮欲別情。","水声冰下咽，砂路雪中平。","旧劒鋒鋩尽，應嫌贈脫轻。"]', '诗', 'shi', '', NULL, '酬張夏雪夜赴州訪別途中苦寒作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('007496dc-0513-4edf-ad52-800b5b465d04', '尋洪尊師不遇', '尋洪尊師不遇', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["古木無人地，來尋羽客家。","道書堆玉案，仙帔疊青霞。","鶴老難知歲，梅寒未作花。"]', '["古木無人地，来尋羽客家。","道书堆玉案，仙帔叠青霞。","鹤老难知歲，梅寒未作花。"]', '诗', 'shi', '', NULL, '尋洪尊師不遇 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ece17b4-ac43-4bfe-9f47-d7072f4f17d0', '喜鮑禪師自龍山至', '喜鲍禪師自龙山至', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["故居何日下，春草欲芊芊。","猶對山中月，誰聽石上泉。","猨聲知後夜，花發見流年。","杖錫閑來往，無心到處禪。"]', '["故居何日下，春草欲芊芊。","猶对山中月，誰听石上泉。","猨声知後夜，花發见流年。","杖錫闲来往，無心到处禪。"]', '诗', 'shi', '', NULL, '喜鮑禪師自龍山至 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aad950ba-0815-4343-9925-1507506ff277', '送方外上人之常州依蕭使君', '送方外上人之常州依蕭使君', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["宰臣思得度，鷗鳥戀爲羣。","遠客迴飛錫，空山臥白雲。","夕陽孤艇去，秋水兩溪分。","歸共臨川史，同翻貝葉文。"]', '["宰臣思得度，鷗鸟戀爲羣。","远客迴飞錫，空山臥白云。","夕陽孤艇去，秋水兩溪分。","归共臨川史，同翻貝葉文。"]', '诗', 'shi', '', NULL, '送方外上人之常州依蕭使君 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9a3335c-b94a-4ba3-8dfc-9f832fd03991', '宿北山禪寺蘭若', '宿北山禪寺蘭若', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["上方鳴夕磬，林下一僧還。","密行傳人少，禪心對虎閑。","青松臨古路，白月滿寒山。","舊識窗前桂，經霜更待攀。"]', '["上方鳴夕磬，林下一僧還。","密行傳人少，禪心对虎闲。","青松臨古路，白月满寒山。","旧識窗前桂，經霜更待攀。"]', '诗', 'shi', '', NULL, '宿北山禪寺蘭若 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c592c1de-0476-4ab0-9dad-1a4940b1f8ec', '赴新安別梁侍郎', '赴新安別梁侍郎', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["新安君莫問，此路水雲深。","江海無行跡，孤舟何處尋。","青山空向淚，白月豈知心。","縱有餘生在，終傷老病侵。"]', '["新安君莫问，此路水云深。","江海無行跡，孤舟何处尋。","青山空向泪，白月豈知心。","縱有餘生在，終傷老病侵。"]', '诗', 'shi', '', NULL, '赴新安別梁侍郎 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7acb860f-1938-4345-84f3-ae7ae66736b5', '江州留別薛六柳八二員外', '江州留別薛六柳八二員外', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["江海相逢少，東南別處長。","獨行風嫋嫋，相去水茫茫。","白首辭同舍，青山背故鄉。","離心與潮信，每日到潯陽。"]', '["江海相逢少，东南別处长。","独行风嫋嫋，相去水茫茫。","白首辞同舍，青山背故乡。","離心與潮信，每日到潯陽。"]', '诗', 'shi', '', NULL, '江州留別薛六柳八二員外 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baae35ca-3c78-41aa-b9c4-61987704e1ff', '和州留別穆郎中', '和州留別穆郎中', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["播遷悲遠道，搖落感衰容。","今日猶多難，何年更此逢。","世交黃葉散，鄉路白雲重。","明發看煙樹，唯聞江北鐘。"]', '["播遷悲远道，搖落感衰容。","今日猶多难，何年更此逢。","世交黄葉散，乡路白云重。","明發看煙樹，唯闻江北鐘。"]', '诗', 'shi', '', NULL, '和州留別穆郎中 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baefd967-c1a8-4cef-90a0-f00eced22a78', '和州送人歸復郢', '和州送人归复郢', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["因家漢水曲，相送掩柴扉。","故郢生秋草，寒江澹落暉。","綠林行客少，赤壁住人稀。","獨過潯陽去，潮歸人不歸。"]', '["因家漢水曲，相送掩柴扉。","故郢生秋草，寒江澹落暉。","綠林行客少，赤壁住人稀。","独過潯陽去，潮归人不归。"]', '诗', 'shi', '', NULL, '和州送人歸復郢 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a48ee95-6297-47b9-857d-159d7de82277', '送金昌宗歸錢塘', '送金昌宗归錢塘', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["新家浙江上，獨泛落潮歸。","秋水照華髮，涼風生褐衣。","柴門嘶馬少，藜杖拜人稀。","惟有陶潛柳，蕭條對掩扉。"]', '["新家浙江上，独泛落潮归。","秋水照华髮，涼风生褐衣。","柴门嘶马少，藜杖拜人稀。","惟有陶潛柳，蕭條对掩扉。"]', '诗', 'shi', '', NULL, '送金昌宗歸錢塘 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('656605b0-217d-4a61-ae1a-9641450b0021', '酬張夏別後道中見寄', '酬張夏別後道中见寄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["離羣方歲晏，謫宦在天涯。","暮雪同行少，寒潮欲上遲。","海鷗知吏傲，砂鶴見人衰。","只畏生秋草，西歸亦未期。"]', '["離羣方歲晏，謫宦在天涯。","暮雪同行少，寒潮欲上遲。","海鷗知吏傲，砂鹤见人衰。","只畏生秋草，西归亦未期。"]', '诗', 'shi', '', NULL, '酬張夏別後道中見寄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b8862d6-a78c-49f7-ae59-074505a6e4f9', '新安奉送穆諭德歸朝賦得行字', '新安奉送穆諭德归朝賦得行字', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["九重宣室召，萬里建溪行。","事直皇天在，歸遲白髮生。","用材身復起，覩聖眼猶明。","離別寒江上，潺湲若有情。"]', '["九重宣室召，万里建溪行。","事直皇天在，归遲白髮生。","用材身复起，覩聖眼猶明。","離別寒江上，潺湲若有情。"]', '诗', 'shi', '', NULL, '新安奉送穆諭德歸朝賦得行字 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e50e67ef-bea9-4b41-b7af-76b47b35d864', '偶然作', '偶然作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["野寺長依止，田家或往還。","老農開古地，夕鳥入寒山。","書劒身同廢，煙霞吏共閑。","豈能將白髮，扶杖出人間。"]', '["野寺长依止，田家或往還。","老農开古地，夕鸟入寒山。","书劒身同廢，煙霞吏共闲。","豈能將白髮，扶杖出人间。"]', '诗', 'shi', '', NULL, '偶然作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddca5ffd-acbb-4325-9941-db2bb6e78493', '送州人孫沅自本州却歸句章新營所居', '送州人孫沅自本州却归句章新營所居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["故里歸成客，新家去未安。","詩書滿蝸舍，征稅及漁竿。","火種山田薄，星居海島寒。","憐君不得已，步步別離難。"]', '["故里归成客，新家去未安。","诗书满蝸舍，征稅及漁竿。","火種山田薄，星居海島寒。","怜君不得已，步步別離难。"]', '诗', 'shi', '', NULL, '送州人孫沅自本州却歸句章新營所居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6c2e24e-3811-489a-b120-715922b45ea5', '送李員外使還蘇州兼呈前袁州李使君賦得長字袁州即員外之從兄', '送李員外使還蘇州兼呈前袁州李使君賦得长字袁州即員外之從兄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["別離共成怨，衰老更難忘。","夜月留同舍，秋風在遠鄉。","朱弦徐向燭，白髮強臨觴。","歸獻西陵作，誰知此路長。"]', '["別離共成怨，衰老更难忘。","夜月留同舍，秋风在远乡。","朱弦徐向燭，白髮強臨觴。","归獻西陵作，誰知此路长。"]', '诗', 'shi', '', NULL, '送李員外使還蘇州兼呈前袁州李使君賦得長字袁州即員外之從兄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecd6acba-1f51-4fb0-96a4-bfefd3cfc1d3', '酬李員外從崔錄事載華宿三河戍先見寄', '酬李員外從崔錄事載华宿三河戍先见寄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["寒江鳴石瀨，歸客夜初分。","人語空山答，猨聲獨戍聞。","遲來朝及暮，愁去水連雲。","歲晚心誰在，青山見此君。"]', '["寒江鳴石瀨，归客夜初分。","人語空山答，猨声独戍闻。","遲来朝及暮，愁去水連云。","歲晚心誰在，青山见此君。"]', '诗', 'shi', '', NULL, '酬李員外從崔錄事載華宿三河戍先見寄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f68a9c5-b1af-4a2a-ab15-48f298295bd4', '見秦系離婚後出山居作', '见秦系離婚後出山居作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["豈知偕老重，垂老絕良姻。","郗氏誠難負，朱家自媿貧。","綻衣留欲故，織錦罷經春。","何況蘼蕪綠，空山不見人。"]', '["豈知偕老重，垂老絕良姻。","郗氏誠难負，朱家自媿貧。","綻衣留欲故，织錦罷經春。","何況蘼蕪綠，空山不见人。"]', '诗', 'shi', '', NULL, '見秦系離婚後出山居作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b2176f6-c5ae-4dc4-aa48-493d350e4a0b', '酬秦系', '酬秦系', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["鶴書猶未至，那出白雲來。","舊路經年別，寒潮每日迴。","家空歸海燕，人老發江梅。","最憶門前柳，閑居手自栽。"]', '["鹤书猶未至，那出白云来。","旧路經年別，寒潮每日迴。","家空归海燕，人老發江梅。","最憶门前柳，闲居手自栽。"]', '诗', 'shi', '', NULL, '酬秦系 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8146e0df-0584-4683-bf5b-219ef3ed15aa', '歲日作', '歲日作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["建寅迴北斗，看曆占春風。","律變滄江外，年加白髮中。","春衣試稚子，壽酒勸衰翁。","今日陽和發，榮枯豈不同。"]', '["建寅迴北斗，看曆占春风。","律变滄江外，年加白髮中。","春衣試稚子，壽酒勸衰翁。","今日陽和發，榮枯豈不同。"]', '诗', 'shi', '', NULL, '歲日作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a0014e4-8a7d-4be0-84aa-e23782b7673b', '題元錄事開元所居', '題元錄事开元所居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["幽居蘿薜情，高臥紀綱行。","鳥散秋鷹下，人閑春草生。","冒風歸野寺，收印出山城。","今日新安郡，因君水更清。"]', '["幽居蘿薜情，高臥紀綱行。","鸟散秋鷹下，人闲春草生。","冒风归野寺，收印出山城。","今日新安郡，因君水更清。"]', '诗', 'shi', '', NULL, '題元錄事開元所居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fcf3c99-a06e-4ab3-a062-3ad8cf69d2a8', '送崔載華張起之閩中', '送崔載华張起之閩中', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["不識閩中路，遙知別後心。","猨聲入嶺切，鳥道問人深。","旅食過夷落，方言會越音。","西征開幕府，早晚用陳琳。"]', '["不識閩中路，遙知別後心。","猨声入嶺切，鸟道问人深。","旅食過夷落，方言會越音。","西征开幕府，早晚用陳琳。"]', '诗', 'shi', '', NULL, '送崔載華張起之閩中 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7ec5352-5194-4a4c-81cf-54e9914b3e16', '送張司直赴嶺南謁張尚書', '送張司直赴嶺南謁張尚书', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["番禺萬里路，遠客片帆過。","盛府依橫海，荒祠拜伏波。","人經秋瘴變，鳥墜火雲多。","誠憚炎洲裏，無如一顧何。"]', '["番禺万里路，远客片帆過。","盛府依橫海，荒祠拜伏波。","人經秋瘴变，鸟墜火云多。","誠憚炎洲裏，無如一顧何。"]', '诗', 'shi', '', NULL, '送張司直赴嶺南謁張尚書 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efcb8205-baf2-4bd3-9179-750206d357a7', '寄會稽公徐侍郎', '寄會稽公徐侍郎', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["搖落淮南葉，秋風想越吟。","皺枚入梁苑，逸少在山陰。","老鶴無衰貌，寒松有本心。","聖朝難稅駕，惆悵白雲深。"]', '["搖落淮南葉，秋风想越吟。","皺枚入梁苑，逸少在山陰。","老鹤無衰貌，寒松有本心。","聖朝难稅駕，惆悵白云深。"]', '诗', 'shi', '', NULL, '寄會稽公徐侍郎 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b53927c-8b42-4e12-84af-4f5ca0b34494', '送朱山人放越州賊退後歸山陰別業', '送朱山人放越州賊退後归山陰別業', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["越州初罷戰，江上送歸橈。","南渡無來客，西陵自落潮。","空城垂故柳，舊業廢春苗。","閭里相逢少，鶯花共寂寥。"]', '["越州初罷戰，江上送归橈。","南渡無来客，西陵自落潮。","空城垂故柳，旧業廢春苗。","閭里相逢少，鶯花共寂寥。"]', '诗', 'shi', '', NULL, '送朱山人放越州賊退後歸山陰別業 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3e110ac-074c-4011-b36a-c6f1a2f3b55e', '秋夜肅公房喜普門上人自陽羨山至', '秋夜肅公房喜普门上人自陽羨山至', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["山棲久不見，林下偶同遊。","早晚來香積，何人住沃洲。","寒禽驚後夜，古木帶高秋。","却入千峰去，孤雲不可留。"]', '["山棲久不见，林下偶同游。","早晚来香積，何人住沃洲。","寒禽驚後夜，古木带高秋。","却入千峰去，孤云不可留。"]', '诗', 'shi', '', NULL, '秋夜肅公房喜普門上人自陽羨山至 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d68d86aa-336f-4272-bac8-933c19b7bd2e', '送李秘書却赴南中', '送李秘书却赴南中', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["却到番禺日，應傷昔所依。","炎洲百口住，故國幾人歸。","路識梅花在，家存棣萼稀。","獨逢迴雁去，猶作舊行飛。"]', '["却到番禺日，應傷昔所依。","炎洲百口住，故国幾人归。","路識梅花在，家存棣萼稀。","独逢迴雁去，猶作旧行飞。"]', '诗', 'shi', '', NULL, '送李秘書却赴南中 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6010d0db-7831-4975-9191-81a006ebdb29', '過前安宜張明府郊居', '過前安宜張明府郊居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["寂寥東郭外，白首一先生。","解印孤琴在，移家五柳成。","夕陽臨水釣，春雨向田耕。"]', '["寂寥东郭外，白首一先生。","解印孤琴在，移家五柳成。","夕陽臨水釣，春雨向田耕。"]', '诗', 'shi', '', NULL, '過前安宜張明府郊居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a32c9f73-f4bf-4b07-8d95-7af35da374ff', '使迴次楊柳過元八所居', '使迴次楊柳過元八所居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["君家楊柳渡，來往落帆過。","綠竹經寒在，青山欲暮多。","薜蘿誠可戀，婚嫁復如何。","無奈閑門外，漁翁夜夜歌。"]', '["君家楊柳渡，来往落帆過。","綠竹經寒在，青山欲暮多。","薜蘿誠可戀，婚嫁复如何。","無奈闲门外，漁翁夜夜歌。"]', '诗', 'shi', '', NULL, '使迴次楊柳過元八所居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30002005-5251-4efe-97d6-527f823e3f32', '送李侍御貶郴州', '送李侍御貶郴州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["洞庭波渺渺，君去弔靈均。","幾路三湘水，全家萬里人。","聽猨明月夜，看柳故年春。","憶想汀洲畔，傷心向白蘋。"]', '["洞庭波渺渺，君去弔靈均。","幾路三湘水，全家万里人。","听猨明月夜，看柳故年春。","憶想汀洲畔，傷心向白蘋。"]', '诗', 'shi', '', NULL, '送李侍御貶郴州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef136ecc-99c0-46e4-a815-7895338fc7f7', '寄普門上人', '寄普门上人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["白雲幽臥處，不向世人傳。","聞在千峰裏，心知獨夜禪。","辛勤羞薄祿，依止愛閑田。","惆悵王孫草，青青又一年。"]', '["白云幽臥处，不向世人傳。","闻在千峰裏，心知独夜禪。","辛勤羞薄祿，依止愛闲田。","惆悵王孫草，青青又一年。"]', '诗', 'shi', '', NULL, '寄普門上人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f2e93c-2d8c-467b-98bb-7dbee148d4fb', '逢郴州使因寄鄭協律', '逢郴州使因寄鄭協律', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["相思楚天外，夢寐楚猨吟。","更落淮南葉，難爲江上心。","衡陽問人遠，湘水向君深。"]', '["相思楚天外，梦寐楚猨吟。","更落淮南葉，难爲江上心。","衡陽问人远，湘水向君深。"]', '诗', 'shi', '', NULL, '逢郴州使因寄鄭協律 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4c1ce9e-92a0-4969-bdd9-7d392f780ef2', '岳陽館中望洞庭湖', '岳陽館中望洞庭湖', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["萬古巴丘戍，平湖此望長。","問人何淼淼，愁暮更蒼蒼。","疊浪浮元氣，中流沒太陽。","孤舟有歸客，早晚達瀟湘。"]', '["万古巴丘戍，平湖此望长。","问人何淼淼，愁暮更蒼蒼。","叠浪浮元氣，中流沒太陽。","孤舟有归客，早晚達瀟湘。"]', '诗', 'shi', '', NULL, '岳陽館中望洞庭湖 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fda8185-6cde-41db-bc25-22a10548e1c2', '巡去岳陽却歸鄂州使院留別鄭洵侍御先曾謫居此州', '巡去岳陽却归鄂州使院留別鄭洵侍御先曾謫居此州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["何事長沙謫，相逢楚水秋。","暮帆歸夏口，寒雨對巴丘。","帝子椒漿奠，騷人木葉愁。","惟憐萬里外，離別洞庭頭。"]', '["何事长沙謫，相逢楚水秋。","暮帆归夏口，寒雨对巴丘。","帝子椒漿奠，騷人木葉愁。","惟怜万里外，離別洞庭头。"]', '诗', 'shi', '', NULL, '巡去岳陽却歸鄂州使院留別鄭洵侍御先曾謫居此州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b682db02-1857-4459-8192-c48dcc620291', '夏口送屈突司直使湖南', '夏口送屈突司直使湖南', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["共悲來夏口，何事更南征。","霧露行人少，瀟湘春草生。","鶯啼何處夢，猨嘯若爲聲。","風月新年好，悠悠遠客情。"]', '["共悲来夏口，何事更南征。","霧露行人少，瀟湘春草生。","鶯啼何处梦，猨嘯若爲声。","风月新年好，悠悠远客情。"]', '诗', 'shi', '', NULL, '夏口送屈突司直使湖南 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03c7b4f0-1207-45b7-b7c5-592ae37fb94a', '代邊將有懷', '代邊將有懷', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["少年辭魏闕，白首向沙場。","瘦馬戀秋草，征人思故鄉。","暮笳吹寒月，曉甲帶胡霜。","自到雲中郡，于今百戰強。"]', '["少年辞魏闕，白首向沙場。","瘦马戀秋草，征人思故乡。","暮笳吹寒月，晓甲带胡霜。","自到云中郡，于今百戰強。"]', '诗', 'shi', '', NULL, '代邊將有懷 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24e70dca-d8fd-4fb3-9c0e-5638b95a417d', '雨中過員稷巴陵山居贈別', '雨中過員稷巴陵山居贈別', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["憐君洞庭上，白髮向人垂。","積雨悲幽獨，長江對別離。","牛羊歸故道，猨鳥聚寒枝。","明發遙相望，雲山不可知。"]', '["怜君洞庭上，白髮向人垂。","積雨悲幽独，长江对別離。","牛羊归故道，猨鸟聚寒枝。","明發遙相望，云山不可知。"]', '诗', 'shi', '', NULL, '雨中過員稷巴陵山居贈別 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a24959d4-1c32-43dc-b620-b4a0147d4dbe', '送李中丞之襄州', '送李中丞之襄州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["流落征南將，曾驅十萬師。","罷歸無舊業，老去戀明時。","獨立三朝識，輕生一劒知。","茫茫漢江上，日暮復何之。"]', '["流落征南將，曾驱十万師。","罷归無旧業，老去戀明时。","独立三朝識，轻生一劒知。","茫茫漢江上，日暮复何之。"]', '诗', 'shi', '', NULL, '送李中丞之襄州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66b1d615-756e-4021-abff-9925ade3a5fb', '奉使至申州傷經陷沒', '奉使至申州傷經陷沒', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["舉目傷蕪沒，何年此戰爭。","歸人失舊里，老將守孤城。","廢戍山煙出，荒田野火行。","獨憐溮水上，時亂亦能清。"]', '["舉目傷蕪沒，何年此戰爭。","归人失旧里，老將守孤城。","廢戍山煙出，荒田野火行。","独怜溮水上，时亂亦能清。"]', '诗', 'shi', '', NULL, '奉使至申州傷經陷沒 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('489e4ab4-905e-4176-b1b0-77db5225a9ad', '穆陵關北逢人歸漁陽', '穆陵关北逢人归漁陽', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["逢君穆陵路，匹馬向桑乾。","楚國蒼山古，幽州白日寒。","城池百戰後，耆舊幾家殘。","處處蓬蒿遍，歸人掩淚看。"]', '["逢君穆陵路，匹马向桑乾。","楚国蒼山古，幽州白日寒。","城池百戰後，耆旧幾家殘。","处处蓬蒿遍，归人掩泪看。"]', '诗', 'shi', '', NULL, '穆陵關北逢人歸漁陽 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88488310-3aca-473a-b45b-dea16b51ac26', '安州道中經滻水有懷', '安州道中經滻水有懷', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["征途逢滻水，忽似到秦川。","借問朝天處，猶看落日邊。","映沙晴漾漾，出澗夜濺濺。","欲寄西歸恨，微波不可傳。"]', '["征途逢滻水，忽似到秦川。","借问朝天处，猶看落日邊。","映沙晴漾漾，出澗夜濺濺。","欲寄西归恨，微波不可傳。"]', '诗', 'shi', '', NULL, '安州道中經滻水有懷 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ef04e6-cf20-42db-9181-9a9670006357', '步登夏口古城作', '步登夏口古城作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["平蕪連古堞，遠客此沾衣。","高樹朝光上，空城秋氣歸。","微明漢水極，搖落楚人稀。","但見荒郊外，寒鵶暮暮飛。"]', '["平蕪連古堞，远客此沾衣。","高樹朝光上，空城秋氣归。","微明漢水極，搖落楚人稀。","但见荒郊外，寒鵶暮暮飞。"]', '诗', 'shi', '', NULL, '步登夏口古城作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89818a9e-2be9-4f51-8fdd-2a7e0a4b576c', '贈別盧司直之閩中', '贈別盧司直之閩中', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["爾來多不見，此去又何之。","華髮同今日，流芳似舊時。","洲長春色遍，漢廣夕陽遲。","歲歲王孫草，空憐無處期。"]', '["爾来多不见，此去又何之。","华髮同今日，流芳似旧时。","洲长春色遍，漢廣夕陽遲。","歲歲王孫草，空怜無处期。"]', '诗', 'shi', '', NULL, '贈別盧司直之閩中 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bc39453-cea9-4304-9a1f-13963cacf3fb', '酬郭夏人日長沙感懷見贈', '酬郭夏人日长沙感懷见贈', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["舊俗歡猶在，憐君恨獨深。","新年向國淚，今日倚門心。","歲去隨湘水，春生近桂林。","流鶯且莫弄，江畔正行吟。"]', '["旧俗歡猶在，怜君恨独深。","新年向国泪，今日倚门心。","歲去隨湘水，春生近桂林。","流鶯且莫弄，江畔正行吟。"]', '诗', 'shi', '', NULL, '酬郭夏人日長沙感懷見贈 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e824af9-c0f0-462b-a88e-5e7e073dab3f', '赴巴南書情寄故人', '赴巴南书情寄故人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["南過三湘去，巴人此路偏。","謫居秋瘴裏，歸處夕陽邊。","直道天何在，愁容鏡亦憐。","裁書欲誰訴，無淚可潸然。"]', '["南過三湘去，巴人此路偏。","謫居秋瘴裏，归处夕陽邊。","直道天何在，愁容镜亦怜。","裁书欲誰訴，無泪可潸然。"]', '诗', 'shi', '', NULL, '赴巴南書情寄故人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ff7652a-efd8-4a5a-a9fd-b3387c9dc8b9', '餘干旅舍', '餘干旅舍', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["搖落暮天迥，青楓霜葉稀。","孤城向水閉，獨鳥背人飛。","渡口月初上，鄰家漁未歸。","鄉心正欲絕，何處擣寒衣。"]', '["搖落暮天迥，青楓霜葉稀。","孤城向水閉，独鸟背人飞。","渡口月初上，鄰家漁未归。","乡心正欲絕，何处擣寒衣。"]', '诗', 'shi', '', NULL, '餘干旅舍 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5dc9238-486b-4b6b-ae92-b56e0865b3a2', '登思禪寺上方題修竹茂松', '登思禪寺上方題修竹茂松', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["上方幽且暮，臺殿隱蒙籠。","遠磬秋山裏，清猨古木中。","衆溪連竹路，諸嶺共松風。","儻許棲林下，甘成白首翁。"]', '["上方幽且暮，台殿隐蒙籠。","远磬秋山裏，清猨古木中。","衆溪連竹路，諸嶺共松风。","儻許棲林下，甘成白首翁。"]', '诗', 'shi', '', NULL, '登思禪寺上方題修竹茂松 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f1d5e58-4123-4607-bef5-4a9aba90ae28', '恩敕重推使牒追赴蘇州次前溪館作', '恩敕重推使牒追赴蘇州次前溪館作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["漸入雲峰裏，愁看驛路閑。","亂鵶投落日，疲馬向空山。","且喜憐非罪，何心戀末班。","天南一萬里，誰料得生還。"]', '["漸入云峰裏，愁看驛路闲。","亂鵶投落日，疲马向空山。","且喜怜非罪，何心戀末班。","天南一万里，誰料得生還。"]', '诗', 'shi', '', NULL, '恩敕重推使牒追赴蘇州次前溪館作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b046e8-91a9-478e-8a5d-52a5635c3fd8', '北歸次秋浦界清溪館', '北归次秋浦界清溪館', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["萬里猨啼斷，孤村客暫依。","雁過彭蠡暮，人向宛陵稀。","舊路青山在，餘生白首歸。","漸知行近北，不見鷓鴣飛。"]', '["万里猨啼斷，孤村客暫依。","雁過彭蠡暮，人向宛陵稀。","旧路青山在，餘生白首归。","漸知行近北，不见鷓鴣飞。"]', '诗', 'shi', '', NULL, '北歸次秋浦界清溪館 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d4e5222-0ddb-48f5-8467-2d150fdb025b', '謫官後却歸故村將過虎丘悵然有作', '謫官後却归故村將過虎丘悵然有作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["萬事依然在，無如歲月何。","邑人憐白髮，庭樹長新柯。","故老相逢少，同官不見多。","唯餘舊山路，惆悵枉帆過。"]', '["万事依然在，無如歲月何。","邑人怜白髮，庭樹长新柯。","故老相逢少，同官不见多。","唯餘旧山路，惆悵枉帆過。"]', '诗', 'shi', '', NULL, '謫官後却歸故村將過虎丘悵然有作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cb98829-a3fb-4453-b5c4-18fe1d9c1e11', '重推後却赴嶺外待進止寄元侍郎', '重推後却赴嶺外待進止寄元侍郎', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["却訪巴人路，難期國士恩。","白雲從出岫，黃葉已辭根。","大造功何薄，長年氣尚冤。","空令數行淚，來往落湘沅。"]', '["却訪巴人路，难期国士恩。","白云從出岫，黄葉已辞根。","大造功何薄，长年氣尚冤。","空令數行泪，来往落湘沅。"]', '诗', 'shi', '', NULL, '重推後却赴嶺外待進止寄元侍郎 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9911b4a-fd83-4d4a-9f89-ef9fa2552f25', '秋杪江亭有作', '秋杪江亭有作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["寂寞江亭下，江楓秋氣斑。","世情何處澹，湘水向人閑。","寒渚一孤雁，夕陽千萬山。","扁舟如落葉，此去未知還。"]', '["寂寞江亭下，江楓秋氣斑。","世情何处澹，湘水向人闲。","寒渚一孤雁，夕陽千万山。","扁舟如落葉，此去未知還。"]', '诗', 'shi', '', NULL, '秋杪江亭有作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ca7246a-7f44-4c71-9a63-1f25ff8cb2e2', '送鄭司直歸上都', '送鄭司直归上都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["歲歲逢離別，蹉跎江海濱。","宦遊成楚老，鄉思逐秦人。","馬首歸何日，鶯啼又一春。","因君報情舊，閑慢欲垂綸。"]', '["歲歲逢離別，蹉跎江海濱。","宦游成楚老，乡思逐秦人。","马首归何日，鶯啼又一春。","因君報情旧，闲慢欲垂綸。"]', '诗', 'shi', '', NULL, '送鄭司直歸上都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06e4a959-9173-49c1-822d-bdbceaa2e705', '送靈澈上人歸嵩陽蘭若', '送靈澈上人归嵩陽蘭若', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["南地隨緣久，東林幾歲空。","暮山門獨掩，春草路難通。","作梵連松韻，焚香入桂叢。","唯將舊缾鉢，却寄白雲中。"]', '["南地隨緣久，东林幾歲空。","暮山门独掩，春草路难通。","作梵連松韻，焚香入桂叢。","唯將旧缾鉢，却寄白云中。"]', '诗', 'shi', '', NULL, '送靈澈上人歸嵩陽蘭若 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe1c7bea-e2b8-4c26-9e99-2c7d31ae7213', '却赴南邑留別蘇臺知己', '却赴南邑留別蘇台知己', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["又過梅嶺上，歲歲此枝寒。","落日孤舟去，青山萬里看。","猨聲湘水靜，草色洞庭寬。","已料生涯事，唯應把釣竿。"]', '["又過梅嶺上，歲歲此枝寒。","落日孤舟去，青山万里看。","猨声湘水静，草色洞庭寬。","已料生涯事，唯應把釣竿。"]', '诗', 'shi', '', NULL, '却赴南邑留別蘇臺知己 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c312d68-e8d4-41ba-961d-22f391da0e0c', '和靈一上人新泉', '和靈一上人新泉', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["東林一泉出，復與遠公期。","石淺寒流處，山空夜落時。","夢閑聞細響，慮澹對清漪。","動靜皆無意，唯應達者知。"]', '["东林一泉出，复與远公期。","石淺寒流处，山空夜落时。","梦闲闻細响，慮澹对清漪。","动静皆無意，唯應達者知。"]', '诗', 'shi', '', NULL, '和靈一上人新泉 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17b85fdb-4ac9-4bf8-978a-b2f460849ded', '送李摯赴延陵令', '送李摯赴延陵令', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["清風季子邑，想見下車時。","向水彈琴靜，看山採菊遲。","明君加印綬，廉使託惸[嫠]。","旦暮華陽洞，雲峰若有期。"]', '["清风季子邑，想见下车时。","向水彈琴静，看山採菊遲。","明君加印綬，廉使託惸[嫠]。","旦暮华陽洞，云峰若有期。"]', '诗', 'shi', '', NULL, '送李摯赴延陵令 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ae7ba6-4da6-494a-9ca6-1e55154f72b6', '奉送裴員外赴上都', '奉送裴員外赴上都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["彤襜江上遠，萬里詔書催。","獨過潯陽去，空憐潮信迴。","離心秋草綠，揮手暮帆開。","想見秦城路，人看五馬來。"]', '["彤襜江上远，万里詔书催。","独過潯陽去，空怜潮信迴。","離心秋草綠，揮手暮帆开。","想见秦城路，人看五马来。"]', '诗', 'shi', '', NULL, '奉送裴員外赴上都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c7ecefc-ee3c-4081-9ff3-d9cdcb6dad24', '長沙桓王墓下別李紓張南史', '长沙桓王墓下別李紓張南史', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["長沙千載後，春草獨萋萋。","流水朝將暮，行人東復西。","碑苔幾字滅，山木萬株齊。","佇立傷今古，相看惜解攜。"]', '["长沙千載後，春草独萋萋。","流水朝將暮，行人东复西。","碑苔幾字滅，山木万株齊。","佇立傷今古，相看惜解携。"]', '诗', 'shi', '', NULL, '長沙桓王墓下別李紓張南史 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('698ce2d2-09ae-42cb-a829-4bc0243d4611', '送侯御赴黔中充判官', '送侯御赴黔中充判官', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["不識黔中路，今看遣使臣。","猨啼萬里客，鳥似五湖人。","地遠官無法，山深俗豈淳。","須令荒徼外，亦解懼埋輪。"]', '["不識黔中路，今看遣使臣。","猨啼万里客，鸟似五湖人。","地远官無法，山深俗豈淳。","須令荒徼外，亦解懼埋輪。"]', '诗', 'shi', '', NULL, '送侯御赴黔中充判官 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdc07d9f-95b8-45f7-b1b3-9d272b3416a4', '秋日登吳公臺上寺遠眺寺即陳將吳明徹戰場', '秋日登吳公台上寺远眺寺即陳將吳明徹戰場', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["古臺搖落後，秋日望鄉心。","野寺人來少，雲峰水隔深。","夕陽依舊壘，寒磬滿空林。","惆悵南朝事，長江獨至今。"]', '["古台搖落後，秋日望乡心。","野寺人来少，云峰水隔深。","夕陽依旧壘，寒磬满空林。","惆悵南朝事，长江独至今。"]', '诗', 'shi', '', NULL, '秋日登吳公臺上寺遠眺寺即陳將吳明徹戰場 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26e38d21-8c0c-42c9-9a9f-02d3d1e4972f', '淮上送梁二恩命追赴上都', '淮上送梁二恩命追赴上都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["賈生年最少，儒行漢庭聞。","拜手卷黃紙，迴身謝白雲。","故關無去客，春草獨隨君。","淼淼長淮水，東西自此分。"]', '["賈生年最少，儒行漢庭闻。","拜手卷黄紙，迴身謝白云。","故关無去客，春草独隨君。","淼淼长淮水，东西自此分。"]', '诗', 'shi', '', NULL, '淮上送梁二恩命追赴上都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d614d131-55bb-4c1a-b1d7-ab2c77ec6568', '送崔昇歸上都', '送崔昇归上都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["舊寺尋遺緒，歸心逐去塵。","早鶯何處客，古木幾家人。","白髮經多難，滄洲欲暮春。","臨期數行淚，爲爾一霑巾。"]', '["旧寺尋遺緒，归心逐去塵。","早鶯何处客，古木幾家人。","白髮經多难，滄洲欲暮春。","臨期數行泪，爲爾一霑巾。"]', '诗', 'shi', '', NULL, '送崔昇歸上都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b011c784-ca75-418f-8e66-36c023a8d4b3', '過李將軍南鄭林園觀妓', '過李將軍南鄭林园观妓', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["郊原風日好，百舌弄何頻。","小婦秦家女，將軍天上人。","鴉歸長郭暮，草映大堤春。","客散垂楊下，通橋車馬塵。"]', '["郊原风日好，百舌弄何頻。","小婦秦家女，將軍天上人。","鴉归长郭暮，草映大堤春。","客散垂楊下，通橋车马塵。"]', '诗', 'shi', '', NULL, '過李將軍南鄭林園觀妓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62875454-03b8-4d99-983c-c336d16d2cff', '送嚴侍御充東畿觀察判官', '送嚴侍御充东畿观察判官', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["洛陽征戰後，君去問凋殘。","雲月臨南至，風霜向北寒。","故園經亂久，古木隔林看。","誰訪江城客，年年守一官。"]', '["洛陽征戰後，君去问凋殘。","云月臨南至，风霜向北寒。","故园經亂久，古木隔林看。","誰訪江城客，年年守一官。"]', '诗', 'shi', '', NULL, '送嚴侍御充東畿觀察判官 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c5f3fb0-c3aa-4854-a816-9da8229860f8', '送王端公入奏上都', '送王端公入奏上都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["舊國無家訪，臨歧亦羨歸。","途經百戰後，客過二陵稀。","秋草通征騎，寒城背落暉。","行當蒙顧問，吳楚歲頻饑。"]', '["旧国無家訪，臨歧亦羨归。","途經百戰後，客過二陵稀。","秋草通征騎，寒城背落暉。","行當蒙顧问，吳楚歲頻饑。"]', '诗', 'shi', '', NULL, '送王端公入奏上都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ace656a-c4e9-433e-a7c4-d7c0530ae90a', '送營田判官鄭侍御赴上都', '送營田判官鄭侍御赴上都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["上國三千里，西還及歲芳。","故山經亂在，春日送歸長。","曉奏趨雙闕，秋成報萬箱。","幸論開濟力，已實海陵倉。"]', '["上国三千里，西還及歲芳。","故山經亂在，春日送归长。","晓奏趨雙闕，秋成報万箱。","幸論开濟力，已實海陵倉。"]', '诗', 'shi', '', NULL, '送營田判官鄭侍御赴上都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('690e93f2-146f-4690-b2aa-44ff939da200', '送李校書赴東浙幕府', '送李校书赴东浙幕府', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["方從大夫後，南去會稽行。","淼淼滄江外，青青春草生。","芸香辭亂事，梅吹聽軍聲。","應訪王家宅，空憐江水平。"]', '["方從大夫後，南去會稽行。","淼淼滄江外，青青春草生。","芸香辞亂事，梅吹听軍声。","應訪王家宅，空怜江水平。"]', '诗', 'shi', '', NULL, '送李校書赴東浙幕府 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b54c525-1950-4456-b859-a11752bee713', '清明後登城眺望', '清明後登城眺望', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["風景清明後，雲山睥睨前。","百花如舊日，萬井出新煙。","草色無空地，江流合遠天。","長安在何處？遙指夕陽邊。"]', '["风景清明後，云山睥睨前。","百花如旧日，万井出新煙。","草色無空地，江流合远天。","长安在何处？遙指夕陽邊。"]', '诗', 'shi', '', NULL, '清明後登城眺望 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48ed2dfa-2e86-49b6-9811-de4204b9e70a', '陪王明府泛舟', '陪王明府泛舟', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["花縣彈琴暇，樵風載酒時。","山含秋色近，鳥度夕陽遲。","出沒鳧成浪，蒙籠竹亞枝。","雲峰逐人意，來去解相隨。"]', '["花縣彈琴暇，樵风載酒时。","山含秋色近，鸟度夕陽遲。","出沒鳧成浪，蒙籠竹亞枝。","云峰逐人意，来去解相隨。"]', '诗', 'shi', '', NULL, '陪王明府泛舟 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c61e04e1-972d-4979-bc52-c3a21833c7a9', '送度支留後若侍御之歙州便赴信州省覲', '送度支留後若侍御之歙州便赴信州省覲', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["國用憂錢穀，朝推此任難。","即山榆莢變，降雨稻花殘。","林響朝登嶺，江喧夜過灘。","遙知驄馬色，應待倚門看。"]', '["国用憂錢穀，朝推此任难。","即山榆莢变，降雨稻花殘。","林响朝登嶺，江喧夜過灘。","遙知驄马色，應待倚门看。"]', '诗', 'shi', '', NULL, '送度支留後若侍御之歙州便赴信州省覲 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87a94bab-3a1d-4cbc-9e07-dd2e0ebc3d42', '餘干夜宴奉餞前蘇州韋使君新除婺州作', '餘干夜宴奉餞前蘇州韋使君新除婺州作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["復拜東陽郡，遙馳北闕心。","行春五馬急，向夜一猨深。","山過康郎近，星看婺女臨。","幸容棲託分，猶戀舊棠陰。"]', '["复拜东陽郡，遙驰北闕心。","行春五马急，向夜一猨深。","山過康郎近，星看婺女臨。","幸容棲託分，猶戀旧棠陰。"]', '诗', 'shi', '', NULL, '餘干夜宴奉餞前蘇州韋使君新除婺州作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dc8382f-7407-4962-9a0a-797fa7efde5d', '晚次苦竹館却憶干越舊遊', '晚次苦竹館却憶干越旧游', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["匹馬風塵色，千峰旦暮時。","遙看落日盡，獨向遠山遲。","故驛花臨道，荒村竹映籬。","誰憐却迴首，步步戀南枝。"]', '["匹马风塵色，千峰旦暮时。","遙看落日尽，独向远山遲。","故驛花臨道，荒村竹映籬。","誰怜却迴首，步步戀南枝。"]', '诗', 'shi', '', NULL, '晚次苦竹館却憶干越舊遊 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5237844-1e9d-4dae-8577-b9c10468eae8', '送李二十四移家之江州', '送李二十四移家之江州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["煙塵猶滿目，歧路易霑衣。","逋客多南渡，征鴻自北飛。","九江春草綠，千里暮潮歸。","別後難相訪，全家隱釣磯。"]', '["煙塵猶满目，歧路易霑衣。","逋客多南渡，征鴻自北飞。","九江春草綠，千里暮潮归。","別後难相訪，全家隐釣磯。"]', '诗', 'shi', '', NULL, '送李二十四移家之江州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad8b08e5-782a-4b33-abe6-c910d766f203', '送盧判官南湖', '送盧判官南湖', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["漾舟仍載酒，愧爾意相寬。","草色南湖綠，松聲小署寒。","水禽前後起，花嶼往來看。","已作滄洲調，無心戀一官。"]', '["漾舟仍載酒，愧爾意相寬。","草色南湖綠，松声小署寒。","水禽前後起，花嶼往来看。","已作滄洲調，無心戀一官。"]', '诗', 'shi', '', NULL, '送盧判官南湖 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79c60eae-693b-4d94-a448-dd8b6f451937', '送張栩扶侍之睦州', '送張栩扶侍之睦州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["遙憶新安舊，扁舟復却還。","淺深看水石，來往逐雲山。","入縣餘花在，過門故柳閑。","東征隨子去，皆隱薜蘿間。"]', '["遙憶新安旧，扁舟复却還。","淺深看水石，来往逐云山。","入縣餘花在，過门故柳闲。","东征隨子去，皆隐薜蘿间。"]', '诗', 'shi', '', NULL, '送張栩扶侍之睦州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9adc8a82-10ff-42a1-9853-f5ac7f4accda', '集梁耿開元寺所居院', '集梁耿开元寺所居院', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["到君幽臥處，爲我埽莓苔。","花雨晴天落，松風終日來。","路經深竹過，門向遠山開。","豈得長高枕，中朝正用才。"]', '["到君幽臥处，爲我埽莓苔。","花雨晴天落，松风終日来。","路經深竹過，门向远山开。","豈得长高枕，中朝正用才。"]', '诗', 'shi', '', NULL, '集梁耿開元寺所居院 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2a97228-08a4-480c-b241-c1036dda041b', '贈西鄰盧少府', '贈西鄰盧少府', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["籬落能相近，漁樵偶復同。","苔封三徑絕，溪向數家通。","犬吠寒煙裏，鵶鳴夕照中。","時因杖藜次，相訪竹林東。"]', '["籬落能相近，漁樵偶复同。","苔封三徑絕，溪向數家通。","犬吠寒煙裏，鵶鳴夕照中。","时因杖藜次，相訪竹林东。"]', '诗', 'shi', '', NULL, '贈西鄰盧少府 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab375fd7-31a4-497d-a6dd-aed44ebd78a1', '遊休禪師雙峰寺', '游休禪師雙峰寺', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["雙扉碧峰際，遙向夕陽開。","飛錫方獨往，孤雲何事來。","寒潭映白月，秋雨上青苔。","相送東郊外，羞看驄馬回。"]', '["雙扉碧峰際，遙向夕陽开。","飞錫方独往，孤云何事来。","寒潭映白月，秋雨上青苔。","相送东郊外，羞看驄马回。"]', '诗', 'shi', '', NULL, '遊休禪師雙峰寺 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08015dc2-ff98-43ad-9820-0e50544b2235', '廨中見桃花南枝已開北枝未發因寄杜副端', '廨中见桃花南枝已开北枝未發因寄杜副端', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["何意同根本，開花每後時。","應緣去日遠，獨自發春遲。","結實恩難忘，無言恨豈知。","年光不可待，空羨向南枝。"]', '["何意同根本，开花每後时。","應緣去日远，独自發春遲。","結實恩难忘，無言恨豈知。","年光不可待，空羨向南枝。"]', '诗', 'shi', '', NULL, '廨中見桃花南枝已開北枝未發因寄杜副端 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb685144-344b-4b6c-bb3e-18d50349e67e', '奉送盧員外之饒州', '奉送盧員外之饒州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["天書萬里至，旌斾上江飛。","日向鄱陽近，應看吳岫微。","暮帆何處落？潮水背人歸。","風土無勞問，南枝黃葉稀。"]', '["天书万里至，旌斾上江飞。","日向鄱陽近，應看吳岫微。","暮帆何处落？潮水背人归。","风土無勞问，南枝黄葉稀。"]', '诗', 'shi', '', NULL, '奉送盧員外之饒州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8911634b-be09-40cb-9d3a-9eed1fb9386e', '送處士歸州因寄林山人', '送处士归州因寄林山人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["陵陽不可見，獨往復如何。","舊邑雲山裏，扁舟來去過。","鳥聲春谷靜，草色太湖多。","儻宿荆溪夜，相思漁者歌。"]', '["陵陽不可见，独往复如何。","旧邑云山裏，扁舟来去過。","鸟声春谷静，草色太湖多。","儻宿荆溪夜，相思漁者歌。"]', '诗', 'shi', '', NULL, '送處士歸州因寄林山人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6061b61d-365c-4c7e-873c-4d0d97a7ace0', '移使鄂州次峴陽館懷舊居', '移使鄂州次峴陽館懷旧居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["多慙恩未報，敢問路何長。","萬里通秋雁，千峰共夕陽。","舊遊成遠道，此去更違鄉。","草露深山裏，朝朝落客裳。"]', '["多慙恩未報，敢问路何长。","万里通秋雁，千峰共夕陽。","旧游成远道，此去更違乡。","草露深山裏，朝朝落客裳。"]', '诗', 'shi', '', NULL, '移使鄂州次峴陽館懷舊居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a5eb28c-ac28-4cb5-8d5a-fdbbc5ddc494', '送齊郎中赴海州', '送齊郎中赴海州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["華省占星動，孤城望日遙。","直廬收舊草，行縣及新苗。","滄海天連水，青山暮與朝。","閭閻幾家散，應待下車招。"]', '["华省占星动，孤城望日遙。","直廬收旧草，行縣及新苗。","滄海天連水，青山暮與朝。","閭閻幾家散，應待下车招。"]', '诗', 'shi', '', NULL, '送齊郎中赴海州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc086050-97dd-4d53-bf1a-ee4a61234fd0', '重陽日鄂城樓送屈突司直', '重陽日鄂城楼送屈突司直', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["登高復送遠，惆悵洞庭秋。","風景同前古，雲山滿上游。","蒼蒼來暮雨，淼淼逐寒流。","今日關中事，蕭何共爾憂。"]', '["登高复送远，惆悵洞庭秋。","风景同前古，云山满上游。","蒼蒼来暮雨，淼淼逐寒流。","今日关中事，蕭何共爾憂。"]', '诗', 'shi', '', NULL, '重陽日鄂城樓送屈突司直 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88e85622-e441-4071-83e4-6fb414e97a9a', '更被奏留淮南送從弟罷使江東', '更被奏留淮南送從弟罷使江东', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["又作淮南客，還悲木葉聲。","寒潮落瓜步，秋色上蕪城。","王事何時盡？滄洲羨爾行。","青山將綠水，惆悵不勝情。"]', '["又作淮南客，還悲木葉声。","寒潮落瓜步，秋色上蕪城。","王事何时尽？滄洲羨爾行。","青山將綠水，惆悵不勝情。"]', '诗', 'shi', '', NULL, '更被奏留淮南送從弟罷使江東 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1a6b79d-aa1c-4ec5-b723-47050340fcdb', '經漂母墓', '經漂母墓', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["昔賢懷一飯，茲事已千秋。","古墓樵人識，前朝楚水流。","渚蘋行客薦，山木杜鵑愁。","春草茫茫綠，王孫舊此遊。"]', '["昔賢懷一飯，茲事已千秋。","古墓樵人識，前朝楚水流。","渚蘋行客薦，山木杜鵑愁。","春草茫茫綠，王孫旧此游。"]', '诗', 'shi', '', NULL, '經漂母墓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8cf4a6e-fd28-4331-875f-071856b61ab9', '送李端公赴東都', '送李端公赴东都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["軒轅征戰後，江海別離長。","遠客歸何處，平蕪滿故鄉。","夕陽帆杳杳，舊里樹蒼蒼。","惆悵蓬山下，瓊枝不可忘。"]', '["軒轅征戰後，江海別離长。","远客归何处，平蕪满故乡。","夕陽帆杳杳，旧里樹蒼蒼。","惆悵蓬山下，瓊枝不可忘。"]', '诗', 'shi', '', NULL, '送李端公赴東都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b781227-6063-43d8-b184-45d06599a8df', '送王員外歸朝', '送王員外归朝', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["往來無盡目，離別要逢春。","海內罹多事，天涯見近臣。","芳時萬里客，鄉路獨歸人。","魏闕心常在，隨君亦向秦。"]', '["往来無尽目，離別要逢春。","海內罹多事，天涯见近臣。","芳时万里客，乡路独归人。","魏闕心常在，隨君亦向秦。"]', '诗', 'shi', '', NULL, '送王員外歸朝 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15eef528-7b6e-4136-9f92-9535b52a7abb', '送蔣侍御入秦', '送蔣侍御入秦', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["朝見及芳菲，恩榮出紫微。","晚光臨仗奏，春色共西歸。","楚客移家老，秦人訪舊稀。","因君鄉里去，爲埽故園扉。"]', '["朝见及芳菲，恩榮出紫微。","晚光臨仗奏，春色共西归。","楚客移家老，秦人訪旧稀。","因君乡里去，爲埽故园扉。"]', '诗', 'shi', '', NULL, '送蔣侍御入秦 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86b0b4cb-0ad8-416a-9b97-4c2c830746db', '洞庭驛逢郴州使還寄李湯司馬', '洞庭驛逢郴州使還寄李湯司马', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["洞庭秋水闊，南望過衡峰。","遠客瀟湘裏，歸人何處逢。","孤雲飛不定，落葉去無蹤。","莫使滄浪叟，長歌笑爾容。"]', '["洞庭秋水闊，南望過衡峰。","远客瀟湘裏，归人何处逢。","孤云飞不定，落葉去無蹤。","莫使滄浪叟，长歌笑爾容。"]', '诗', 'shi', '', NULL, '洞庭驛逢郴州使還寄李湯司馬 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ca954b-a832-4920-a242-1d7464c8768c', '送舍弟之鄱陽居', '送舍弟之鄱陽居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["鄱陽寄家處，自別掩柴扉。","故里人何在，滄波孤客稀。","湖山春草遍，雲木夕陽微。","南去逢迴鴈，應憐相背飛。"]', '["鄱陽寄家处，自別掩柴扉。","故里人何在，滄波孤客稀。","湖山春草遍，云木夕陽微。","南去逢迴鴈，應怜相背飞。"]', '诗', 'shi', '', NULL, '送舍弟之鄱陽居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('168a4b6e-0f9a-4f6f-bcce-2a561a8552b4', '送裴二十端公使嶺南', '送裴二十端公使嶺南', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["蒼梧萬里路，空見白雲來。","遠國知何在，憐君去未迴。","桂林無葉落，梅嶺自花開。","陸賈千年後，誰看朝漢臺。"]', '["蒼梧万里路，空见白云来。","远国知何在，怜君去未迴。","桂林無葉落，梅嶺自花开。","陸賈千年後，誰看朝漢台。"]', '诗', 'shi', '', NULL, '送裴二十端公使嶺南 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44f24ab9-5326-4326-a592-ab3e5b1bfa7f', '過桃花夫人廟', '過桃花夫人廟', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["寂寞應千歲，桃花想一枝。","路人看古木，江月向空祠。","雲雨飛何處，山川是舊時。","獨憐春草色，猶似憶佳期。"]', '["寂寞應千歲，桃花想一枝。","路人看古木，江月向空祠。","云雨飞何处，山川是旧时。","独怜春草色，猶似憶佳期。"]', '诗', 'shi', '', NULL, '過桃花夫人廟 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bede5fef-14d6-481a-b569-604db6dfe58d', '鄂渚送池州程使君', '鄂渚送池州程使君', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["蕭蕭五馬動，欲別謝臨川。","落日蕪湖色，空山梅冶煙。","江湖通廨舍，楚老拜戈船。","風化東南滿，行舟來去傳。"]', '["蕭蕭五马动，欲別謝臨川。","落日蕪湖色，空山梅冶煙。","江湖通廨舍，楚老拜戈船。","风化东南满，行舟来去傳。"]', '诗', 'shi', '', NULL, '鄂渚送池州程使君 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('339be593-55ba-47a6-babc-12070bfec2b9', '送友人西上', '送友人西上', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["羈心不自解，有別會霑衣。","春草連天積，五陵遠客歸。","十年經轉戰，幾處便芳菲。","想見函關路，行人去亦稀。"]', '["羈心不自解，有別會霑衣。","春草連天積，五陵远客归。","十年經轉戰，幾处便芳菲。","想见函关路，行人去亦稀。"]', '诗', 'shi', '', NULL, '送友人西上 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b559fb98-3c91-4f99-a640-4ee33b58df48', '送梁郎中赴吉州', '送梁郎中赴吉州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["遙想廬陵郡，還聽叔度歌。","舊官移上象，新令布中和。","看竹經霜少，聞猨帶雨多。","但愁徵拜日，無奈借留何。"]', '["遙想廬陵郡，還听叔度歌。","旧官移上象，新令布中和。","看竹經霜少，闻猨带雨多。","但愁徵拜日，無奈借留何。"]', '诗', 'shi', '', NULL, '送梁郎中赴吉州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6172c14-2aef-4809-bcf5-cc1b1ce67b2d', '過湖南羊處士別業', '過湖南羊处士別業', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["杜門成白首，湖上寄生涯。","秋草蕪三徑，寒塘獨一家。","鳥歸村落盡，水向縣城斜。","自有東籬菊，年年解作花。"]', '["杜门成白首，湖上寄生涯。","秋草蕪三徑，寒塘独一家。","鸟归村落尽，水向縣城斜。","自有东籬菊，年年解作花。"]', '诗', 'shi', '', NULL, '過湖南羊處士別業 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8615fe81-6b98-4851-92c8-416ba9462361', '送河南元判官赴河南句當苗稅充百官俸錢', '送河南元判官赴河南句當苗稅充百官俸錢', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["春草長河曲，離心共渺然。","方收漢家俸，獨向汶陽田。","鳥雀空城在，榛蕪舊路遷。","山東征戰苦，幾處有人煙。"]', '["春草长河曲，離心共渺然。","方收漢家俸，独向汶陽田。","鸟雀空城在，榛蕪旧路遷。","山东征戰苦，幾处有人煙。"]', '诗', 'shi', '', NULL, '送河南元判官赴河南句當苗稅充百官俸錢 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d18a3083-e675-44b1-9623-cb34d542a4da', '夏中崔中丞宅見海紅搖落一花獨開', '夏中崔中丞宅见海紅搖落一花独开', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["何事一花殘，閑庭百草闌。","綠滋經雨發，紅豔隔林看。","竟日餘香在，過時獨秀難。","共憐芳意晚，秋露未須團。"]', '["何事一花殘，闲庭百草闌。","綠滋經雨發，紅豔隔林看。","竟日餘香在，過时独秀难。","共怜芳意晚，秋露未須團。"]', '诗', 'shi', '', NULL, '夏中崔中丞宅見海紅搖落一花獨開 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbc26cb9-8466-4947-b688-1b115f0a5324', '使還至菱陂驛渡溮水作', '使還至菱陂驛渡溮水作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["清川已再涉，疲馬共西還。","何事行人倦，終年流水閑。","孤煙飛廣澤，一鳥向空山。","愁入雲峰裏，蒼蒼閉古關。"]', '["清川已再涉，疲马共西還。","何事行人倦，終年流水闲。","孤煙飞廣澤，一鸟向空山。","愁入云峰裏，蒼蒼閉古关。"]', '诗', 'shi', '', NULL, '使還至菱陂驛渡溮水作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9919c6c3-d6d9-424f-a1be-e593e1d8388e', '送齊郎中典括州', '送齊郎中典括州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["星象移何處，旌麾獨向東。","勸耕滄海畔，聽訟白雲中。","樹色雙溪合，猨聲萬嶺同。","石門康樂住，幾里枉帆通。"]', '["星象移何处，旌麾独向东。","勸耕滄海畔，听訟白云中。","樹色雙溪合，猨声万嶺同。","石门康乐住，幾里枉帆通。"]', '诗', 'shi', '', NULL, '送齊郎中典括州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88d109af-babd-4c33-b35d-17dce2a690b0', '過隱空和尚故居', '過隐空和尚故居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["自從飛錫去，人到沃洲稀。","林下期何在，山中春獨歸。","踏花尋舊徑，映竹掩空扉。","寥落東峰上，猶堪靜者依。"]', '["自從飞錫去，人到沃洲稀。","林下期何在，山中春独归。","踏花尋旧徑，映竹掩空扉。","寥落东峰上，猶堪静者依。"]', '诗', 'shi', '', NULL, '過隱空和尚故居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcc318be-3a92-4c4e-a7fe-3930a823b5de', '過蕭尚書故居見李花感而成詠', '過蕭尚书故居见李花感而成詠', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["手植已芳菲，心傷故徑微。","往年啼鳥至，今日主人非。","滿地誰當埽，隨風豈復歸。","空憐舊陰在，門客共霑衣。"]', '["手植已芳菲，心傷故徑微。","往年啼鸟至，今日主人非。","满地誰當埽，隨风豈复归。","空怜旧陰在，门客共霑衣。"]', '诗', 'shi', '', NULL, '過蕭尚書故居見李花感而成詠 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97dba3eb-67f0-47d0-9e1e-3ef1f2fdad7d', '送袁處士', '送袁处士', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["閑田北川下，靜者去躬耕。","萬里空江菼，孤舟過郢城。","種荷依野水，移柳待山鶯。","出處安能問，浮雲豈有情。"]', '["闲田北川下，静者去躬耕。","万里空江菼，孤舟過郢城。","種荷依野水，移柳待山鶯。","出处安能问，浮云豈有情。"]', '诗', 'shi', '', NULL, '送袁處士 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d67a8c4-cef8-467e-bf3b-ce0a332613d2', '酬李侍御登岳陽見寄', '酬李侍御登岳陽见寄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["想見孤舟去，無由此路尋。","暮帆遙在眼，春色獨何心。","綠水瀟湘闊，青山鄠杜深。","誰當北風至，爲爾一開襟。"]', '["想见孤舟去，無由此路尋。","暮帆遙在眼，春色独何心。","綠水瀟湘闊，青山鄠杜深。","誰當北风至，爲爾一开襟。"]', '诗', 'shi', '', NULL, '酬李侍御登岳陽見寄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('604aa35c-21d2-40e8-b354-2fcb339a3beb', '喜晴', '喜晴', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["曉日西風轉，秋天萬里明。","湖天一種色，林鳥百般聲。","霽景浮雲滿，遊絲暎水輕。","今朝江上客，凡慰幾人情。"]', '["晓日西风轉，秋天万里明。","湖天一種色，林鸟百般声。","霽景浮云满，游絲暎水轻。","今朝江上客，凡慰幾人情。"]', '诗', 'shi', '', NULL, '喜晴 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dd4e4db-95f2-4cdf-984f-5fd413980f06', '夏口送徐郎中歸朝', '夏口送徐郎中归朝', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["星象南宮遠，風流上客稀。","九重思曉奏，萬里見春歸。","棹發空江響，城孤落日暉。","離心與楊柳，臨水更依依。"]', '["星象南宮远，风流上客稀。","九重思晓奏，万里见春归。","棹發空江响，城孤落日暉。","離心與楊柳，臨水更依依。"]', '诗', 'shi', '', NULL, '夏口送徐郎中歸朝 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5fa34cf-7151-488c-88ee-a9c439ae7f56', '鄂渚聽杜別駕彈胡琴', '鄂渚听杜別駕彈胡琴', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["文姬留此曲，千載一知音。","不解胡人語，空留楚客心。","聽隨邊草動，意入隴雲深。","何事長江上，蕭蕭出塞吟。"]', '["文姬留此曲，千載一知音。","不解胡人語，空留楚客心。","听隨邊草动，意入隴云深。","何事长江上，蕭蕭出塞吟。"]', '诗', 'shi', '', NULL, '鄂渚聽杜別駕彈胡琴 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('652d2e04-0922-4e01-b3e4-212eee1091de', '過鸚鵡洲王處士別業', '過鸚鵡洲王处士別業', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["白首此爲漁，青山對結廬。","問人尋野笋，留客饋家蔬。","古柳依沙發，春苗帶雨鋤。","共憐芳杜色，終日伴閑居。"]', '["白首此爲漁，青山对結廬。","问人尋野笋，留客饋家蔬。","古柳依沙發，春苗带雨鋤。","共怜芳杜色，終日伴闲居。"]', '诗', 'shi', '', NULL, '過鸚鵡洲王處士別業 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25724640-0835-4136-9635-e8158a7bbf15', '寄萬州崔使君', '寄万州崔使君', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["時艱方用武，儒者任浮沈。","搖落秋江暮，憐君巴峽深。","丘門多白首，蜀郡滿青襟。","自解書生詠，愁猨莫夜吟。"]', '["时艱方用武，儒者任浮沈。","搖落秋江暮，怜君巴峽深。","丘门多白首，蜀郡满青襟。","自解书生詠，愁猨莫夜吟。"]', '诗', 'shi', '', NULL, '寄萬州崔使君 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad2d3d59-da1d-4291-9693-3f0d32e4f0d2', '送馬秀才移家京洛便赴舉', '送马秀才移家京洛便赴舉', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["自從爲楚客，不復掃荆扉。","劒共丹誠在，書隨白髮歸。","舊遊經亂靜，後進識君稀。","空把相如賦，何人薦禮闈。"]', '["自從爲楚客，不复掃荆扉。","劒共丹誠在，书隨白髮归。","旧游經亂静，後進識君稀。","空把相如賦，何人薦禮闈。"]', '诗', 'shi', '', NULL, '送馬秀才移家京洛便赴舉 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('823a409e-3a11-4f1a-a669-fc94527c0363', '送南特進赴歸行營', '送南特進赴归行營', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["聞道軍書至，揚鞭不問家。","虜雲連白草，漢月到黃沙。","汗馬河源飲，燒羌隴坻遮。","翩翩新結束，去逐李輕車。"]', '["闻道軍书至，揚鞭不问家。","虜云連白草，漢月到黄沙。","汗马河源饮，燒羌隴坻遮。","翩翩新結束，去逐李轻车。"]', '诗', 'shi', '', NULL, '送南特進赴歸行營 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e653382-12b8-4814-831e-f218553b4571', '送道標上人歸南岳', '送道標上人归南岳', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["悠然倚孤棹，却憶臥中林。","江草將歸遠，湘山獨往深。","白雲留不住，淥水去無心。","衡岳千峰亂，禪房何處尋。"]', '["悠然倚孤棹，却憶臥中林。","江草將归远，湘山独往深。","白云留不住，淥水去無心。","衡岳千峰亂，禪房何处尋。"]', '诗', 'shi', '', NULL, '送道標上人歸南岳 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e51881c0-e9fc-4b5e-a471-f2039bec5a3f', '送梁侍御巡永州', '送梁侍御巡永州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["蕭蕭江雨暮，客散野亭空。","憂國天涯去，思鄉歲暮同。","到時猨未斷，迴處水應窮。","莫望零陵路，千峰萬木中。"]', '["蕭蕭江雨暮，客散野亭空。","憂国天涯去，思乡歲暮同。","到时猨未斷，迴处水應窮。","莫望零陵路，千峰万木中。"]', '诗', 'shi', '', NULL, '送梁侍御巡永州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fe45936-0c4b-4dcd-9b3b-2a64adb6f309', '歲夜喜魏萬成郭夏雪中相尋', '歲夜喜魏万成郭夏雪中相尋', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["新年欲變柳，舊客共霑衣。","歲夜猶難盡，鄉春又獨歸。","寒燈映虛牖，暮雪掩閑扉。","且莫乘船去，平生相訪稀。"]', '["新年欲变柳，旧客共霑衣。","歲夜猶难尽，乡春又独归。","寒灯映虛牖，暮雪掩闲扉。","且莫乘船去，平生相訪稀。"]', '诗', 'shi', '', NULL, '歲夜喜魏萬成郭夏雪中相尋 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55932dbd-51d3-4968-9448-5c2f7f09825f', '送蔡侍御赴上都', '送蔡侍御赴上都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["遲遲立駟馬，久客戀瀟湘。","明日誰同路，新年獨到鄉。","孤煙向驛遠，積雪去關長。","秦地看春色，南枝不可忘。"]', '["遲遲立駟马，久客戀瀟湘。","明日誰同路，新年独到乡。","孤煙向驛远，積雪去关长。","秦地看春色，南枝不可忘。"]', '诗', 'shi', '', NULL, '送蔡侍御赴上都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbe1b2ab-b9a2-4a16-9c46-350e16523dda', '晦日陪辛大夫宴南亭', '晦日陪辛大夫宴南亭', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["月晦逢休澣，年光逐宴移。","早鶯留客醉，春日爲人遲。","蓂草全無葉，梅花遍壓枝。","政閑風景好，莫比峴山時。"]', '["月晦逢休澣，年光逐宴移。","早鶯留客醉，春日爲人遲。","蓂草全無葉，梅花遍壓枝。","政闲风景好，莫比峴山时。"]', '诗', 'shi', '', NULL, '晦日陪辛大夫宴南亭 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e053637-210f-4f95-a3f2-148f414eaa7b', '送獨孤判官赴嶺', '送独孤判官赴嶺', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["伏波初樹羽，待爾靜川鱗。","嶺海看飛鳥，天涯問遠人。","蒼梧雲裏夕，青草嶂中春。","遙想文身國，迎舟拜使臣。"]', '["伏波初樹羽，待爾静川鱗。","嶺海看飞鸟，天涯问远人。","蒼梧云裏夕，青草嶂中春。","遙想文身国，迎舟拜使臣。"]', '诗', 'shi', '', NULL, '送獨孤判官赴嶺 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('000318db-5cde-4294-a1e4-8170c9e6e7b6', '長沙館中與郭夏對雨', '长沙館中與郭夏对雨', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["長沙積雨晦，深巷絕人幽。","潤上春衣冷，聲連暮角愁。","雲橫全楚地，樹暗古湘洲。","杳藹江天外，空堂生百憂。"]', '["长沙積雨晦，深巷絕人幽。","潤上春衣冷，声連暮角愁。","云橫全楚地，樹暗古湘洲。","杳藹江天外，空堂生百憂。"]', '诗', 'shi', '', NULL, '長沙館中與郭夏對雨 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('340ba0aa-9b16-4092-ab7d-a64e8f7723e1', '陪辛大夫西亭宴觀妓', '陪辛大夫西亭宴观妓', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["歌舞憐遲日，旌麾映早春。","鶯窺隴西將，花對洛陽人。","醉罷知何事，恩深忘此身。","任他行雨去，歸路裛香塵。"]', '["歌舞怜遲日，旌麾映早春。","鶯窺隴西將，花对洛陽人。","醉罷知何事，恩深忘此身。","任他行雨去，归路裛香塵。"]', '诗', 'shi', '', NULL, '陪辛大夫西亭宴觀妓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cb680ab-73c6-41cb-b856-2021c2ce5f93', '題魏萬成江亭', '題魏万成江亭', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["蕭條方歲晏，牢落對空洲。","才出時人右，家貧湘水頭。","蒼山隱暮雪，白鳥沒寒流。","不是蓮花府，冥冥不可求。"]', '["蕭條方歲晏，牢落对空洲。","才出时人右，家貧湘水头。","蒼山隐暮雪，白鸟沒寒流。","不是蓮花府，冥冥不可求。"]', '诗', 'shi', '', NULL, '題魏萬成江亭 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8dd9acc-2083-4310-970b-d258bdd023eb', '春過裴虬郊園', '春過裴虬郊园', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["郊原春欲暮，桃杏落紛紛。","何處隨芳草，留家寄白雲。","聽鶯情念友，看竹恨無君。","長嘯高臺上，南風冀爾聞。"]', '["郊原春欲暮，桃杏落紛紛。","何处隨芳草，留家寄白云。","听鶯情念友，看竹恨無君。","长嘯高台上，南风冀爾闻。"]', '诗', 'shi', '', NULL, '春過裴虬郊園 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32ce6bba-527a-480a-8985-a5260ed38928', '送韋贊善使嶺南', '送韋贊善使嶺南', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["欲逐樓船將，方安卉服夷。","炎洲經瘴遠，春水上瀧遲。","歲貢隨重譯，年芳徧四時。","番禺靜無事，空詠飲泉詩。"]', '["欲逐楼船將，方安卉服夷。","炎洲經瘴远，春水上瀧遲。","歲貢隨重譯，年芳徧四时。","番禺静無事，空詠饮泉诗。"]', '诗', 'shi', '', NULL, '送韋贊善使嶺南 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec319906-635a-47f6-bea3-82c168e4a5ce', '送喬判官赴福州', '送喬判官赴福州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["揚帆向何處，插羽逐征東。","夷落人煙迥，王程鳥路通。","江流回澗底，山色聚閩中。","君去凋殘後，應憐百越空。"]', '["揚帆向何处，插羽逐征东。","夷落人煙迥，王程鸟路通。","江流回澗底，山色聚閩中。","君去凋殘後，應怜百越空。"]', '诗', 'shi', '', NULL, '送喬判官赴福州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('162079b4-6a53-424f-b25b-40eb047d8fae', '送李補闕之上都', '送李補闕之上都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["獨歸西掖去，難接後塵遊。","向日三千里，朝天十二樓。","路看新柳夕，家對舊山秋。","惆悵離心遠，滄江空自流。"]', '["独归西掖去，难接後塵游。","向日三千里，朝天十二楼。","路看新柳夕，家对旧山秋。","惆悵離心远，滄江空自流。"]', '诗', 'shi', '', NULL, '送李補闕之上都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6e4de51-0600-4ae9-938f-f7605e4de8a0', '送袁明府之任', '送袁明府之任', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["既有親人術，還逢試吏年。","蓬蒿千里閉，村樹幾家全。","雪覆淮南道，春生潁谷煙。","何時當莅政，相府待聞天。"]', '["既有親人術，還逢試吏年。","蓬蒿千里閉，村樹幾家全。","雪覆淮南道，春生潁谷煙。","何时當莅政，相府待闻天。"]', '诗', 'shi', '', NULL, '送袁明府之任 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51cb634a-3685-48f6-b9df-7ccd3a105429', '海鹽官舍早春', '海鹽官舍早春', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["小邑滄洲吏，新年白首翁。","一官如遠客，萬事極飄蓬。","柳色孤城裏，鶯聲細雨中。","羈心早已亂，何事更春風。"]', '["小邑滄洲吏，新年白首翁。","一官如远客，万事極飄蓬。","柳色孤城裏，鶯声細雨中。","羈心早已亂，何事更春风。"]', '诗', 'shi', '', NULL, '海鹽官舍早春 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('277081c8-2f97-4fbb-979f-b972f4e5a949', '南湖送徐二十七西上', '南湖送徐二十七西上', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["家在橫塘曲，那能萬里違。","門臨秋水掩，帆帶夕陽飛。","傲俗宜紗帽，干時倚布衣。","獨將湖上月，相逐去還歸。"]', '["家在橫塘曲，那能万里違。","门臨秋水掩，帆带夕陽飞。","傲俗宜紗帽，干时倚布衣。","独將湖上月，相逐去還归。"]', '诗', 'shi', '', NULL, '南湖送徐二十七西上 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('353c3796-b91d-4aea-b133-7ecd1d0999a4', '曲阿對月別岑況徐說', '曲阿对月別岑況徐说', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["金陵已蕪沒，函谷復煙塵。","猶見南朝月，還隨上國人。","白雲心自遠，滄海意相親。","何事須成別，汀洲欲暮春。"]', '["金陵已蕪沒，函谷复煙塵。","猶见南朝月，還隨上国人。","白云心自远，滄海意相親。","何事須成別，汀洲欲暮春。"]', '诗', 'shi', '', NULL, '曲阿對月別岑況徐說 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9d028b4-285d-4fd6-a814-cb80b17c2d94', '送李侍御貶鄱陽', '送李侍御貶鄱陽', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["迴車仍昨日，謫去已秋風。","干越知何處，雲山只向東。","暮天江色裏，田鶴稻花中。","却見鄱陽吏，猶應舊馬驄。"]', '["迴车仍昨日，謫去已秋风。","干越知何处，云山只向东。","暮天江色裏，田鹤稻花中。","却见鄱陽吏，猶應旧马驄。"]', '诗', 'shi', '', NULL, '送李侍御貶鄱陽 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99817a07-7174-42a0-b0a5-831be9effd7b', '送路少府使東京便應制舉', '送路少府使东京便應制舉', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["故人西奉使，胡騎正紛紛。","舊國無來信，春江獨送君。","五言淩白雪，六翮向青雲。","誰念滄州吏，忘機鷗鳥羣。"]', '["故人西奉使，胡騎正紛紛。","旧国無来信，春江独送君。","五言淩白雪，六翮向青云。","誰念滄州吏，忘機鷗鸟羣。"]', '诗', 'shi', '', NULL, '送路少府使東京便應制舉 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c293bcaf-2279-4f7a-a73c-3b5198d98177', '松江獨宿', '松江独宿', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["洞庭初下葉，孤客不勝愁。","明月天涯夜，青山江上秋。","一官成白首，萬里寄滄洲。","久被浮名繫，能無媿海鷗。"]', '["洞庭初下葉，孤客不勝愁。","明月天涯夜，青山江上秋。","一官成白首，万里寄滄洲。","久被浮名繫，能無媿海鷗。"]', '诗', 'shi', '', NULL, '松江獨宿 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57921126-316b-4967-a828-e08a6ffe74cb', '尋白石山真禪師舊草堂', '尋白石山真禪師旧草堂', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["惆悵雲山暮，閑門獨不開。","何時飛杖錫，終日閉蒼苔。","隔嶺春猶在，無人燕亦來。","誰堪暝投處，空復一猨哀。"]', '["惆悵云山暮，闲门独不开。","何时飞杖錫，終日閉蒼苔。","隔嶺春猶在，無人燕亦来。","誰堪暝投处，空复一猨哀。"]', '诗', 'shi', '', NULL, '尋白石山真禪師舊草堂 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1285b2d0-b7ad-42fa-981f-bf96b84791cc', '送行軍張司馬罷使迴', '送行軍張司马罷使迴', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["時危身赴敵，事往任浮沈。","末路三江去，當時百戰心。","春風吳苑綠，古木剡山深。","千里滄波上，孤舟不可尋。"]', '["时危身赴敵，事往任浮沈。","末路三江去，當时百戰心。","春风吳苑綠，古木剡山深。","千里滄波上，孤舟不可尋。"]', '诗', 'shi', '', NULL, '送行軍張司馬罷使迴 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a76e28-465d-454d-9be4-08d4293f2708', '喜李翰自越至', '喜李翰自越至', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["南浮滄海上，萬里到吳臺。","久別長相憶，孤舟何處來。","春風催客醉，江月向人開。","羨爾無羈束，沙鷗獨不猜。"]', '["南浮滄海上，万里到吳台。","久別长相憶，孤舟何处来。","春风催客醉，江月向人开。","羨爾無羈束，沙鷗独不猜。"]', '诗', 'shi', '', NULL, '喜李翰自越至 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e954d58f-feb2-4392-a31a-9aae9944deed', '罪所留繫寄張十四', '罪所留繫寄張十四', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["不見君來久，冤深意未傳。","冶長空得罪，夷甫豈言錢。","直道天何在，愁容鏡亦憐。","因書欲自訴，無淚可潸然。"]', '["不见君来久，冤深意未傳。","冶长空得罪，夷甫豈言錢。","直道天何在，愁容镜亦怜。","因书欲自訴，無泪可潸然。"]', '诗', 'shi', '', NULL, '罪所留繫寄張十四 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44824d1a-ffc0-4793-b436-134073275e96', '送勤照和尚往睢陽赴太守請', '送勤照和尚往睢陽赴太守請', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["燃燈傳七祖，杖錫爲諸侯。","來去雲無意，東西水自流。","青山春滿目，白日夜隨舟。","知到梁園下，蒼生賴此遊。"]', '["燃灯傳七祖，杖錫爲諸侯。","来去云無意，东西水自流。","青山春满目，白日夜隨舟。","知到梁园下，蒼生賴此游。"]', '诗', 'shi', '', NULL, '送勤照和尚往睢陽赴太守請 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76da5012-0d84-4f65-9fef-02e32649d455', '長門怨', '长门怨', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["何事長門閉，珠簾只自垂。","月移深殿早，春向後宮遲。","蕙草生閑地，梨花發舊枝。","芳菲自恩幸，看著被風吹。"]', '["何事长门閉，珠簾只自垂。","月移深殿早，春向後宮遲。","蕙草生闲地，梨花發旧枝。","芳菲自恩幸，看著被风吹。"]', '诗', 'shi', '', NULL, '長門怨 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('749adb62-e238-4e32-9791-b1e9eca0bc83', '過橫山顧山人草堂', '過橫山顧山人草堂', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["只見山相掩，誰言路尚通。","人來千嶂外，犬吠百花中。","細草香飄雨，垂楊閑臥風。","却尋樵徑去，惆悵綠溪東。"]', '["只见山相掩，誰言路尚通。","人来千嶂外，犬吠百花中。","細草香飄雨，垂楊闲臥风。","却尋樵徑去，惆悵綠溪东。"]', '诗', 'shi', '', NULL, '過橫山顧山人草堂 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4d48d13-f3cb-445a-9e57-65cf82732576', '送李校書適越謁杜中丞', '送李校书適越謁杜中丞', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["江風處處盡，旦暮水空波。","搖落行人去，雲山向越多。","陳蕃懸榻待，謝客枉帆過。","相見耶溪路，逶迤入薜蘿。"]', '["江风处处尽，旦暮水空波。","搖落行人去，云山向越多。","陳蕃懸榻待，謝客枉帆過。","相见耶溪路，逶迤入薜蘿。"]', '诗', 'shi', '', NULL, '送李校書適越謁杜中丞 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b0dbbd2-8da9-4b1f-903d-e0f0ea79efd8', '秋夜雨中諸公過靈光寺所居', '秋夜雨中諸公過靈光寺所居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["晤語青蓮舍，重門閉夕陰。","向人寒燭靜，帶雨夜鐘沈。","流水從他事，孤雲任此心。","不能捐斗粟，終日媿瑤琴。"]', '["晤語青蓮舍，重门閉夕陰。","向人寒燭静，带雨夜鐘沈。","流水從他事，孤云任此心。","不能捐斗粟，終日媿瑤琴。"]', '诗', 'shi', '', NULL, '秋夜雨中諸公過靈光寺所居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5050ffa2-e966-43f5-ac8d-f21c53723073', '西庭夜燕喜評事兄拜會', '西庭夜燕喜評事兄拜會', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["猶是南州吏，江城又一春。","隔簾湖上月，對酒眼中人。","棘寺初銜命，梅仙已誤身。","無心羨榮祿，唯待却垂綸。"]', '["猶是南州吏，江城又一春。","隔簾湖上月，对酒眼中人。","棘寺初銜命，梅仙已誤身。","無心羨榮祿，唯待却垂綸。"]', '诗', 'shi', '', NULL, '西庭夜燕喜評事兄拜會 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04af557e-bac8-4fbf-92e7-d8a87fa11038', '尋南溪常山道人隱居', '尋南溪常山道人隐居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["一路經行處，莓苔見履痕。","白雲依靜渚，春草閉閑門。","過雨看松色，隨山到水源。","溪花與禪意，相對亦忘言。"]', '["一路經行处，莓苔见履痕。","白云依静渚，春草閉闲门。","過雨看松色，隨山到水源。","溪花與禪意，相对亦忘言。"]', '诗', 'shi', '', NULL, '尋南溪常山道人隱居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a5f33bf-639a-479e-bc05-623abbdc4aa6', '揚州雨中張十宅觀妓', '揚州雨中張十宅观妓', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["夜色帶春煙，燈花拂更然。","殘粧添石黛，豔舞落金鈿。","掩笑頻欹扇，迎歌乍動弦。","不知巫峽雨，何事海西邊。"]', '["夜色带春煙，灯花拂更然。","殘粧添石黛，豔舞落金鈿。","掩笑頻欹扇，迎歌乍动弦。","不知巫峽雨，何事海西邊。"]', '诗', 'shi', '', NULL, '揚州雨中張十宅觀妓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddbe854e-ed66-43eb-8808-31f8a8b2c478', '赴宣州使院夜宴寂上人房留辭前蘇州韋使君', '赴宣州使院夜宴寂上人房留辞前蘇州韋使君', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["白雲乖始願，滄海有微波。","戀舊爭趨府，臨危欲負戈。","春歸花殿暗，秋傍竹房多。","耐可機心息，其如羽檄何。"]', '["白云乖始願，滄海有微波。","戀旧爭趨府，臨危欲負戈。","春归花殿暗，秋傍竹房多。","耐可機心息，其如羽檄何。"]', '诗', 'shi', '', NULL, '赴宣州使院夜宴寂上人房留辭前蘇州韋使君 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aa3bc1a-8bed-467a-a1b1-d61c98aa9f96', '送薛承矩秩滿北遊', '送薛承矩秩满北游', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["匹馬向何處，北遊殊未還。","寒雲帶飛雪，日暮雁門關。","一路傍汾水，數州看晉山。","知君喜初服，秪愛此身閑。"]', '["匹马向何处，北游殊未還。","寒云带飞雪，日暮雁门关。","一路傍汾水，數州看晉山。","知君喜初服，秪愛此身闲。"]', '诗', 'shi', '', NULL, '送薛承矩秩滿北遊 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1487452b-5f49-4f4f-9913-1f3ec1cddf95', '餞別王十一南遊', '餞別王十一南游', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["望君煙水闊，揮手淚霑巾。","飛鳥沒何處，青山空向人。","長江一帆遠，落日五湖春。","誰見汀洲上，相思愁白蘋。"]', '["望君煙水闊，揮手泪霑巾。","飞鸟沒何处，青山空向人。","长江一帆远，落日五湖春。","誰见汀洲上，相思愁白蘋。"]', '诗', 'shi', '', NULL, '餞別王十一南遊 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b96ed9b0-175f-4a0f-a193-0c89ab696596', '送嚴維尉諸暨', '送嚴維尉諸暨', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["愛爾文章遠，還家印綬榮。","退公兼色養，臨下帶鄉情。","喬木映官舍，春山宜縣城。","應憐釣臺石，閑却爲浮名。"]', '["愛爾文章远，還家印綬榮。","退公兼色養，臨下带乡情。","喬木映官舍，春山宜縣城。","應怜釣台石，闲却爲浮名。"]', '诗', 'shi', '', NULL, '送嚴維尉諸暨 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f18de4b4-2309-4a58-91fb-fbc07f054d61', '送李七之莋水謁張相公', '送李七之莋水謁張相公', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["惆悵青春晚，慇懃濁酒壚。","後時長劒澀，斜日片帆孤。","東閣邀才子，南昌老腐儒。","梁國舊相識，誰憶臥江湖。"]', '["惆悵青春晚，慇懃濁酒壚。","後时长劒澀，斜日片帆孤。","东閣邀才子，南昌老腐儒。","梁国旧相識，誰憶臥江湖。"]', '诗', 'shi', '', NULL, '送李七之莋水謁張相公 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c198f744-ce8c-41a2-907d-84012b2e7ced', '送崔處士先適越', '送崔处士先適越', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["山陰好雲物，此去又春風。","越鳥聞花裏，曹娥想鏡中。","小江潮易滿，萬井水皆通。","徒羨扁舟客，微官事不同。"]', '["山陰好云物，此去又春风。","越鸟闻花裏，曹娥想镜中。","小江潮易满，万井水皆通。","徒羨扁舟客，微官事不同。"]', '诗', 'shi', '', NULL, '送崔處士先適越 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90e0fc08-1ba8-4395-a94e-9586852c27e2', '奉陪使君西庭送淮西魏判官', '奉陪使君西庭送淮西魏判官', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["羽檄催歸恨，春風醉別顏。","能邀五馬送，自逐一星還。","破竹從軍樂，看花聽訟閑。","遙知用兵處，多在八公山。"]', '["羽檄催归恨，春风醉別顏。","能邀五马送，自逐一星還。","破竹從軍乐，看花听訟闲。","遙知用兵处，多在八公山。"]', '诗', 'shi', '', NULL, '奉陪使君西庭送淮西魏判官 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10ec49e8-146c-41c8-9660-02c275a467f0', '獄中見壁畫佛', '獄中见壁畫佛', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["不謂銜冤處，而能窺大悲。","獨棲叢棘下，還見雨花時。","地狹青蓮小，城高白日遲。","幸親方便力，猶畏毒龍欺。"]', '["不謂銜冤处，而能窺大悲。","独棲叢棘下，還见雨花时。","地狹青蓮小，城高白日遲。","幸親方便力，猶畏毒龙欺。"]', '诗', 'shi', '', NULL, '獄中見壁畫佛 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8570f120-231a-4594-abd4-b3cc5071a289', '送許拾遺還京', '送許拾遺還京', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["萬里辭三殿，金陵到舊居。","文星出西掖，卿月在南徐。","故里驚朝服，高堂捧詔書。","暫容乘駟馬，誰許戀鱸魚。"]', '["万里辞三殿，金陵到旧居。","文星出西掖，卿月在南徐。","故里驚朝服，高堂捧詔书。","暫容乘駟马，誰許戀鱸鱼。"]', '诗', 'shi', '', NULL, '送許拾遺還京 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bce947e4-574d-4fc2-a886-a8a95e907262', '送張七判官還京覲省', '送張七判官還京覲省', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["春蘭方可採，此去葉初齊。","函谷鶯聲裏，秦山馬首西。","庭闈新栢署，門館舊桃蹊。","春色長安道，相隨入禁閨。"]', '["春蘭方可採，此去葉初齊。","函谷鶯声裏，秦山马首西。","庭闈新栢署，门館旧桃蹊。","春色长安道，相隨入禁閨。"]', '诗', 'shi', '', NULL, '送張七判官還京覲省 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c0107fd-13f1-4ce7-8248-e774c43db3fd', '送孫瑩京監擢第歸蜀覲省', '送孫瑩京監擢第归蜀覲省', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["適賀一枝新，旋驚萬里分。","禮闈稱獨步，太學許能文。","征馬望春草，行人看暮雲。","遙知倚門處，江樹正氛氳。"]', '["適賀一枝新，旋驚万里分。","禮闈稱独步，太学許能文。","征马望春草，行人看暮云。","遙知倚门处，江樹正氛氳。"]', '诗', 'shi', '', NULL, '送孫瑩京監擢第歸蜀覲省 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63035e67-c1aa-405a-8660-a53c378a933c', '送史九赴任寧陵兼呈單父史八時監察五兄初入臺', '送史九赴任寧陵兼呈單父史八时監察五兄初入台', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["趨府弟聯兄，看君此去榮。","春隨千里道，河帶萬家城。","繡服棠花映，青袍草色迎。","梁園修竹在，持贈結交情。"]', '["趨府弟聯兄，看君此去榮。","春隨千里道，河带万家城。","繡服棠花映，青袍草色迎。","梁园修竹在，持贈結交情。"]', '诗', 'shi', '', NULL, '送史九赴任寧陵兼呈單父史八時監察五兄初入臺 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d03098c5-4d9e-4d06-82d1-a14769d01df3', '臥病喜田九見寄', '臥病喜田九见寄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["臥來能幾日，春事已依然。","不解謝公意，翻令靜者便。","庭陰殘舊雪，柳色帶新年。","寂寞深村裏，唯君相訪偏。"]', '["臥来能幾日，春事已依然。","不解謝公意，翻令静者便。","庭陰殘旧雪，柳色带新年。","寂寞深村裏，唯君相訪偏。"]', '诗', 'shi', '', NULL, '臥病喜田九見寄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cb68537-4c65-489f-81a5-132344ccf113', '重過宣峰寺山房寄靈一上人', '重過宣峰寺山房寄靈一上人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["西陵潮信滿，島嶼入中流。","越客依風水，相思南渡頭。","寒光生極浦，暮雪映滄洲。","何事揚帆去，空驚海上鷗。"]', '["西陵潮信满，島嶼入中流。","越客依风水，相思南渡头。","寒光生極浦，暮雪映滄洲。","何事揚帆去，空驚海上鷗。"]', '诗', 'shi', '', NULL, '重過宣峰寺山房寄靈一上人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a338939b-2ed2-408b-a6bc-7acdec143f7a', '雲門寺訪靈一上人', '云门寺訪靈一上人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["所思勞日夕，惆悵去西東。","禪客知何在，春山到處同。","獨行殘雪裏，相見白雲中。","請近東林寺，窮年事遠公。"]', '["所思勞日夕，惆悵去西东。","禪客知何在，春山到处同。","独行殘雪裏，相见白云中。","請近东林寺，窮年事远公。"]', '诗', 'shi', '', NULL, '雲門寺訪靈一上人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17154f34-f404-4c8b-85c8-3deb628f1661', '送陸羽之茅山寄李延陵', '送陸羽之茅山寄李延陵', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["延陵衰草遍，有路問茅山。","雞犬驅將去，煙霞擬不還。","新家彭澤縣，舊國穆陵關。","處處逃名姓，無名亦是閑。"]', '["延陵衰草遍，有路问茅山。","雞犬驱將去，煙霞擬不還。","新家彭澤縣，旧国穆陵关。","处处逃名姓，無名亦是闲。"]', '诗', 'shi', '', NULL, '送陸羽之茅山寄李延陵 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbc87b26-3540-4adc-a325-d30f2ba23ee6', '寄靈一上人初還雲門', '寄靈一上人初還云门', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["寒霜白雲裏，法侶自相攜。","竹逕通城下，松風隔水西。","方同沃洲去，不作武陵迷。","髣髴知心處，高峰是會稽。"]', '["寒霜白云裏，法侶自相携。","竹逕通城下，松风隔水西。","方同沃洲去，不作武陵迷。","髣髴知心处，高峰是會稽。"]', '诗', 'shi', '', NULL, '寄靈一上人初還雲門 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('338ed593-fa8b-4004-88c8-9189a6f99f87', '寄靈一上人', '寄靈一上人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["高僧本姓竺，開士舊名林。","一去春山裏，千峰不可尋。","新年芳草遍，終日白雲深。","欲徇微官去，懸知訝此心。"]', '["高僧本姓竺，开士旧名林。","一去春山裏，千峰不可尋。","新年芳草遍，終日白云深。","欲徇微官去，懸知訝此心。"]', '诗', 'shi', '', NULL, '寄靈一上人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4a6680a-eac3-447a-96b7-47c20c9177b8', '送韓司直', '送韓司直', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["遊吳還入越，來往任風波。","復送王孫去，其如春草何。","岸明殘雪在，潮滿夕陽多。","季子楊柳廟，停舟試一過。"]', '["游吳還入越，来往任风波。","复送王孫去，其如春草何。","岸明殘雪在，潮满夕陽多。","季子楊柳廟，停舟試一過。"]', '诗', 'shi', '', NULL, '送韓司直 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71964553-851c-4f22-83f2-a521d3b3a15e', '酬李郎中夜登蘇州城樓見寄', '酬李郎中夜登蘇州城楼见寄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["辛勤萬里道，蕭索九秋殘。","日照閩中夜，天凝海上寒。","客程無地遠，主意在人安。","遙寄登樓作，空知行路難。"]', '["辛勤万里道，蕭索九秋殘。","日照閩中夜，天凝海上寒。","客程無地远，主意在人安。","遙寄登楼作，空知行路难。"]', '诗', 'shi', '', NULL, '酬李郎中夜登蘇州城樓見寄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0e686cd-cf24-4ed8-afaf-8080ac97e567', '送人遊越', '送人游越', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["未習風波事，初爲吳越遊。","露霑湖色曉，月照海門秋。","梅市門何在，蘭亭水尚流。","西陵待潮處，落日滿扁舟。"]', '["未習风波事，初爲吳越游。","露霑湖色晓，月照海门秋。","梅市门何在，蘭亭水尚流。","西陵待潮处，落日满扁舟。"]', '诗', 'shi', '', NULL, '送人遊越 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8499552-faf7-4418-a512-428a703b6b8f', '贈普門上人', '贈普门上人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["支公身欲老，長在沃洲多。","惠力堪傳教，禪心久伏魔。","山雲隨坐夏，江草伴頭陀。","借問迴心後，賢愚去幾何。"]', '["支公身欲老，长在沃洲多。","惠力堪傳教，禪心久伏魔。","山云隨坐夏，江草伴头陀。","借问迴心後，賢愚去幾何。"]', '诗', 'shi', '', NULL, '贈普門上人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bb386e8-5066-44b5-bb00-8d6b6b70bd8e', '送康判官往新安', '送康判官往新安', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["不向新安去，那知江路長。","猨聲近廬霍，水色勝瀟湘。","驛路收殘雨，漁家帶夕陽。","何須愁旅泊，使者有輝光。"]', '["不向新安去，那知江路长。","猨声近廬霍，水色勝瀟湘。","驛路收殘雨，漁家带夕陽。","何須愁旅泊，使者有輝光。"]', '诗', 'shi', '', NULL, '送康判官往新安 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b4e183-f231-4e3c-9ff3-eeb68a915a45', '送顧長', '送顧长', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["由來山水客，復道向新安。","半是乘槎便，全非行路難。","晨裝林月在，野飯浦沙寒。","嚴子千年後，何人釣舊灘。"]', '["由来山水客，复道向新安。","半是乘槎便，全非行路难。","晨裝林月在，野飯浦沙寒。","嚴子千年後，何人釣旧灘。"]', '诗', 'shi', '', NULL, '送顧長 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ff46b95-fb09-45d0-80ab-6fc12ce17cb4', '九日登李明府北樓', '九日登李明府北楼', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["九日登高望，蒼蒼遠樹低。","人煙湖草裏，山翠縣樓西。","霜降鴻聲切，秋深客思迷。","無勞白衣酒，陶令自相攜。"]', '["九日登高望，蒼蒼远樹低。","人煙湖草裏，山翠縣楼西。","霜降鴻声切，秋深客思迷。","無勞白衣酒，陶令自相携。"]', '诗', 'shi', '', NULL, '九日登李明府北樓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49c0119c-d873-43d1-b625-bd786d10ea87', '同諸公登樓', '同諸公登楼', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["秋草行將暮，登樓客思驚。","千家同霽色，一鴈報寒聲。","北望無鄉信，東遊滯客行。","今君佩銅墨，還有越鄉情。"]', '["秋草行將暮，登楼客思驚。","千家同霽色，一鴈報寒声。","北望無乡信，东游滯客行。","今君佩銅墨，還有越乡情。"]', '诗', 'shi', '', NULL, '同諸公登樓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a00c87b-69b6-4627-8830-06062221f811', '送友人南遊', '送友人南游', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["不愁尋水遠，自愛逐連山。","雖在春風裏，猶從芳草間。","去程何用計，勝事且相關。","旅逸同羣鳥，悠悠往復還。"]', '["不愁尋水远，自愛逐連山。","雖在春风裏，猶從芳草间。","去程何用計，勝事且相关。","旅逸同羣鸟，悠悠往复還。"]', '诗', 'shi', '', NULL, '送友人南遊 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21d525f5-1980-46f2-abf3-6501563a9aef', '送裴二十一', '送裴二十一', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["多病長無事，開筵暫送君。","正愁帆帶雨，莫望水連雲。","客思閑偏極，川程遠更分。","不須論早晚，惆悵又離羣。"]', '["多病长無事，开筵暫送君。","正愁帆带雨，莫望水連云。","客思闲偏極，川程远更分。","不須論早晚，惆悵又離羣。"]', '诗', 'shi', '', NULL, '送裴二十一 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ef58313-2e18-49cf-90b3-6f96e24c0275', '送張判官罷使東歸', '送張判官罷使东归', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["白首辭知己，滄洲憶舊居。","落潮迴野艇，積雪臥官廬。","范叔寒猶在，周王歲欲除。","春山數畝地，歸去帶經鉏。"]', '["白首辞知己，滄洲憶旧居。","落潮迴野艇，積雪臥官廬。","范叔寒猶在，周王歲欲除。","春山數畝地，归去带經鉏。"]', '诗', 'shi', '', NULL, '送張判官罷使東歸 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2df0e3e0-b9af-4631-a112-d7ac89daf18d', '早春', '早春', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["微雨夜來歇，江南春色迴。","本驚時不住，還恐老相催。","人好千場醉，花無百日開。","豈堪滄海畔，爲客十年來。"]', '["微雨夜来歇，江南春色迴。","本驚时不住，還恐老相催。","人好千場醉，花無百日开。","豈堪滄海畔，爲客十年来。"]', '诗', 'shi', '', NULL, '早春 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3151345-6219-4360-b666-e62a5b22270d', '送青苗鄭判官歸江西', '送青苗鄭判官归江西', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["三苗餘古地，五稼滿秋田。","來問周公稅，歸輸漢俸錢。","江城寒背日，湓水暮連天。","南楚凋殘後，疲民賴爾憐。"]', '["三苗餘古地，五稼满秋田。","来问周公稅，归輸漢俸錢。","江城寒背日，湓水暮連天。","南楚凋殘後，疲民賴爾怜。"]', '诗', 'shi', '', NULL, '送青苗鄭判官歸江西 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cfb817b-fca9-487d-8355-fa04144fdeb6', '過包尊師山院', '過包尊師山院', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["賣藥曾相識，吹蕭此復聞。","杏花誰是主，桂樹獨留君。","漱玉臨丹井，圍碁訪白雲。","道經今爲寫，不慮惜鵝羣。"]', '["賣藥曾相識，吹蕭此复闻。","杏花誰是主，桂樹独留君。","漱玉臨丹井，圍碁訪白云。","道經今爲寫，不慮惜鵝羣。"]', '诗', 'shi', '', NULL, '過包尊師山院 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f64921ce-c218-4962-af65-b79b7e134ee7', '故女道士婉儀太原郭氏挽歌詞 一', '故女道士婉儀太原郭氏挽歌词 一', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["作範宮闈睦，歸真道藝超。","馭風仙路遠，背日帝宮遙。","鸞殿空留處，霓裳已罷朝。","淮王哀不盡，松柏但蕭蕭。"]', '["作範宮闈睦，归真道藝超。","馭风仙路远，背日帝宮遙。","鸾殿空留处，霓裳已罷朝。","淮王哀不尽，松柏但蕭蕭。"]', '诗', 'shi', '', NULL, '故女道士婉儀太原郭氏挽歌詞 一 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6343e0b2-b4cd-4155-b6b3-55b9f8660d7c', '故女道士婉儀太原郭氏挽歌詞 二', '故女道士婉儀太原郭氏挽歌词 二', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["宮禁恩長隔，神仙道已分。","人間驚早露，天上失朝雲。","逝水年無限，佳城日易曛。","簫聲將薤曲，哀斷不堪聞。"]', '["宮禁恩长隔，神仙道已分。","人间驚早露，天上失朝云。","逝水年無限，佳城日易曛。","簫声將薤曲，哀斷不堪闻。"]', '诗', 'shi', '', NULL, '故女道士婉儀太原郭氏挽歌詞 二 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32c9d409-9206-4100-817d-63c395dd832a', '少年行', '少年行', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["射飛誇侍獵，行樂愛聯鑣。","薦枕青蛾豔，鳴鞭白馬驕。","曲房珠翠合，深巷管弦調。","日晚春風裏，衣香滿路飄。"]', '["射飞誇侍獵，行乐愛聯鑣。","薦枕青蛾豔，鳴鞭白马驕。","曲房珠翠合，深巷管弦調。","日晚春风裏，衣香满路飄。"]', '诗', 'shi', '', NULL, '少年行 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d97de54-3443-4dfd-b80f-b1077c2d5171', '歸弋陽山居留別盧邵二侍御', '归弋陽山居留別盧邵二侍御', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["渺渺歸何處，沿流附客船。","久依鄱水住，頻稅越人田。","偶俗機偏少，安閑性所便。","祗應君少慣，又欲寄林泉。"]', '["渺渺归何处，沿流附客船。","久依鄱水住，頻稅越人田。","偶俗機偏少，安闲性所便。","祗應君少慣，又欲寄林泉。"]', '诗', 'shi', '', NULL, '歸弋陽山居留別盧邵二侍御 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6be8c63b-a2fd-46f5-b0e5-e43fc5305c4d', '赴江西湖上贈皇甫曾之宣州', '赴江西湖上贈皇甫曾之宣州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["莫恨扁舟去，川途我更遙。","東西潮渺渺，離別雨蕭蕭。","流水通春谷，青山過板橋。","天涯有來客，遲爾訪漁樵。"]', '["莫恨扁舟去，川途我更遙。","东西潮渺渺，離別雨蕭蕭。","流水通春谷，青山過板橋。","天涯有来客，遲爾訪漁樵。"]', '诗', 'shi', '', NULL, '赴江西湖上贈皇甫曾之宣州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6034f75a-a1fc-4ed2-aeec-a6f2d1c12c2c', '湘中紀行十首 湘妃廟', '湘中紀行十首 湘妃廟', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["荒祠古木暗，寂寂此江濆。","未作湘南雨，知爲何處雲。","苔痕斷珠履，草色帶羅裙。","莫唱迎仙曲，空山不可聞。"]', '["荒祠古木暗，寂寂此江濆。","未作湘南雨，知爲何处云。","苔痕斷珠履，草色带羅裙。","莫唱迎仙曲，空山不可闻。"]', '诗', 'shi', '', NULL, '湘中紀行十首 湘妃廟 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('698569ba-9ce6-4d94-9395-07d86d48634e', '湘中紀行十首 斑竹巖', '湘中紀行十首 斑竹巖', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["蒼梧在何處，斑竹自成林。","點點留殘淚，枝枝寄此心。","寒山響易滿，秋水影偏深。","欲覓樵人路，蒙籠不可尋。"]', '["蒼梧在何处，斑竹自成林。","点点留殘泪，枝枝寄此心。","寒山响易满，秋水影偏深。","欲覓樵人路，蒙籠不可尋。"]', '诗', 'shi', '', NULL, '湘中紀行十首 斑竹巖 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308280bc-9b1b-45fb-9778-723e13dee642', '湘中紀行十首 洞山陽', '湘中紀行十首 洞山陽', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["舊日仙成處，荒林客到稀。","白雲將犬去，芳草任人歸。","空谷無行徑，深山少落暉。","桃園幾家住，誰爲掃荆扉。"]', '["旧日仙成处，荒林客到稀。","白云將犬去，芳草任人归。","空谷無行徑，深山少落暉。","桃园幾家住，誰爲掃荆扉。"]', '诗', 'shi', '', NULL, '湘中紀行十首 洞山陽 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7152b1e3-efff-46de-8ab3-34ca517621d9', '湘中紀行十首 雲母溪', '湘中紀行十首 云母溪', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["雲母映溪水，溪流知幾春。","深藏武陵客，時過洞庭人。","白髮慚皎鏡，清光媚奫淪。","寥寥古松下，歲晚挂頭巾。"]', '["云母映溪水，溪流知幾春。","深藏武陵客，时過洞庭人。","白髮慚皎镜，清光媚奫淪。","寥寥古松下，歲晚挂头巾。"]', '诗', 'shi', '', NULL, '湘中紀行十首 雲母溪 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81fdf606-72d6-438a-9c74-db5e2554a52b', '湘中紀行十首 赤沙湖', '湘中紀行十首 赤沙湖', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["茫茫葭菼外，一望一霑衣。","秋水連天闊，涔陽何處歸。","沙鷗積暮雪，川日動寒暉。","楚客來相問，孤舟泊釣磯。"]', '["茫茫葭菼外，一望一霑衣。","秋水連天闊，涔陽何处归。","沙鷗積暮雪，川日动寒暉。","楚客来相问，孤舟泊釣磯。"]', '诗', 'shi', '', NULL, '湘中紀行十首 赤沙湖 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a42503d9-d919-48bc-a8ba-51c9bd3aea56', '湘中紀行十首 秋雲嶺', '湘中紀行十首 秋云嶺', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["山色無定姿，如煙復如黛。","孤峰夕陽後，翠嶺秋天外。","雲起遙蔽虧，江迴頻向背。","不知今遠近，到處猶相對。"]', '["山色無定姿，如煙复如黛。","孤峰夕陽後，翠嶺秋天外。","云起遙蔽虧，江迴頻向背。","不知今远近，到处猶相对。"]', '诗', 'shi', '', NULL, '湘中紀行十首 秋雲嶺 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('141ab67f-ae08-404c-856f-ae5bf31406ab', '湘中紀行十首 花石潭', '湘中紀行十首 花石潭', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["江楓日搖落，轉愛寒潭靜。","水色淡如空，山光復相映。","人閑流更慢，魚戲波難定。","楚客往來多，偏知白鷗性。"]', '["江楓日搖落，轉愛寒潭静。","水色淡如空，山光复相映。","人闲流更慢，鱼戲波难定。","楚客往来多，偏知白鷗性。"]', '诗', 'shi', '', NULL, '湘中紀行十首 花石潭 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14b9f2ba-3904-4b22-94a0-142c899a01c5', '湘中紀行十首 石圍峰', '湘中紀行十首 石圍峰', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["前山帶秋色，獨往秋江晚。","疊嶂入雲多，孤峰去人遠。","[夤]緣不可到，蒼翠空在眼。","渡口問漁家，桃源路深淺。"]', '["前山带秋色，独往秋江晚。","叠嶂入云多，孤峰去人远。","[夤]緣不可到，蒼翠空在眼。","渡口问漁家，桃源路深淺。"]', '诗', 'shi', '', NULL, '湘中紀行十首 石圍峰 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ea5e8c6-ccb7-4983-98c1-e1bb3daf0c81', '湘中紀行十首 浮石瀨', '湘中紀行十首 浮石瀨', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["秋月照瀟湘，月明聞盪槳。","石橫晚瀨急，水落寒沙廣。","衆嶺猨嘯重，空江人語響。","清暉朝復暮，如待扁舟賞。"]', '["秋月照瀟湘，月明闻盪槳。","石橫晚瀨急，水落寒沙廣。","衆嶺猨嘯重，空江人語响。","清暉朝复暮，如待扁舟賞。"]', '诗', 'shi', '', NULL, '湘中紀行十首 浮石瀨 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef8efd33-5aec-467c-a9f2-f87340dde6ec', '湘中紀行十首 橫龍渡', '湘中紀行十首 橫龙渡', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["空傳古岸下，曾見蛟龍去。","秋水晚沈沈，猶疑在深處。","亂聲沙上石，倒影雲中樹。","獨見一扁舟，樵人往來渡。"]', '["空傳古岸下，曾见蛟龙去。","秋水晚沈沈，猶疑在深处。","亂声沙上石，倒影云中樹。","独见一扁舟，樵人往来渡。"]', '诗', 'shi', '', NULL, '湘中紀行十首 橫龍渡 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b7523f5-78da-475b-814b-cf6e43e58eb3', '雜詠八首上禮部李侍郎 幽琴', '杂詠八首上禮部李侍郎 幽琴', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["月色滿軒白，琴聲宜夜闌。","飀飀青絲上，靜聽松風寒。","古調雖自愛，今人多不彈。","向君投此曲，所貴知音難。"]', '["月色满軒白，琴声宜夜闌。","飀飀青絲上，静听松风寒。","古調雖自愛，今人多不彈。","向君投此曲，所貴知音难。"]', '诗', 'shi', '', NULL, '雜詠八首上禮部李侍郎 幽琴 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b8b30c9-4f25-458c-bf31-f914ffc9ce99', '雜詠八首上禮部李侍郎 晚桃', '杂詠八首上禮部李侍郎 晚桃', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["四月深澗底，桃花方欲然。","寧知地勢下，遂使春風偏。","此意頗堪惜，無言誰爲傳。","過時君未賞，空媚幽林前。"]', '["四月深澗底，桃花方欲然。","寧知地勢下，遂使春风偏。","此意頗堪惜，無言誰爲傳。","過时君未賞，空媚幽林前。"]', '诗', 'shi', '', NULL, '雜詠八首上禮部李侍郎 晚桃 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e1ebca-d690-495d-9280-f75cffa60172', '雜詠八首上禮部李侍郎 疲馬', '杂詠八首上禮部李侍郎 疲马', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["玄黃一疲馬，筋力盡胡塵。","驤首北風夕，徘徊鳴向人。","誰憐棄置久，欲與駑駘親。","猶戀長城外，青青寒草春。"]', '["玄黄一疲马，筋力尽胡塵。","驤首北风夕，徘徊鳴向人。","誰怜棄置久，欲與駑駘親。","猶戀长城外，青青寒草春。"]', '诗', 'shi', '', NULL, '雜詠八首上禮部李侍郎 疲馬 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf32721c-143b-44ae-8cec-9c114f17b623', '雜詠八首上禮部李侍郎 春鏡', '杂詠八首上禮部李侍郎 春镜', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["寶鏡凌曙開，含虛淨如水。","獨懸秦臺上，萬象清光裏。","豈慮高鑒偏，但防流塵委。","不知娉婷色，回照今何似。"]', '["寶镜凌曙开，含虛淨如水。","独懸秦台上，万象清光裏。","豈慮高鑒偏，但防流塵委。","不知娉婷色，回照今何似。"]', '诗', 'shi', '', NULL, '雜詠八首上禮部李侍郎 春鏡 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce619ad9-c87f-4719-b56d-8993d7b4ab8c', '雜詠八首上禮部李侍郎 古劒', '杂詠八首上禮部李侍郎 古劒', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["龍泉閑古匣，苔蘚淪此地。","何意久藏鋒，翻令世人棄。","鐵衣今正澀，寶刃猶可試。","儻遇拂拭恩，應知剸犀利。"]', '["龙泉闲古匣，苔蘚淪此地。","何意久藏鋒，翻令世人棄。","鐵衣今正澀，寶刃猶可試。","儻遇拂拭恩，應知剸犀利。"]', '诗', 'shi', '', NULL, '雜詠八首上禮部李侍郎 古劒 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62a877ad-3fc8-4100-b202-41477229be6c', '雜詠八首上禮部李侍郎 舊井', '杂詠八首上禮部李侍郎 旧井', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["舊井依舊城，寒水深洞徹。","下看百餘尺，一鏡光不滅。","素綆久未垂，清涼尚含潔。","豈能無汲引，長訝君恩絕。"]', '["旧井依旧城，寒水深洞徹。","下看百餘尺，一镜光不滅。","素綆久未垂，清涼尚含潔。","豈能無汲引，长訝君恩絕。"]', '诗', 'shi', '', NULL, '雜詠八首上禮部李侍郎 舊井 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('352facdd-ac75-42aa-8604-624b3ed38096', '雜詠八首上禮部李侍郎 白鷺', '杂詠八首上禮部李侍郎 白鷺', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["亭亭常獨立，川上時延頸。","秋水寒白毛，夕陽弔孤影。","幽姿閑自媚，逸翮思一騁。","如有長風吹，青雲在俄頃。"]', '["亭亭常独立，川上时延頸。","秋水寒白毛，夕陽弔孤影。","幽姿闲自媚，逸翮思一騁。","如有长风吹，青云在俄頃。"]', '诗', 'shi', '', NULL, '雜詠八首上禮部李侍郎 白鷺 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc45421-ac3e-491e-845c-eff4daa8ae5e', '雜詠八首上禮部李侍郎 寒釭', '杂詠八首上禮部李侍郎 寒釭', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["向夕燈稍進，空堂彌寂寞。","光寒對愁人，時復一花落。","但恐明見累，何愁暗難托。","戀君秋夜永，無使蘭膏薄。"]', '["向夕灯稍進，空堂彌寂寞。","光寒对愁人，时复一花落。","但恐明见累，何愁暗难托。","戀君秋夜永，無使蘭膏薄。"]', '诗', 'shi', '', NULL, '雜詠八首上禮部李侍郎 寒釭 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('488b6b71-49c9-468a-8f22-3425eae37daa', '寄李侍御', '寄李侍御', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["舊國人未歸，芳洲草還碧。","年年湖上亭，悵望江南客。","驄馬入關西，白雲獨何適。","相思煙水外，唯有心不隔。"]', '["旧国人未归，芳洲草還碧。","年年湖上亭，悵望江南客。","驄马入关西，白云独何適。","相思煙水外，唯有心不隔。"]', '诗', 'shi', '', NULL, '寄李侍御 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a3161e7-9c31-432d-b843-107f9f1fac7a', '晚泊湘江懷故人', '晚泊湘江懷故人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["天涯片雲去，遙指帝鄉憶。","惆悵增暮情，瀟湘復秋色。","扁舟宿何處，落日羨歸翼。","萬里無故人，江鷗不相識。"]', '["天涯片云去，遙指帝乡憶。","惆悵增暮情，瀟湘复秋色。","扁舟宿何处，落日羨归翼。","万里無故人，江鷗不相識。"]', '诗', 'shi', '', NULL, '晚泊湘江懷故人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dac99dd-58f0-4275-b0f9-9ebaa15b246e', '過鄥三湖上書齋', '過鄥三湖上书斋', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["何事東南客，忘機一釣竿。","酒香開甕老，湖色對門寒。","向郭青山送，臨池白鳥看。","見君能浪跡，予亦厭微官。"]', '["何事东南客，忘機一釣竿。","酒香开甕老，湖色对门寒。","向郭青山送，臨池白鸟看。","见君能浪跡，予亦厭微官。"]', '诗', 'shi', '', NULL, '過鄥三湖上書齋 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28fe0cb5-04d4-473d-b1b9-523bf6d957dd', '從軍六首 一', '從軍六首 一', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["迴看虜騎合，城下漢兵稀。","白刃兩相向，黃雲愁不飛。","手中無尺鐵，徒欲突重圍。"]', '["迴看虜騎合，城下漢兵稀。","白刃兩相向，黄云愁不飞。","手中無尺鐵，徒欲突重圍。"]', '诗', 'shi', '', NULL, '從軍六首 一 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('162bb14f-83e0-4450-a6cd-9fd64bf2d47c', '從軍六首 二', '從軍六首 二', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["目極鴈門道，青青邊草春。","一身事征戰，匹馬同苦辛。","末路成白首，功歸天下人。"]', '["目極鴈门道，青青邊草春。","一身事征戰，匹马同苦辛。","末路成白首，功归天下人。"]', '诗', 'shi', '', NULL, '從軍六首 二 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e25e90a-ba40-4019-a216-6c2917acf794', '從軍六首 三', '從軍六首 三', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["倚劒白日暮，望鄉登戍樓。","北風吹羌笛，此夜關山愁。","迴首不無意，滹河空自流。"]', '["倚劒白日暮，望乡登戍楼。","北风吹羌笛，此夜关山愁。","迴首不無意，滹河空自流。"]', '诗', 'shi', '', NULL, '從軍六首 三 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eff304b-dc1d-42a9-96b2-472a41ddac85', '從軍六首 四', '從軍六首 四', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["黃沙一萬里，白首無人憐。","報國劒已折，歸鄉身幸全。","單于古臺下，邊色寒蒼然。"]', '["黄沙一万里，白首無人怜。","報国劒已折，归乡身幸全。","單于古台下，邊色寒蒼然。"]', '诗', 'shi', '', NULL, '從軍六首 四 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('407d703d-2756-458b-b5a5-da0e8f90dd68', '從軍六首 五', '從軍六首 五', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["落日更蕭條，北風動枯草。","將軍追虜騎，夜失陰山道。","戰敗仍樹勳，韓彭但空老。"]', '["落日更蕭條，北风动枯草。","將軍追虜騎，夜失陰山道。","戰敗仍樹勳，韓彭但空老。"]', '诗', 'shi', '', NULL, '從軍六首 五 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f6112f9-e619-4ce6-9d77-ba2a64f2bece', '從軍六首 六', '從軍六首 六', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["草枯秋塞上，望見漁陽郭。","胡馬嘶一聲，漢兵淚雙落。","誰爲吮瘡者，此事今人薄。"]', '["草枯秋塞上，望见漁陽郭。","胡马嘶一声，漢兵泪雙落。","誰爲吮瘡者，此事今人薄。"]', '诗', 'shi', '', NULL, '從軍六首 六 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfa4f6f9-c928-48a0-882a-b40308585505', '龍門八詠 闕口', '龙门八詠 闕口', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["秋山日搖落，秋水急波瀾。","獨見魚龍氣，長令煙雨寒。","誰窮造化力，空向兩崖看。"]', '["秋山日搖落，秋水急波瀾。","独见鱼龙氣，长令煙雨寒。","誰窮造化力，空向兩崖看。"]', '诗', 'shi', '', NULL, '龍門八詠 闕口 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57903765-0883-429a-aa86-584d9b2b7058', '龍門八詠 水東渡', '龙门八詠 水东渡', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["山葉傍崖赤，千峰秋色多。","夜泉發清響，寒渚生微波。","稍見沙上月，歸人爭渡河。"]', '["山葉傍崖赤，千峰秋色多。","夜泉發清响，寒渚生微波。","稍见沙上月，归人爭渡河。"]', '诗', 'shi', '', NULL, '龍門八詠 水東渡 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04daed88-7303-4b95-9402-95bfded35309', '龍門八詠 福公塔', '龙门八詠 福公塔', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["寂寞對伊水，經行長未還。","東流自朝暮，千載空雲山。","誰見白鷗鳥，無心洲渚間。"]', '["寂寞对伊水，經行长未還。","东流自朝暮，千載空云山。","誰见白鷗鸟，無心洲渚间。"]', '诗', 'shi', '', NULL, '龍門八詠 福公塔 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fd2afb8-37e6-49f8-a164-9880fe72f1f2', '龍門八詠 遠公龕', '龙门八詠 远公龕', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["松路向精舍，花龕歸老僧。","閑雲隨錫杖，落日低金繩。","入夜翠微裏，千峰明一燈。"]', '["松路向精舍，花龕归老僧。","闲云隨錫杖，落日低金繩。","入夜翠微裏，千峰明一灯。"]', '诗', 'shi', '', NULL, '龍門八詠 遠公龕 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2296a2c-e27b-4864-990e-c48e3eb31c09', '龍門八詠 石樓', '龙门八詠 石楼', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["隱隱見花閣，隔河映青林。","水田秋鴈下，山寺夜鐘深。","寂寞羣動息，風泉清道心。"]', '["隐隐见花閣，隔河映青林。","水田秋鴈下，山寺夜鐘深。","寂寞羣动息，风泉清道心。"]', '诗', 'shi', '', NULL, '龍門八詠 石樓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd0bcd8e-779c-4de4-9419-89367ce14598', '龍門八詠 下山', '龙门八詠 下山', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["誰識往來意，孤雲長自閑。","風寒未渡水，日暮更看山。","木落衆峰出，龍宮蒼翠間。"]', '["誰識往来意，孤云长自闲。","风寒未渡水，日暮更看山。","木落衆峰出，龙宮蒼翠间。"]', '诗', 'shi', '', NULL, '龍門八詠 下山 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37afabc0-a58f-41c4-9463-f95d69c6aab2', '龍門八詠 水西渡', '龙门八詠 水西渡', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["伊水搖鏡光，纖鱗如不隔。","千龕道傍古，一鳥沙上白。","何事還山雲，能留向城客。"]', '["伊水搖镜光，纖鱗如不隔。","千龕道傍古，一鸟沙上白。","何事還山云，能留向城客。"]', '诗', 'shi', '', NULL, '龍門八詠 水西渡 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('401cd681-5518-40a4-a9ee-e63d17ea107f', '龍門八詠 渡水', '龙门八詠 渡水', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["日暮下山來，千山暮鐘發。","不知波上棹，還弄山中月。","伊水連白雲，東南遠明滅。"]', '["日暮下山来，千山暮鐘發。","不知波上棹，還弄山中月。","伊水連白云，东南远明滅。"]', '诗', 'shi', '', NULL, '龍門八詠 渡水 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51d79199-8a00-456b-9bb2-9ec17eea3a2b', '月下聽砧', '月下听砧', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["夜靜掩寒城，清砧發何處？","聲聲擣秋月，腸斷盧龍戍。","未得寄征人，愁霜復愁露。"]', '["夜静掩寒城，清砧發何处？","声声擣秋月，腸斷盧龙戍。","未得寄征人，愁霜复愁露。"]', '诗', 'shi', '', NULL, '月下聽砧 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eca9c72d-2848-4031-9461-4a4039df5d91', '送丘爲赴上都', '送丘爲赴上都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["帝鄉何處是，歧路空垂泣。","楚思愁暮多，川程帶潮急。","潮歸人不歸，獨向空塘立。"]', '["帝乡何处是，歧路空垂泣。","楚思愁暮多，川程带潮急。","潮归人不归，独向空塘立。"]', '诗', 'shi', '', NULL, '送丘爲赴上都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52aed16e-eafb-4f0d-88d4-20e09fb7ca80', '題大理黃主簿湖上高齋', '題大理黄主簿湖上高斋', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["閉門湖水畔，自與白鷗親。","竟日窗中岫，終年林下人。","俗輕儒服弊，家厭法官貧。","多雨茅簷夜，空洲草徑春。","桃源君莫愛，且作漢朝臣。"]', '["閉门湖水畔，自與白鷗親。","竟日窗中岫，終年林下人。","俗轻儒服弊，家厭法官貧。","多雨茅簷夜，空洲草徑春。","桃源君莫愛，且作漢朝臣。"]', '诗', 'shi', '', NULL, '題大理黃主簿湖上高齋 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa3e46a2-eef6-4b77-a965-d0cba127e082', '平蕃曲三首 一', '平蕃曲三首 一', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["吹角報蕃營，迴軍欲洗兵。","已教青海外，自築漢家城。"]', '["吹角報蕃營，迴軍欲洗兵。","已教青海外，自築漢家城。"]', '诗', 'shi', '', NULL, '平蕃曲三首 一 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bcdcbdd-8b9e-4d91-9d18-242990e40b3f', '平蕃曲三首 二', '平蕃曲三首 二', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["渺渺戍煙孤，茫茫塞草枯。","隴頭那用閉，萬里不防胡。"]', '["渺渺戍煙孤，茫茫塞草枯。","隴头那用閉，万里不防胡。"]', '诗', 'shi', '', NULL, '平蕃曲三首 二 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74f91114-cd88-475c-bf98-70314c2e7746', '平蕃曲三首 三', '平蕃曲三首 三', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["絕漠大軍還，平沙獨戍閑。","空留一片石，萬古在燕山。"]', '["絕漠大軍還，平沙独戍闲。","空留一片石，万古在燕山。"]', '诗', 'shi', '', NULL, '平蕃曲三首 三 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e59f1f46-2be3-479b-87e7-f01ffa539d74', '送鄭說之歙州謁薛侍郎', '送鄭说之歙州謁薛侍郎', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["漂泊來千里，謳謠滿百城。","漢家尊太守，魯國重諸生。","俗變人難理，江傳水至清。","船經危石住，路入亂山行。","老得滄州趣，春傷白首情。","嘗聞馬南郡，門下有康成。"]', '["漂泊来千里，謳謠满百城。","漢家尊太守，魯国重諸生。","俗变人难理，江傳水至清。","船經危石住，路入亂山行。","老得滄州趣，春傷白首情。","嘗闻马南郡，门下有康成。"]', '诗', 'shi', '', NULL, '送鄭說之歙州謁薛侍郎 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b697cfce-8177-48df-b0a8-d770fa8499af', '題獨孤使君湖上林亭', '題独孤使君湖上林亭', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["出樹倚朱闌，吹鐃引上官。","老農持鍤拜，時稼捲簾看。","水對登龍淨，山當建隼寒。","夕陽湖草動，秋色渚田寬。","渤海人無事，荆州客獨安。","謝公何足比，來往石門難。"]', '["出樹倚朱闌，吹鐃引上官。","老農持鍤拜，时稼捲簾看。","水对登龙淨，山當建隼寒。","夕陽湖草动，秋色渚田寬。","渤海人無事，荆州客独安。","謝公何足比，来往石门难。"]', '诗', 'shi', '', NULL, '題獨孤使君湖上林亭 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1cc7c06-6bab-45e6-8a16-e404144f101d', '酬滁州李十六使君見贈', '酬滁州李十六使君见贈', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["滿鏡悲華髮，空山寄此身。","白雲家自有，黃卷業長貧。","嬾任垂竿老，狂因釀黍春。","桃花迷聖代，桂樹狎幽人。","幢蓋方臨郡，柴荆忝作鄰。","但愁千騎至，石路却生塵。"]', '["满镜悲华髮，空山寄此身。","白云家自有，黄卷業长貧。","嬾任垂竿老，狂因釀黍春。","桃花迷聖代，桂樹狎幽人。","幢蓋方臨郡，柴荆忝作鄰。","但愁千騎至，石路却生塵。"]', '诗', 'shi', '', NULL, '酬滁州李十六使君見贈 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26b9cb31-09d8-45ea-8d4f-9d3bdbdf4a25', '送嚴維赴河南充嚴中丞幕府', '送嚴維赴河南充嚴中丞幕府', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["久別耶溪客，來乘使者軒。","用才榮入幕，扶病喜同樽。","山屐留何處，江帆去獨翻。","暮情辭鏡水，秋夢識雲門。","蓮府開花萼，桃園寄子孫。","何當舉嚴助，徧沐漢朝恩。"]', '["久別耶溪客，来乘使者軒。","用才榮入幕，扶病喜同樽。","山屐留何处，江帆去独翻。","暮情辞镜水，秋梦識云门。","蓮府开花萼，桃园寄子孫。","何當舉嚴助，徧沐漢朝恩。"]', '诗', 'shi', '', NULL, '送嚴維赴河南充嚴中丞幕府 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('908bc080-beaa-40f1-9ce5-cab722b30019', '酬包諫議佶見寄之什', '酬包諫議佶见寄之什', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["佐郡媿頑疎，殊方親里閭。","家貧寒未度，身老歲將除。","過雪山僧至，依陽野客舒。","藥陳隨遠宦，梅發對幽居。","落日棲鴞鳥，行人遺鯉魚。","高文不可和，空媿學相如。"]', '["佐郡媿頑疎，殊方親里閭。","家貧寒未度，身老歲將除。","過雪山僧至，依陽野客舒。","藥陳隨远宦，梅發对幽居。","落日棲鴞鸟，行人遺鯉鱼。","高文不可和，空媿学相如。"]', '诗', 'shi', '', NULL, '酬包諫議佶見寄之什 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10818fd5-8ff5-4256-8615-064e0c9ccb91', '棲霞寺東峰尋南齊明徵君故居', '棲霞寺东峰尋南齊明徵君故居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["山人今不見，山鳥自相從。","長嘯辭明主，終身臥此峰。","泉源通石徑，磵戶掩塵容。","古墓依寒草，前朝寄老松。","片雲生斷壁，萬壑遍疎鐘。","惆悵空歸去，猶疑林下逢。"]', '["山人今不见，山鸟自相從。","长嘯辞明主，終身臥此峰。","泉源通石徑，磵戶掩塵容。","古墓依寒草，前朝寄老松。","片云生斷壁，万壑遍疎鐘。","惆悵空归去，猶疑林下逢。"]', '诗', 'shi', '', NULL, '棲霞寺東峰尋南齊明徵君故居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e803c0c-31c5-44d3-8dd2-be3360578a39', '奉和趙給事使君留贈李婺州舍人兼謝舍人別駕之什', '奉和趙給事使君留贈李婺州舍人兼謝舍人別駕之什', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["便道訪情親，東方千騎塵。","禁深分直夜，地遠獨行春。","絳闕辭明主，滄洲識近臣。","雲山隨候吏，雞犬逐歸人。","庭顧婆娑老，邦傳蔽芾新。","玄暉翻佐理，聞到郡齋頻。"]', '["便道訪情親，东方千騎塵。","禁深分直夜，地远独行春。","絳闕辞明主，滄洲識近臣。","云山隨候吏，雞犬逐归人。","庭顧婆娑老，邦傳蔽芾新。","玄暉翻佐理，闻到郡斋頻。"]', '诗', 'shi', '', NULL, '奉和趙給事使君留贈李婺州舍人兼謝舍人別駕之什 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38241ee3-f448-4411-b490-84c038c323ff', '行營酬呂侍御時尚書問罪襄陽軍次漢東境上侍御以州鄰寇賊復有水火迫於征稅詩以見諭', '行營酬呂侍御时尚书问罪襄陽軍次漢东境上侍御以州鄰寇賊复有水火迫於征稅诗以见諭', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["不敢淮南臥，來趨漢將營。","受辭瞻左鉞，扶疾往前旌。","井稅鶉衣樂，壺漿鶴髮迎。","水歸餘斷岸，烽至掩孤城。","晚日歸千騎，秋風合五兵。","孔璋才素健，早晚檄書成。"]', '["不敢淮南臥，来趨漢將營。","受辞瞻左鉞，扶疾往前旌。","井稅鶉衣乐，壺漿鹤髮迎。","水归餘斷岸，烽至掩孤城。","晚日归千騎，秋风合五兵。","孔璋才素健，早晚檄书成。"]', '诗', 'shi', '', NULL, '行營酬呂侍御時尚書問罪襄陽軍次漢東境上侍御以州鄰寇賊復有水火迫於征稅詩以見諭 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5150a64f-f1ed-4fce-a76c-00afcab2de64', '登遷仁樓酬子壻李穆', '登遷仁楼酬子壻李穆', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["臨風敞麗譙，落日聽吹鐃。","歸路空迴首，新章已在腰。","非才受官謗，無政作人謠。","儉歲安三戶，餘年寄六條。","春蕪生楚國，古樹過隋朝。","賴有東牀客，池塘免寂寥。"]', '["臨风敞丽譙，落日听吹鐃。","归路空迴首，新章已在腰。","非才受官謗，無政作人謠。","儉歲安三戶，餘年寄六條。","春蕪生楚国，古樹過隋朝。","賴有东牀客，池塘免寂寥。"]', '诗', 'shi', '', NULL, '登遷仁樓酬子壻李穆 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f15966f6-c014-40a1-b09a-1d2af25df2c5', '別李氏女子', '別李氏女子', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["念爾嫁猶近，稚年那別親。","臨歧方教誨，所貴和六姻。","俛首戴荆釵，欲拜淒且嚬。","本來儒家子，莫恥梁鴻貧。","漢川若可涉，水清石磷磷。","天涯遠鄉婦，月下孤舟人。"]', '["念爾嫁猶近，稚年那別親。","臨歧方教誨，所貴和六姻。","俛首戴荆釵，欲拜淒且嚬。","本来儒家子，莫恥梁鴻貧。","漢川若可涉，水清石磷磷。","天涯远乡婦，月下孤舟人。"]', '诗', 'shi', '', NULL, '別李氏女子 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dae41b00-bbdf-4a94-a3ff-c18c4e95c298', '長沙早春雪後臨湘水呈同遊諸子', '长沙早春雪後臨湘水呈同游諸子', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["汀洲暖漸淥，煙景淡相和。","舉目方如此，歸心豈奈何。","日華浮野雪，春色染湘波。","北渚生芳草，東風變舊柯。","江山古思遠，猨鳥暮情多。","君問漁人意，滄浪自有歌。"]', '["汀洲暖漸淥，煙景淡相和。","舉目方如此，归心豈奈何。","日华浮野雪，春色染湘波。","北渚生芳草，东风变旧柯。","江山古思远，猨鸟暮情多。","君问漁人意，滄浪自有歌。"]', '诗', 'shi', '', NULL, '長沙早春雪後臨湘水呈同遊諸子 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('935aa372-f84f-482b-be94-a1c9347b7776', '自道林寺西入石路至麓山寺過法崇禪師故居', '自道林寺西入石路至麓山寺過法崇禪師故居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["山僧候谷口，石路拂莓苔。","深入泉源去，遙從樹杪回。","香隨青靄散，鐘過白雲來。","野雪空齋掩，山風古殿開。","桂寒知自發，松老問誰栽。","惆悵湘江水，何人更渡杯。"]', '["山僧候谷口，石路拂莓苔。","深入泉源去，遙從樹杪回。","香隨青靄散，鐘過白云来。","野雪空斋掩，山风古殿开。","桂寒知自發，松老问誰栽。","惆悵湘江水，何人更渡杯。"]', '诗', 'shi', '', NULL, '自道林寺西入石路至麓山寺過法崇禪師故居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06b617aa-b5b4-4a26-8162-4ce3a73c1d4c', '和袁郎中破賊後軍行過剡中山水謹上太尉', '和袁郎中破賊後軍行過剡中山水謹上太尉', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["剡路除荆棘，王師罷鼓鼙。","農歸滄海畔，圍解赤城西。","赦罪春陽發，收兵太白低。","遠峰來馬首，橫笛入猨啼。","蘭渚催新幄，桃源識故蹊。","已聞開閣待，誰許臥東溪。"]', '["剡路除荆棘，王師罷鼓鼙。","農归滄海畔，圍解赤城西。","赦罪春陽發，收兵太白低。","远峰来马首，橫笛入猨啼。","蘭渚催新幄，桃源識故蹊。","已闻开閣待，誰許臥东溪。"]', '诗', 'shi', '', NULL, '和袁郎中破賊後軍行過剡中山水謹上太尉 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18bbdbb6-a942-4c8e-9707-7e082ffa1ef4', '送鄭十二還廬山別業', '送鄭十二還廬山別業', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["潯陽數畝宅，歸臥掩柴關。","谷口何人待，門前秋草閑。","忘機賣藥罷，無語杖藜還。","舊筍成寒竹，空齋向暮山。","水流經舍下，雲去到人間。","桂樹花應發，因行寄一攀。"]', '["潯陽數畝宅，归臥掩柴关。","谷口何人待，门前秋草闲。","忘機賣藥罷，無語杖藜還。","旧筍成寒竹，空斋向暮山。","水流經舍下，云去到人间。","桂樹花應發，因行寄一攀。"]', '诗', 'shi', '', NULL, '送鄭十二還廬山別業 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed2b57e5-df5b-4602-9c97-e0b5b5b8b50d', '至饒州尋陶十七不在寄贈', '至饒州尋陶十七不在寄贈', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["謫宦投東道，逢君已北轅。","孤蓬向何處，五柳不開門。","去國空迴首，懷賢欲訴冤。","梅枝橫嶺嶠，竹路過湘源。","月下高秋雁，天南獨夜猨。","離心與流水，萬里共朝昏。"]', '["謫宦投东道，逢君已北轅。","孤蓬向何处，五柳不开门。","去国空迴首，懷賢欲訴冤。","梅枝橫嶺嶠，竹路過湘源。","月下高秋雁，天南独夜猨。","離心與流水，万里共朝昏。"]', '诗', 'shi', '', NULL, '至饒州尋陶十七不在寄贈 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e1e7be0-dc30-450d-bca7-69234e85b2d4', '奉陪鄭中丞自宣州解印與諸姪宴餘干後溪', '奉陪鄭中丞自宣州解印與諸姪宴餘干後溪', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["跡遠親魚鳥，功成厭鼓鼙。","林中阮生集，池上謝公題。","戶牖垂藤合，藩離插槿齊。","夕陽山向背，春草水東西。","度雨諸峰出，看花幾路迷。","何勞問秦漢，更入武陵溪。"]', '["跡远親鱼鸟，功成厭鼓鼙。","林中阮生集，池上謝公題。","戶牖垂藤合，藩離插槿齊。","夕陽山向背，春草水东西。","度雨諸峰出，看花幾路迷。","何勞问秦漢，更入武陵溪。"]', '诗', 'shi', '', NULL, '奉陪鄭中丞自宣州解印與諸姪宴餘干後溪 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5615ec93-8265-4b7c-9d3d-058e76c99566', '同諸公袁郎中宴筵喜加章服', '同諸公袁郎中宴筵喜加章服', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["手詔來筵上，腰金向粉闈。","勳名傳舊閣，蹈舞著新衣。","白社同遊在，滄洲此會稀。","寒笳發後殿，秋草送西歸。","世難常摧敵，時閑已息機。","魯連功可讓，千載一相揮。"]', '["手詔来筵上，腰金向粉闈。","勳名傳旧閣，蹈舞著新衣。","白社同游在，滄洲此會稀。","寒笳發後殿，秋草送西归。","世难常摧敵，时闲已息機。","魯連功可讓，千載一相揮。"]', '诗', 'shi', '', NULL, '同諸公袁郎中宴筵喜加章服 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1a1e17f-6619-4f7d-9831-afe9c8e601ca', '毘陵送鄒結先赴河南充判官', '毘陵送鄒結先赴河南充判官', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["王事相逢少，雲山奈別何。","芳年臨水怨，瓜步上潮過。","客路方經楚，鄉心共渡河。","凋殘春草在，離亂故城多。","罷戰逢時泰，輕徭佇俗和。","東西此分手，惆悵恨煙波。"]', '["王事相逢少，云山奈別何。","芳年臨水怨，瓜步上潮過。","客路方經楚，乡心共渡河。","凋殘春草在，離亂故城多。","罷戰逢时泰，轻徭佇俗和。","东西此分手，惆悵恨煙波。"]', '诗', 'shi', '', NULL, '毘陵送鄒結先赴河南充判官 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2115d608-8d0a-446c-956c-8d310f4ab0f3', '送徐大夫赴廣州', '送徐大夫赴廣州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["上將壇場拜，南荒羽檄招。","遠人來百越，元老事三朝。","霧繞龍山暗，山連象郡遙。","路分江淼淼，軍動馬蕭蕭。","畫角知秋氣，樓船逐暮潮。","當令輸貢賦，不使外夷驕。"]', '["上將壇場拜，南荒羽檄招。","远人来百越，元老事三朝。","霧繞龙山暗，山連象郡遙。","路分江淼淼，軍动马蕭蕭。","畫角知秋氣，楼船逐暮潮。","當令輸貢賦，不使外夷驕。"]', '诗', 'shi', '', NULL, '送徐大夫赴廣州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81147d62-8132-4987-a4fc-6eab94d46d02', '九日題蔡國公主樓', '九日題蔡国公主楼', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["主第人何在，重陽客暫尋。","水餘龍鏡色，雲罷鳳簫音。","暗牖藏昏曉，蒼苔換古今。","晴山卷幔出，秋草閉門深。","籬菊仍新吐，庭槐尚舊陰。","年年畫梁燕，來去豈無心。"]', '["主第人何在，重陽客暫尋。","水餘龙镜色，云罷鳳簫音。","暗牖藏昏晓，蒼苔換古今。","晴山卷幔出，秋草閉门深。","籬菊仍新吐，庭槐尚旧陰。","年年畫梁燕，来去豈無心。"]', '诗', 'shi', '', NULL, '九日題蔡國公主樓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c755dfcb-420c-4ee4-8224-dd1833a6de17', '送荀八過山陰舊縣兼寄剡中諸官', '送荀八過山陰旧縣兼寄剡中諸官', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["訪舊山陰縣，扁舟到海涯。","故林嗟滿歲，春草憶佳期。","晚景千峰亂，晴江一鳥遲。","桂香留客處，楓暗泊舟時。","舊石曹娥篆，空山夏禹祠。","剡溪多隱吏，君去道相思。"]', '["訪旧山陰縣，扁舟到海涯。","故林嗟满歲，春草憶佳期。","晚景千峰亂，晴江一鸟遲。","桂香留客处，楓暗泊舟时。","旧石曹娥篆，空山夏禹祠。","剡溪多隐吏，君去道相思。"]', '诗', 'shi', '', NULL, '送荀八過山陰舊縣兼寄剡中諸官 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('756ff877-de47-47d1-a3f9-974f27b18e9d', '奉餞元侍郎加豫章採訪兼賜章服', '奉餞元侍郎加豫章採訪兼賜章服', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["任重兼烏府，時平偃豹韜。","澄清湘水變，分別楚山高。","花對彤襜發，霜和白雪操。","黃金裝舊馬，青草換新袍。","嶺暗猿啼月，江寒鷺映濤。","豫章生宇下，無使翳篷蒿。"]', '["任重兼烏府，时平偃豹韜。","澄清湘水变，分別楚山高。","花对彤襜發，霜和白雪操。","黄金裝旧马，青草換新袍。","嶺暗猿啼月，江寒鷺映濤。","豫章生宇下，無使翳篷蒿。"]', '诗', 'shi', '', NULL, '奉餞元侍郎加豫章採訪兼賜章服 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f36b70a5-b185-47b6-a39b-07f8878f2053', '奉餞郎中四兄罷餘杭太守承恩加侍御史充行軍司馬赴汝南行營', '奉餞郎中四兄罷餘杭太守承恩加侍御史充行軍司马赴汝南行營', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["星使三江上，天波萬里通。","權分金節重，恩借鐵冠雄。","梅吹前軍發，棠陰舊府空。","殘春錦障外，初日羽旗東。","岸柳遮浮鷁，江花隔避驄。","離心在何處，芳草滿吳宮。"]', '["星使三江上，天波万里通。","權分金節重，恩借鐵冠雄。","梅吹前軍發，棠陰旧府空。","殘春錦障外，初日羽旗东。","岸柳遮浮鷁，江花隔避驄。","離心在何处，芳草满吳宮。"]', '诗', 'shi', '', NULL, '奉餞郎中四兄罷餘杭太守承恩加侍御史充行軍司馬赴汝南行營 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c26804e-1725-4922-a485-5574f6c0dbfb', '送賈侍御克復後入京', '送賈侍御克复後入京', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["對酒心不樂，見君動行舟。","回看暮帆隱，獨向空江愁。","晴雲淡初夜，春塘深慢流。","溫顏風霜霽，喜氣煙塵收。","馳馹數千里，朝天十二樓。","因之報親愛，白髮生滄洲。"]', '["对酒心不乐，见君动行舟。","回看暮帆隐，独向空江愁。","晴云淡初夜，春塘深慢流。","溫顏风霜霽，喜氣煙塵收。","驰馹數千里，朝天十二楼。","因之報親愛，白髮生滄洲。"]', '诗', 'shi', '', NULL, '送賈侍御克復後入京 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b610632-ac8e-401c-9c68-625ddb8e1667', '會稽王處士草堂壁畫衡霍諸山', '會稽王处士草堂壁畫衡霍諸山', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["粉壁衡霍近，羣峰如可攀。","能令堂上客，見盡湖南山。","青翠數千仞，飛來方丈間。","歸雲無處滅，去鳥何時還？","勝事日相對，主人常獨閑。","稍看林壑晚，佳氣生重關。"]', '["粉壁衡霍近，羣峰如可攀。","能令堂上客，见尽湖南山。","青翠數千仞，飞来方丈间。","归云無处滅，去鸟何时還？","勝事日相对，主人常独闲。","稍看林壑晚，佳氣生重关。"]', '诗', 'shi', '', NULL, '會稽王處士草堂壁畫衡霍諸山 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85b682be-71a3-4a8a-abbe-bd5934ae549e', '惠福寺與陳留諸官茶會', '惠福寺與陳留諸官茶會', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["到此機事遣，自嫌塵網迷。","因知萬法幻，盡與浮雲齊。","疎竹映高枕，空花隨杖藜。","香飄諸天外，日隱雙林西。","傲吏方見狎，真僧幸相攜。","能令歸客意，不復還東溪。"]', '["到此機事遣，自嫌塵網迷。","因知万法幻，尽與浮云齊。","疎竹映高枕，空花隨杖藜。","香飄諸天外，日隐雙林西。","傲吏方见狎，真僧幸相携。","能令归客意，不复還东溪。"]', '诗', 'shi', '', NULL, '惠福寺與陳留諸官茶會 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad6524b0-eae7-4fdf-8129-bc88194abc5c', '金陵西泊舟臨江樓', '金陵西泊舟臨江楼', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["蕭條金陵郭，舊是帝王州。","日暮望鄉處，雲邊江樹秋。","楚雲不可託，楚水只堪愁。","行客千萬里，滄波朝暮流。","迢迢洛陽夢，獨臥清川樓。","異鄉共如此，孤帆難久遊。"]', '["蕭條金陵郭，旧是帝王州。","日暮望乡处，云邊江樹秋。","楚云不可託，楚水只堪愁。","行客千万里，滄波朝暮流。","迢迢洛陽梦，独臥清川楼。","異乡共如此，孤帆难久游。"]', '诗', 'shi', '', NULL, '金陵西泊舟臨江樓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29c0368f-acb9-49d1-ba9f-e9ee5f3c8254', '題靈祐上人法華院木蘭花', '題靈祐上人法华院木蘭花', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["庭種南中樹，年華幾度新。","已依初地長，獨發舊園春。","映日成華蓋，搖風散錦茵。","色空榮落處，香醉往來人。","菡萏千燈遍，芳菲一雨均。","高柯儻爲檝，渡海有良因。"]', '["庭種南中樹，年华幾度新。","已依初地长，独發旧园春。","映日成华蓋，搖风散錦茵。","色空榮落处，香醉往来人。","菡萏千灯遍，芳菲一雨均。","高柯儻爲檝，渡海有良因。"]', '诗', 'shi', '', NULL, '題靈祐上人法華院木蘭花 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a7fb5d2-8d09-4129-a8b8-0aac8c405aba', '宿嚴維宅送包佶', '宿嚴維宅送包佶', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["江湖同避地，分首自依依。","盡室今爲客，驚秋空念歸。","歲儲無別墅，寒服羨鄰機。","草色春橋晚，蟬聲江樹稀。","夜深宜共醉，時難忍相違。","何事隨陽雁，汀洲忽背飛。"]', '["江湖同避地，分首自依依。","尽室今爲客，驚秋空念归。","歲儲無別墅，寒服羨鄰機。","草色春橋晚，蟬声江樹稀。","夜深宜共醉，时难忍相違。","何事隨陽雁，汀洲忽背飞。"]', '诗', 'shi', '', NULL, '宿嚴維宅送包佶 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('965d3eb4-7c68-405d-b216-42945066d7d8', '送從弟貶袁州', '送從弟貶袁州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["何事成遷客，思歸不見鄉。","遊吳經萬里，弔屈向三湘。","水與荆巫接，山通鄢郢長。","名羞黃綬繫，身是白眉郎。","獨結南枝恨，應思北雁行。","憂來沽楚酒，老鬢莫凝霜。"]', '["何事成遷客，思归不见乡。","游吳經万里，弔屈向三湘。","水與荆巫接，山通鄢郢长。","名羞黄綬繫，身是白眉郎。","独結南枝恨，應思北雁行。","憂来沽楚酒，老鬢莫凝霜。"]', '诗', 'shi', '', NULL, '送從弟貶袁州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43e0f03e-a137-4285-ad9b-a50dad4ecb79', '無錫東郭送友人遊越', '無錫东郭送友人游越', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["客路風霜曉，郊原春興餘。","平蕪不可望，遊子去何如。","煙水乘湖闊，雲山適越初。","舊都懷作賦，古穴覓藏書。","碑缺曹娥宅，林荒逸少居。","江湖無限意，非獨爲樵漁。"]', '["客路风霜晓，郊原春兴餘。","平蕪不可望，游子去何如。","煙水乘湖闊，云山適越初。","旧都懷作賦，古穴覓藏书。","碑缺曹娥宅，林荒逸少居。","江湖無限意，非独爲樵漁。"]', '诗', 'shi', '', NULL, '無錫東郭送友人遊越 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('762e2c1d-e5d5-47e3-8167-71fd4c0c8d6b', '送邵州判官往南', '送邵州判官往南', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["看君發原隰，駟牡志皇皇。","始罷滄江令，還隨粉署郎。","海沂軍未息，河兗歲仍荒。","征稅人全少，榛蕪虜近亡。","新知行宋遠，相望隔淮長。","早晚裁書寄，銀鉤佇八行。"]', '["看君發原隰，駟牡志皇皇。","始罷滄江令，還隨粉署郎。","海沂軍未息，河兗歲仍荒。","征稅人全少，榛蕪虜近亡。","新知行宋远，相望隔淮长。","早晚裁书寄，銀鉤佇八行。"]', '诗', 'shi', '', NULL, '送邵州判官往南 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd4d784-6ea3-4707-9a65-719ddbfeed65', '出豐縣界寄韓明府', '出豐縣界寄韓明府', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["迴首古原上，未能辭舊鄉。","西風收暮雨，隱隱分芒碭。","賢友此爲邑，令名滿徐方。","音容想在眼，暫若升琴堂。","疲馬顧春草，行人看夕陽。","自非傳尺素，誰爲論中腸。"]', '["迴首古原上，未能辞旧乡。","西风收暮雨，隐隐分芒碭。","賢友此爲邑，令名满徐方。","音容想在眼，暫若升琴堂。","疲马顧春草，行人看夕陽。","自非傳尺素，誰爲論中腸。"]', '诗', 'shi', '', NULL, '出豐縣界寄韓明府 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cb49e2e-45c9-49d3-8ef0-dbded948d362', '別陳留諸官', '別陳留諸官', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["戀此東道主，能令西上遲。","徘徊暮郊別，惆悵秋風時。","上國邈千里，夷門難再期。","行人望落日，歸馬嘶空陂。","不愧寶刀贈，維懷瓊樹枝。","音塵倘未接，夢寐徒相思。"]', '["戀此东道主，能令西上遲。","徘徊暮郊別，惆悵秋风时。","上国邈千里，夷门难再期。","行人望落日，归马嘶空陂。","不愧寶刀贈，維懷瓊樹枝。","音塵倘未接，梦寐徒相思。"]', '诗', 'shi', '', NULL, '別陳留諸官 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feed1bff-0872-43b5-9ae2-8611dbe59db7', '觀李湊所畫美人障子', '观李湊所畫美人障子', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["愛爾含天姿，丹青有殊智。","無間已得象，象外更生意。","西子不可見，千載無重還。","空令浣沙態，猶在含毫間。","一笑豈易得，雙蛾如有情。","窗風不舉袖，但覺羅衣輕。","華堂翠幕春風來，內閣金屏曙色開。","此中一見亂人目，只疑行到雲陽臺。"]', '["愛爾含天姿，丹青有殊智。","無间已得象，象外更生意。","西子不可见，千載無重還。","空令浣沙態，猶在含毫间。","一笑豈易得，雙蛾如有情。","窗风不舉袖，但覺羅衣轻。","华堂翠幕春风来，內閣金屏曙色开。","此中一见亂人目，只疑行到云陽台。"]', '诗', 'shi', '', NULL, '觀李湊所畫美人障子 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96bd1f67-43ad-44b6-9030-deb2eddedf99', '送史判官奏事之靈武兼寄巴西親故', '送史判官奏事之靈武兼寄巴西親故', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["中州日紛梗，天地何時泰。","獨有西歸心，遙懸夕陽外。","故人奉章奏，此去論利害。","陽雁南渡江，征驂去相背。","因君欲寄遠，何處問親愛。","空使滄洲人，相思減衣帶。"]', '["中州日紛梗，天地何时泰。","独有西归心，遙懸夕陽外。","故人奉章奏，此去論利害。","陽雁南渡江，征驂去相背。","因君欲寄远，何处问親愛。","空使滄洲人，相思減衣带。"]', '诗', 'shi', '', NULL, '送史判官奏事之靈武兼寄巴西親故 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a7b52ec-6cea-46b5-a1e1-6ad7eda7ab2b', '自鄱陽還道中寄褚徵君', '自鄱陽還道中寄褚徵君', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["南風日夜起，萬里孤帆漾。","元氣連洞庭，夕陽落波上。","故人煙水隔，復此遙相望。","江信久寂寥，楚雲獨惆悵。","愛君清川口，弄月時櫂唱。","白首無子孫，一生自疎曠。"]', '["南风日夜起，万里孤帆漾。","元氣連洞庭，夕陽落波上。","故人煙水隔，复此遙相望。","江信久寂寥，楚云独惆悵。","愛君清川口，弄月时櫂唱。","白首無子孫，一生自疎曠。"]', '诗', 'shi', '', NULL, '自鄱陽還道中寄褚徵君 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3238941-e181-4685-a0d0-c8d55bd5f4dd', '石梁湖有寄', '石梁湖有寄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["故人千里道，滄波一年別。","夜上明月樓，相思楚天闊。","瀟瀟清秋暮，嫋嫋涼風發。","湖色淡不流，沙鷗遠還滅。","煙波日已遠，音問日已絕。","歲晏空含情，江臯綠芳歇。"]', '["故人千里道，滄波一年別。","夜上明月楼，相思楚天闊。","瀟瀟清秋暮，嫋嫋涼风發。","湖色淡不流，沙鷗远還滅。","煙波日已远，音问日已絕。","歲晏空含情，江臯綠芳歇。"]', '诗', 'shi', '', NULL, '石梁湖有寄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f723e68-0ccf-4eea-a9ca-496d17a7449a', '送沈少府之任淮南', '送沈少府之任淮南', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["惜君滯南楚，枳棘徒棲鳳。","獨與千里帆，春風遠相送。","此行山水好，時物亦應衆。","一鳥飛長淮，百花滿雲夢。","相期丹霄路，遙聽清風頌。","勿爲州縣卑，時來自爲用。"]', '["惜君滯南楚，枳棘徒棲鳳。","独與千里帆，春风远相送。","此行山水好，时物亦應衆。","一鸟飞长淮，百花满云梦。","相期丹霄路，遙听清风頌。","勿爲州縣卑，时来自爲用。"]', '诗', 'shi', '', NULL, '送沈少府之任淮南 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8859c9be-c859-4a10-972d-b278cb053731', '嚴子瀨東送馬處直歸蘇', '嚴子瀨东送马处直归蘇', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["望君舟已遠，落日潮未退。","目送滄海帆，人行白雲外。","江中遠回首，波上生微靄。","秋色姑蘇臺，寒流子陵瀨。","相送苦易散，動別知難會。","從此日相思，空令減衣帶。"]', '["望君舟已远，落日潮未退。","目送滄海帆，人行白云外。","江中远回首，波上生微靄。","秋色姑蘇台，寒流子陵瀨。","相送苦易散，动別知难會。","從此日相思，空令減衣带。"]', '诗', 'shi', '', NULL, '嚴子瀨東送馬處直歸蘇 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15a02240-9c03-4376-87ae-a8388a668b0a', '宿懷仁縣南湖寄東海荀處士', '宿懷仁縣南湖寄东海荀处士', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["向夕歛微雨，晴開湖上天。","離人正惆悵，新月愁嬋娟。","佇立白沙曲，相思滄海邊。","浮雲自來去，此意誰能傳。","一水不相見，千峰隨客船。","寒塘起孤雁，夜色分鹽田。","時復一延首，憶君如眼前。"]', '["向夕歛微雨，晴开湖上天。","離人正惆悵，新月愁嬋娟。","佇立白沙曲，相思滄海邊。","浮云自来去，此意誰能傳。","一水不相见，千峰隨客船。","寒塘起孤雁，夜色分鹽田。","时复一延首，憶君如眼前。"]', '诗', 'shi', '', NULL, '宿懷仁縣南湖寄東海荀處士 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21a572f5-8e1d-4ab2-9c3f-40e3a242361f', '初至洞庭懷灞陵別業', '初至洞庭懷灞陵別業', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["長安邈千里，日夕懷雙闕。","已是洞庭人，猶看灞陵月。","誰堪去鄉意，親戚想天末。","昨夜夢中歸，煙波覺來闊。","江臯見芳草，孤客心欲絕。","豈訝青春來，但傷經時別。","長天不可望，鳥與浮雲沒。"]', '["长安邈千里，日夕懷雙闕。","已是洞庭人，猶看灞陵月。","誰堪去乡意，親戚想天末。","昨夜梦中归，煙波覺来闊。","江臯见芳草，孤客心欲絕。","豈訝青春来，但傷經时別。","长天不可望，鸟與浮云沒。"]', '诗', 'shi', '', NULL, '初至洞庭懷灞陵別業 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('333eb65d-8cbb-4c46-9a58-0b58c8fa4ae3', '題蕭郎中開元寺新構幽寂亭', '題蕭郎中开元寺新構幽寂亭', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["康樂愛山水，賞心千載同。","結茅依翠微，伐木開蒙籠。","孤峰倚青霄，一徑去不窮。","候客石苔上，禮僧雲樹中。","曠然見滄洲，自遠來清風。","五馬留谷口，雙旌薄煙虹。","沈沈衆香積，眇眇諸天空。","獨往應未遂，蒼生思謝公。"]', '["康乐愛山水，賞心千載同。","結茅依翠微，伐木开蒙籠。","孤峰倚青霄，一徑去不窮。","候客石苔上，禮僧云樹中。","曠然见滄洲，自远来清风。","五马留谷口，雙旌薄煙虹。","沈沈衆香積，眇眇諸天空。","独往應未遂，蒼生思謝公。"]', '诗', 'shi', '', NULL, '題蕭郎中開元寺新構幽寂亭 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79df0612-509b-4015-a637-b90d251ec8a1', '同姜濬題裴式微餘干東齋', '同姜濬題裴式微餘干东斋', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["世事終成夢，生涯欲半過。","白雲心已矣，滄海意如何。","藜杖全吾道，榴花養太和。","春風騎馬醉，江月釣魚歌。","散帙看蟲蠹，開門見雀羅。","遠山終日在，芳草傍人多。","吏體莊生傲，方言楚俗譌。","屈平君莫弔，腸斷洞庭波。"]', '["世事終成梦，生涯欲半過。","白云心已矣，滄海意如何。","藜杖全吾道，榴花養太和。","春风騎马醉，江月釣鱼歌。","散帙看蟲蠹，开门见雀羅。","远山終日在，芳草傍人多。","吏體莊生傲，方言楚俗譌。","屈平君莫弔，腸斷洞庭波。"]', '诗', 'shi', '', NULL, '同姜濬題裴式微餘干東齋 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a26dd3e-7589-4820-bff3-8aaf2211eb22', '贈元容州', '贈元容州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["擁旌臨合浦，上印臥長沙。","海徼長無戍，湘山獨種畬。","政傳通歲貢，才惜過年華。","萬里依孤劒，千峰寄一家。","累徵期旦暮，未起戀煙霞。","避世歌芝草，休官醉菊花。","舊遊如夢裏，此別是天涯。","何事滄波上，漂漂逐海槎。"]', '["擁旌臨合浦，上印臥长沙。","海徼长無戍，湘山独種畬。","政傳通歲貢，才惜過年华。","万里依孤劒，千峰寄一家。","累徵期旦暮，未起戀煙霞。","避世歌芝草，休官醉菊花。","旧游如梦裏，此別是天涯。","何事滄波上，漂漂逐海槎。"]', '诗', 'shi', '', NULL, '贈元容州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e1771e6-2fa1-4a25-9401-08e68b560584', '夏口送長寧楊明府歸荆南因寄幕府諸公', '夏口送长寧楊明府归荆南因寄幕府諸公', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["關西楊太尉，千載德猶聞。","白日俱終老，清風獨至君。","身承遠祖遺，才出衆人羣。","舉世貪荆玉，全家戀楚雲。","向煙帆杳杳，臨水葉紛紛。","草覆昭丘綠，江從夏口分。","高名光盛府，異姓寵殊勳。","百越今無事，南征欲罷軍。"]', '["关西楊太尉，千載德猶闻。","白日俱終老，清风独至君。","身承远祖遺，才出衆人羣。","舉世貪荆玉，全家戀楚云。","向煙帆杳杳，臨水葉紛紛。","草覆昭丘綠，江從夏口分。","高名光盛府，異姓寵殊勳。","百越今無事，南征欲罷軍。"]', '诗', 'shi', '', NULL, '夏口送長寧楊明府歸荆南因寄幕府諸公 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d55a0755-ce84-4d96-8197-b445e2f84c9b', '奉和杜相公新移長興宅呈元相公', '奉和杜相公新移长兴宅呈元相公', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["間世生賢宰，同心奉至尊。","功高開北第，機靜灌中園。","入並蟬冠影，歸分騎士喧。","窗聞漢宮漏，家識杜陵源。","獻替常焚藁，優閑獨對萱。","花香逐荀令，草色對王孫。","有地先開閣，何人不掃門。","江湖難自退，明主託元元。"]', '["间世生賢宰，同心奉至尊。","功高开北第，機静灌中园。","入並蟬冠影，归分騎士喧。","窗闻漢宮漏，家識杜陵源。","獻替常焚藁，優闲独对萱。","花香逐荀令，草色对王孫。","有地先开閣，何人不掃门。","江湖难自退，明主託元元。"]', '诗', 'shi', '', NULL, '奉和杜相公新移長興宅呈元相公 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('581e5a92-6e7f-4d27-9242-221681598fb0', '湖南使還留辭辛大夫', '湖南使還留辞辛大夫', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["王師勞近甸，兵食仰諸侯。","天子無南顧，元勳在上遊。","大才生間氣，盛業拯橫流。","風景隨搖筆，山川入運籌。","羽觴交餞席，旄節對歸舟。","鶯識春深恨，猿知日去愁。","別離花寂寂，南北水悠悠。","唯有家兼國，終身共所憂。"]', '["王師勞近甸，兵食仰諸侯。","天子無南顧，元勳在上游。","大才生间氣，盛業拯橫流。","风景隨搖笔，山川入運籌。","羽觴交餞席，旄節对归舟。","鶯識春深恨，猿知日去愁。","別離花寂寂，南北水悠悠。","唯有家兼国，終身共所憂。"]', '诗', 'shi', '', NULL, '湖南使還留辭辛大夫 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3d148a1-fc57-488e-8318-1eb3a1f50c2e', '泛曲阿後湖簡同遊諸公', '泛曲阿後湖簡同游諸公', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["元氣浮積水，沈沈深不流。","春風萬頃綠，映帶至徐州。","爲客難適意，逢君方暫遊。","夤緣白蘋際，日暮滄浪舟。","渡口微月進，林西殘雨收。","水雲去仍濕，沙鶴鳴相留。","且習子陵隱，能忘生事憂。","此中深有意，非爲釣魚鉤。"]', '["元氣浮積水，沈沈深不流。","春风万頃綠，映带至徐州。","爲客难適意，逢君方暫游。","夤緣白蘋際，日暮滄浪舟。","渡口微月進，林西殘雨收。","水云去仍濕，沙鹤鳴相留。","且習子陵隐，能忘生事憂。","此中深有意，非爲釣鱼鉤。"]', '诗', 'shi', '', NULL, '泛曲阿後湖簡同遊諸公 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d40264-2d5b-4a14-b518-6beb6dc15438', '北遊酬孟雲卿見寄', '北游酬孟云卿见寄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["忽忽忘前事，事願能相乖。","衣馬日羸弊，誰辨行與才。","善道居貧賤，潔服蒙塵埃。","行行無定止，懔坎難歸來。","慈母憂疾疹，室家念棲萊。","幸君夙姻親，深見中外懷。","俟子惜時節，悵望臨高臺。"]', '["忽忽忘前事，事願能相乖。","衣马日羸弊，誰辨行與才。","善道居貧賤，潔服蒙塵埃。","行行無定止，懔坎难归来。","慈母憂疾疹，室家念棲萊。","幸君夙姻親，深见中外懷。","俟子惜时節，悵望臨高台。"]', '诗', 'shi', '', NULL, '北遊酬孟雲卿見寄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fac64e67-75fa-4d31-a82a-b3dbe87b96f0', '冬夜宿揚州開元寺烈公房送李侍御之江東', '冬夜宿揚州开元寺烈公房送李侍御之江东', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["遷客投百越，窮陰淮海凝。","中原馳困獸，萬里棲飢鷹。","寂寂連宇下，愛君心自弘。","空堂來霜氣，永夜清明燈。","發後望煙水，相思勞寢興。","暮帆背楚郭，江色浮金陵。","此去爾何恨，近名予未能。","爐峰若便道，爲訪東林僧。"]', '["遷客投百越，窮陰淮海凝。","中原驰困獸，万里棲飢鷹。","寂寂連宇下，愛君心自弘。","空堂来霜氣，永夜清明灯。","發後望煙水，相思勞寢兴。","暮帆背楚郭，江色浮金陵。","此去爾何恨，近名予未能。","爐峰若便道，爲訪东林僧。"]', '诗', 'shi', '', NULL, '冬夜宿揚州開元寺烈公房送李侍御之江東 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34e1a717-4fd7-4a11-9387-58975a95a8c8', '南楚懷古', '南楚懷古', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["南國久蕪沒，我來空鬱陶。","君看章華宮，處處生蓬蒿。","但見陵與谷，豈知賢與豪。","精魂托古木，寶劒捐江臯。","倚棹下晴景，回舟隨晚濤。","碧雲暮寥落，湖上秋天高。","往事那堪問，此心徒自勞。","獨餘湘水上，千載聞離騷。"]', '["南国久蕪沒，我来空鬱陶。","君看章华宮，处处生蓬蒿。","但见陵與谷，豈知賢與豪。","精魂托古木，寶劒捐江臯。","倚棹下晴景，回舟隨晚濤。","碧云暮寥落，湖上秋天高。","往事那堪问，此心徒自勞。","独餘湘水上，千載闻離騷。"]', '诗', 'shi', '', NULL, '南楚懷古 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9177966-be32-4fa1-a3a8-c23ae2428007', '上湖田館南樓憶朱晏', '上湖田館南楼憶朱晏', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["漂泊日復日，洞庭今更秋。","白雲如有意，萬里望孤舟。","何事愛成別，空令登此樓。","天光映波動，月影隨江流。","鶴唳靜寒渚，猿啼深夜洲。","歸期誠已促，清景仍相留。","頃者慕獨往，爾來悲遠遊。","風波自此去，桂水空離憂。"]', '["漂泊日复日，洞庭今更秋。","白云如有意，万里望孤舟。","何事愛成別，空令登此楼。","天光映波动，月影隨江流。","鹤唳静寒渚，猿啼深夜洲。","归期誠已促，清景仍相留。","頃者慕独往，爾来悲远游。","风波自此去，桂水空離憂。"]', '诗', 'shi', '', NULL, '上湖田館南樓憶朱晏 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d4b0d05-1f92-4127-9608-6aedbc76ca36', '送姚八之句容舊任便歸江南', '送姚八之句容旧任便归江南', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["故人還水國，春色動離憂。","碧草千萬里，滄江朝暮流。","桃花迷舊路，萍葉蕩歸舟。","遠戍看京口，空城問石頭。","折芳佳麗地，望月西南樓。","猨鳥共孤嶼，煙波連數州。","誰家過楚老，何處戀江鷗。","尺素能相報，湖山若箇憂。"]', '["故人還水国，春色动離憂。","碧草千万里，滄江朝暮流。","桃花迷旧路，萍葉蕩归舟。","远戍看京口，空城问石头。","折芳佳丽地，望月西南楼。","猨鸟共孤嶼，煙波連數州。","誰家過楚老，何处戀江鷗。","尺素能相報，湖山若箇憂。"]', '诗', 'shi', '', NULL, '送姚八之句容舊任便歸江南 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53d6d62c-51e2-44b1-9ed1-220166a69e32', '睢陽贈李司倉', '睢陽贈李司倉', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["白露變時候，蛬聲暮啾啾。","飄飄洛陽客，惆悵梁園秋。","只爲乏生計，爾來成遠遊。","一身不家食，萬事從人求。","且喜接餘論，足堪資小留。","寒城落日後，砧杵令人愁。","歸路歲時盡，長河朝夕流。","非君深意願，誰復能相憂。"]', '["白露变时候，蛬声暮啾啾。","飄飄洛陽客，惆悵梁园秋。","只爲乏生計，爾来成远游。","一身不家食，万事從人求。","且喜接餘論，足堪資小留。","寒城落日後，砧杵令人愁。","归路歲时尽，长河朝夕流。","非君深意願，誰复能相憂。"]', '诗', 'shi', '', NULL, '睢陽贈李司倉 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2325ad26-e0cc-4561-9fa5-727b4810b9b6', '杪秋洞庭中懷亡道士謝太虛', '杪秋洞庭中懷亡道士謝太虛', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["漂泊日復日，洞庭今更秋。","青楓亦何意，此夜催人愁。","惆悵客中月，徘徊江上樓。","心知楚天遠，目送滄波流。","羽客久已歿，微言無處求。","空餘白雲在，容與隨孤舟。","千里杳難望，一身當獨遊。","故園復何許，江海徒遲留。"]', '["漂泊日复日，洞庭今更秋。","青楓亦何意，此夜催人愁。","惆悵客中月，徘徊江上楼。","心知楚天远，目送滄波流。","羽客久已歿，微言無处求。","空餘白云在，容與隨孤舟。","千里杳难望，一身當独游。","故园复何許，江海徒遲留。"]', '诗', 'shi', '', NULL, '杪秋洞庭中懷亡道士謝太虛 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f1d811b-6040-4de8-9a10-003b056d3e0d', '同郭參謀詠崔僕射淮南節度使廳前竹', '同郭參謀詠崔僕射淮南節度使廳前竹', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["昔種梁王苑，今移漢將壇。","蒙籠低冕過，青翠捲簾看。","得地移根遠，經霜抱節難。","開花成鳳實，嫩笋長魚竿。","藹藹軍容靜，蕭蕭郡宇寬。","細音和角暮，疎影上門寒。","湘浦何年變，山陽幾處殘。","不知軒屏側，歲晚對袁安。"]', '["昔種梁王苑，今移漢將壇。","蒙籠低冕過，青翠捲簾看。","得地移根远，經霜抱節难。","开花成鳳實，嫩笋长鱼竿。","藹藹軍容静，蕭蕭郡宇寬。","細音和角暮，疎影上门寒。","湘浦何年变，山陽幾处殘。","不知軒屏側，歲晚对袁安。"]', '诗', 'shi', '', NULL, '同郭參謀詠崔僕射淮南節度使廳前竹 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ebe4220-8778-4f86-9a6d-f91e1feb0ae5', '硤石遇雨宴前主簿從兄子英宅', '硤石遇雨宴前主簿從兄子英宅', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["縣城蒼翠裏，客路兩崖開。","硤石雲漠漠，東風吹雨來。","吾兄此爲吏，薄宦知無媒。","方寸抱秦鏡，聲名傳楚材。","折腰五斗間，僶俛隨塵埃。","秩滿少餘俸，家貧仍散財。","誰言次東道，暫預傾金罍。","雖欲少留此，其如歸限催。"]', '["縣城蒼翠裏，客路兩崖开。","硤石云漠漠，东风吹雨来。","吾兄此爲吏，薄宦知無媒。","方寸抱秦镜，声名傳楚材。","折腰五斗间，僶俛隨塵埃。","秩满少餘俸，家貧仍散財。","誰言次东道，暫預傾金罍。","雖欲少留此，其如归限催。"]', '诗', 'shi', '', NULL, '硤石遇雨宴前主簿從兄子英宅 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2091c2c-9169-4ce2-a2e5-7115bde0e5c2', '江中晚釣寄荆南一二相識', '江中晚釣寄荆南一二相識', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["楚郭微雨收，荆門遙在目。","漾舟水雲裏，日暮春江綠。","霽華靜洲渚，暝色連松竹。","月出波上時，人歸渡頭宿。","一身已無累，萬事更何欲。","漁父自夷猶，白鷗不羈束。","既憐滄浪水，復愛滄浪曲。","不見眼中人，相思心斷續。"]', '["楚郭微雨收，荆门遙在目。","漾舟水云裏，日暮春江綠。","霽华静洲渚，暝色連松竹。","月出波上时，人归渡头宿。","一身已無累，万事更何欲。","漁父自夷猶，白鷗不羈束。","既怜滄浪水，复愛滄浪曲。","不见眼中人，相思心斷續。"]', '诗', 'shi', '', NULL, '江中晚釣寄荆南一二相識 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41c095de-597d-4cb0-8daf-cebb1ef9f366', '九日岳陽待黃遂張渙', '九日岳陽待黄遂張渙', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["別君頗已久，離念與時積。","楚水空浮煙，江樓望歸客。","徘徊正佇想，髣髴如暫覿。","心目徒自親，風波尚相隔。","青林泊舟處，猿鳥愁孤驛。","遙見郭外山，蒼然雨中夕。","季鷹久疎曠，叔度早疇昔。","反櫂來何遲，黃花候君摘。"]', '["別君頗已久，離念與时積。","楚水空浮煙，江楼望归客。","徘徊正佇想，髣髴如暫覿。","心目徒自親，风波尚相隔。","青林泊舟处，猿鸟愁孤驛。","遙见郭外山，蒼然雨中夕。","季鷹久疎曠，叔度早疇昔。","反櫂来何遲，黄花候君摘。"]', '诗', 'shi', '', NULL, '九日岳陽待黃遂張渙 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82499be7-6c67-4df7-9a88-67841e562923', '題王少府堯山隱處簡陸鄱陽', '題王少府堯山隐处簡陸鄱陽', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["故人滄洲吏，深與世情薄。","解印二十年，委身在丘壑。","買田楚山下，妻子自耕鑿。","羣動心有營，孤雲本無著。","因收谿上釣，遂接林中酌。","對酒春日長，山村杏花落。","陸生鄱陽令，獨步建溪作。","早晚休此官，隨君永棲託。"]', '["故人滄洲吏，深與世情薄。","解印二十年，委身在丘壑。","買田楚山下，妻子自耕鑿。","羣动心有營，孤云本無著。","因收谿上釣，遂接林中酌。","对酒春日长，山村杏花落。","陸生鄱陽令，独步建溪作。","早晚休此官，隨君永棲託。"]', '诗', 'shi', '', NULL, '題王少府堯山隱處簡陸鄱陽 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff91b9df-5052-4dd5-866d-7347e1b1dc25', '晚次湖口有懷', '晚次湖口有懷', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["靄然空水合，目極平江暮。","南望天無涯，孤帆落何處。","頃爲衡湘客，頗見湖山趣。","朝氣和楚雲，夕陽映江樹。","帝鄉勞想望，萬里心來去。","白髮生扁舟，滄波滿歸路。","秋風今已至，日夜雁南度。","木葉辭洞庭，紛紛落無數。"]', '["靄然空水合，目極平江暮。","南望天無涯，孤帆落何处。","頃爲衡湘客，頗见湖山趣。","朝氣和楚云，夕陽映江樹。","帝乡勞想望，万里心来去。","白髮生扁舟，滄波满归路。","秋风今已至，日夜雁南度。","木葉辞洞庭，紛紛落無數。"]', '诗', 'shi', '', NULL, '晚次湖口有懷 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c0ed9d1-f147-4faa-af0e-a226dbf5d25d', '陪元侍御遊支硎山寺', '陪元侍御游支硎山寺', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["支公去已久，寂寞龍華會。","古木閉空山，蒼然暮相對。","林巒非一狀，水石有餘態。","密竹藏晦明，羣峰爭向背。","峰峰帶落日，步步入青靄。","香氣空翠中，猿聲暮雲外。","留連南臺客，想像西方內。","因逐溪水還，觀心兩無礙。"]', '["支公去已久，寂寞龙华會。","古木閉空山，蒼然暮相对。","林巒非一狀，水石有餘態。","密竹藏晦明，羣峰爭向背。","峰峰带落日，步步入青靄。","香氣空翠中，猿声暮云外。","留連南台客，想像西方內。","因逐溪水還，观心兩無礙。"]', '诗', 'shi', '', NULL, '陪元侍御遊支硎山寺 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64352fb2-31b1-424e-ad57-d1314e0f5b65', '桂陽西州晚泊古橋村住人', '桂陽西州晚泊古橋村住人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["洛陽別離久，江上心可得。","惆悵增暮情，瀟湘復秋色。","故山隔何處，落日羨歸翼。","滄海空自流，白鷗不相識。","悲蛬滿荆渚，輟櫂徒沾臆。","行客念寒衣，主人愁夜織。","帝鄉片雲去，遙寄千里憶。","南路隨天長，征帆杳無極。"]', '["洛陽別離久，江上心可得。","惆悵增暮情，瀟湘复秋色。","故山隔何处，落日羨归翼。","滄海空自流，白鷗不相識。","悲蛬满荆渚，輟櫂徒沾臆。","行客念寒衣，主人愁夜织。","帝乡片云去，遙寄千里憶。","南路隨天长，征帆杳無極。"]', '诗', 'shi', '', NULL, '桂陽西州晚泊古橋村住人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d272f191-11c7-4df6-8cfd-2836b2bac9af', '夕次檐石湖夢洛陽親故', '夕次檐石湖梦洛陽親故', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["天涯望不盡，日暮愁獨去。","萬里雲海空，孤帆向何處。","寄身煙波裏，頗得湖山趣。","江氣和楚雲，秋聲亂楓樹。","如何異鄉縣，日復懷親故。","遙與洛陽人，相逢夢中路。","不堪明月裏，更值清秋暮。","倚棹對滄波，歸心共誰語。"]', '["天涯望不尽，日暮愁独去。","万里云海空，孤帆向何处。","寄身煙波裏，頗得湖山趣。","江氣和楚云，秋声亂楓樹。","如何異乡縣，日复懷親故。","遙與洛陽人，相逢梦中路。","不堪明月裏，更值清秋暮。","倚棹对滄波，归心共誰語。"]', '诗', 'shi', '', NULL, '夕次檐石湖夢洛陽親故 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0564dcc9-d5cc-4be0-a392-23d05ff966db', '按覆後歸睦州贈苗侍御', '按覆後归睦州贈苗侍御', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["地遠心難達，天高謗易成。","羊腸留覆轍，虎口脫餘生。","直氏偷金枉，于家決獄明。","一言知己重，片議殺身輕。","日下人誰憶，天涯客獨行。","年光銷蹇步，秋氣入衰情。","建德知何在，長江問去程。","孤舟百口渡，萬里一猿聲。","落日開鄉路，空山向郡城。","豈令冤氣積，千古在長平。"]', '["地远心难達，天高謗易成。","羊腸留覆轍，虎口脫餘生。","直氏偷金枉，于家決獄明。","一言知己重，片議殺身轻。","日下人誰憶，天涯客独行。","年光銷蹇步，秋氣入衰情。","建德知何在，长江问去程。","孤舟百口渡，万里一猿声。","落日开乡路，空山向郡城。","豈令冤氣積，千古在长平。"]', '诗', 'shi', '', NULL, '按覆後歸睦州贈苗侍御 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4d9d6ad-f1c1-465c-b962-97dd9d5c12a2', '奉寄婺州李使君舍人', '奉寄婺州李使君舍人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["建隼罷鳴珂，初傳來暮歌。","漁樵識太古，草樹得陽和。","東道諸生從，南依遠客過。","天清婺女出，土厚絳人多。","永日空相望，流年復幾何。","崖開當夕照，葉去逐寒波。","眼暗經難受，身閑劒懶磨。","似鴞占賈誼，上馬試廉頗。","窮分安藜藿，衰容勝薜蘿。","只應隨越鳥，南翥託高柯。"]', '["建隼罷鳴珂，初傳来暮歌。","漁樵識太古，草樹得陽和。","东道諸生從，南依远客過。","天清婺女出，土厚絳人多。","永日空相望，流年复幾何。","崖开當夕照，葉去逐寒波。","眼暗經难受，身闲劒懶磨。","似鴞占賈誼，上马試廉頗。","窮分安藜藿，衰容勝薜蘿。","只應隨越鸟，南翥託高柯。"]', '诗', 'shi', '', NULL, '奉寄婺州李使君舍人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea7c9ab6-c8a8-44d4-885e-43794ae25c84', '哭魏兼遂', '哭魏兼遂', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["古今俱此去，脩短竟誰分。","樽酒空如在，絃琴肯重聞。","一門同逝水，萬事共浮雲。","舊館何人宅，空山遠客墳。","艱危貧且共，少小秀而文。","獨行依窮巷，全身出亂軍。","歲時長寂寞，煙月自氛氳。","壠樹隨人古，山門對日曛。","汎舟悲向子，留劒贈徐君。","來去雲陽路，傷心江水濆。"]', '["古今俱此去，脩短竟誰分。","樽酒空如在，絃琴肯重闻。","一门同逝水，万事共浮云。","旧館何人宅，空山远客墳。","艱危貧且共，少小秀而文。","独行依窮巷，全身出亂軍。","歲时长寂寞，煙月自氛氳。","壠樹隨人古，山门对日曛。","汎舟悲向子，留劒贈徐君。","来去云陽路，傷心江水濆。"]', '诗', 'shi', '', NULL, '哭魏兼遂 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad81d121-40b2-4357-9bfa-f9ef47011a8b', '負謫後登干越亭作', '負謫後登干越亭作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["天南愁望絕，亭上柳條新。","落日獨歸鳥，孤舟何處人。","生涯投越徼，世業陷胡塵。","杳杳鍾陵暮，悠悠鄱水春。","秦臺悲白首，楚澤怨青蘋。","草色迷征路，鶯聲傷逐臣。","獨醒空取笑，直道不容身。","得罪風霜苦，全生天地仁。","青山數行淚，滄海一窮鱗。","牢落機心盡，惟憐鷗鳥親。"]', '["天南愁望絕，亭上柳條新。","落日独归鸟，孤舟何处人。","生涯投越徼，世業陷胡塵。","杳杳鍾陵暮，悠悠鄱水春。","秦台悲白首，楚澤怨青蘋。","草色迷征路，鶯声傷逐臣。","独醒空取笑，直道不容身。","得罪风霜苦，全生天地仁。","青山數行泪，滄海一窮鱗。","牢落機心尽，惟怜鷗鸟親。"]', '诗', 'shi', '', NULL, '負謫後登干越亭作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b49d8c48-7218-4967-a374-99f2d5d14c4a', '留題李明府霅溪水堂', '留題李明府霅溪水堂', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["寥寥此堂上，幽意復誰論。","落日無王事，青山在縣門。","雲峰向高枕，漁釣入前軒。","晚竹疎簾影，春苔雙履痕。","荷香隨坐臥，湖色映晨昏。","虛牖閑生白，鳴琴靜對言。","暮禽飛上下，春水帶清渾。","遠岸誰家柳，孤煙何處村。","謫居投瘴癘，離思過湘沅。","從此扁舟去，誰堪江浦猿。"]', '["寥寥此堂上，幽意复誰論。","落日無王事，青山在縣门。","云峰向高枕，漁釣入前軒。","晚竹疎簾影，春苔雙履痕。","荷香隨坐臥，湖色映晨昏。","虛牖闲生白，鳴琴静对言。","暮禽飞上下，春水带清渾。","远岸誰家柳，孤煙何处村。","謫居投瘴癘，離思過湘沅。","從此扁舟去，誰堪江浦猿。"]', '诗', 'shi', '', NULL, '留題李明府霅溪水堂 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ee445ea-eb05-4596-a1b8-8696b375c996', '入白沙渚夤緣二十五里至石窟山下懷天台陸山人', '入白沙渚夤緣二十五里至石窟山下懷天台陸山人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["遠嶼靄將夕，玩幽行自遲。","歸人不計日，流水閑相隨。","輟棹古崖口，捫蘿春景遲。","偶因回舟次，寧與前山期。","對此瑤草色，懷君瓊樹枝。","浮雲去寂寞，白鳥相因依。","何事愛高隱，但令勞遠思。","窮年臥海嶠，永望愁天涯。","吾亦從此去，扁舟何所之？","迢迢江上帆，千里東風吹。"]', '["远嶼靄將夕，玩幽行自遲。","归人不計日，流水闲相隨。","輟棹古崖口，捫蘿春景遲。","偶因回舟次，寧與前山期。","对此瑤草色，懷君瓊樹枝。","浮云去寂寞，白鸟相因依。","何事愛高隐，但令勞远思。","窮年臥海嶠，永望愁天涯。","吾亦從此去，扁舟何所之？","迢迢江上帆，千里东风吹。"]', '诗', 'shi', '', NULL, '入白沙渚夤緣二十五里至石窟山下懷天台陸山人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ff9ef45-3d60-4c80-93a5-7e864d21ef46', '禪智寺上方懷演和尚寺即和尚所創', '禪智寺上方懷演和尚寺即和尚所創', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["絕巘東林寺，高僧惠遠公。","買園隋苑下，持鉢楚城中。","斗極千燈近，煙波萬井通。","遠山低月殿，寒木露花宮。","紺宇焚香淨，滄州擺霧空。","鴈來秋色裏，曙起早潮東。","飛錫今何在？蒼生待發蒙。","白雲翻送客，庭樹自辭風。","捨筏追開士，迴舟狎釣翁。","平生江海意，惟共白鷗同。"]', '["絕巘东林寺，高僧惠远公。","買园隋苑下，持鉢楚城中。","斗極千灯近，煙波万井通。","远山低月殿，寒木露花宮。","紺宇焚香淨，滄州擺霧空。","鴈来秋色裏，曙起早潮东。","飞錫今何在？蒼生待發蒙。","白云翻送客，庭樹自辞风。","捨筏追开士，迴舟狎釣翁。","平生江海意，惟共白鷗同。"]', '诗', 'shi', '', NULL, '禪智寺上方懷演和尚寺即和尚所創 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a8e3904-a09e-44fc-aa52-bda8fba8172a', '賈侍郎自會稽使迴篇什盈卷兼蒙見寄一首與余有挂冠之期因書數事率成十韻', '賈侍郎自會稽使迴篇什盈卷兼蒙见寄一首與余有挂冠之期因书數事率成十韻', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["江上逢星使，南來自會稽。","驚年一葉落，按俗五花嘶。","上國悲蕪梗，中原動鼓鼙。","報恩看鐵劒，銜命出金閨。","風物催歸緒，雲峰發詠題。","天長百越外，潮上小江西。","鳥道通閩嶺，山光落剡溪。","暮帆千里思，秋夜一猨啼。","柏樹榮新壠，桃源憶故蹊。","若能爲休去，行復草萋萋。"]', '["江上逢星使，南来自會稽。","驚年一葉落，按俗五花嘶。","上国悲蕪梗，中原动鼓鼙。","報恩看鐵劒，銜命出金閨。","风物催归緒，云峰發詠題。","天长百越外，潮上小江西。","鸟道通閩嶺，山光落剡溪。","暮帆千里思，秋夜一猨啼。","柏樹榮新壠，桃源憶故蹊。","若能爲休去，行复草萋萋。"]', '诗', 'shi', '', NULL, '賈侍郎自會稽使迴篇什盈卷兼蒙見寄一首與余有挂冠之期因書數事率成十韻 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('412c2a12-0b17-4b10-95f1-0bfb7501177c', '秋日夏口涉漢陽獻李相公', '秋日夏口涉漢陽獻李相公', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["日望衡門處，心知漢水濆。","偶乘青雀舫，還在白鷗羣。","間氣生靈秀，先朝翼戴勳。","藏弓身已退，焚藳事難聞。","舊業成青草，全家寄白雲。","松蘿長稚子，風景逐新文。","山帶寒城出，江依古岸分。","楚歌悲遠客，羌笛怨孤軍。","鼎罷調梅久，門看種藥勤。","十年猶去國，黃葉又紛紛。"]', '["日望衡门处，心知漢水濆。","偶乘青雀舫，還在白鷗羣。","间氣生靈秀，先朝翼戴勳。","藏弓身已退，焚藳事难闻。","旧業成青草，全家寄白云。","松蘿长稚子，风景逐新文。","山带寒城出，江依古岸分。","楚歌悲远客，羌笛怨孤軍。","鼎罷調梅久，门看種藥勤。","十年猶去国，黄葉又紛紛。"]', '诗', 'shi', '', NULL, '秋日夏口涉漢陽獻李相公 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6e4e09-99ef-47c8-8152-f6f7d45a911b', '歸沛縣道中晚泊留侯城', '归沛縣道中晚泊留侯城', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["訪古此城下，子房安在哉？","白雲去不反，危堞空崔嵬。","伊昔楚漢時，頗聞經濟才。","運籌風塵下，能使天地開。","蔓草日已積，長松日已摧。","功名滿青史，祠廟唯蒼苔。","百里暮程遠，孤舟川上迴。","進帆東風便，轉岸前山來。","楚水澹相引，沙鷗閑不猜。","扣舷從此去，延首仍裴回。"]', '["訪古此城下，子房安在哉？","白云去不反，危堞空崔嵬。","伊昔楚漢时，頗闻經濟才。","運籌风塵下，能使天地开。","蔓草日已積，长松日已摧。","功名满青史，祠廟唯蒼苔。","百里暮程远，孤舟川上迴。","進帆东风便，轉岸前山来。","楚水澹相引，沙鷗闲不猜。","扣舷從此去，延首仍裴回。"]', '诗', 'shi', '', NULL, '歸沛縣道中晚泊留侯城 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efecfa49-79d0-4bcf-86f1-a8d92dce1490', '關門望華山', '关门望华山', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["客路瞻太華，三峰高際天。","夏雲亙百里，合沓遙相連。","雷雨飛半腹，太陽在其巔。","翠微關上近，瀑布林梢懸。","愛此衆容秀，能令西望偏。","徘徊忘暝色，泱漭成陰煙。","會是朝百靈，亦聞會羣仙。","瓊漿豈易挹，毛女非空傳。","髣髴仍佇想，幽期如眼前。","金天有青廟，松柏隱蒼然。"]', '["客路瞻太华，三峰高際天。","夏云亙百里，合沓遙相連。","雷雨飞半腹，太陽在其巔。","翠微关上近，瀑布林梢懸。","愛此衆容秀，能令西望偏。","徘徊忘暝色，泱漭成陰煙。","會是朝百靈，亦闻會羣仙。","瓊漿豈易挹，毛女非空傳。","髣髴仍佇想，幽期如眼前。","金天有青廟，松柏隐蒼然。"]', '诗', 'shi', '', NULL, '關門望華山 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ebc42f-71a1-42be-b0c8-af50686a15a2', '奉陪蕭使君入鮑達洞尋靈山寺', '奉陪蕭使君入鲍達洞尋靈山寺', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["山居秋更鮮，秋江相映碧。","獨臨滄洲路，如待挂帆客。","遂使康樂侯，披榛著雙屐。","入雲開嶺道，永日尋泉脈。","古寺隱青冥，空中寒磬夕。","蒼苔絕行徑，飛鳥無去跡。","樹杪下歸人，水聲過幽石。","任情趣逾遠，移步奇屢易。","蘿木靜蒙蒙，風煙深寂寂。","徘徊未能去，畏共桃源隔。"]', '["山居秋更鲜，秋江相映碧。","独臨滄洲路，如待挂帆客。","遂使康乐侯，披榛著雙屐。","入云开嶺道，永日尋泉脈。","古寺隐青冥，空中寒磬夕。","蒼苔絕行徑，飞鸟無去跡。","樹杪下归人，水声過幽石。","任情趣逾远，移步奇屢易。","蘿木静蒙蒙，风煙深寂寂。","徘徊未能去，畏共桃源隔。"]', '诗', 'shi', '', NULL, '奉陪蕭使君入鮑達洞尋靈山寺 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f98875c-1e9e-4396-92a1-58c6b3e64934', '孫權故城下懷古兼送友人歸建業', '孫權故城下懷古兼送友人归建業', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["雄圖爭割據，神器終不守。","上下武昌城，長江竟何有。","古來壯臺榭，事往悲陵阜。","寥落幾家人，猶依數株柳。","威靈絕想像，蕪沒空林藪。","野徑春草中，郊扉夕陽後。","逢君從此去，背楚方東走。","煙際指金陵，潮時過湓口。","行人已何在，臨水徒揮手。","惆悵不能歸，孤帆沒雲久。"]', '["雄圖爭割據，神器終不守。","上下武昌城，长江竟何有。","古来壯台榭，事往悲陵阜。","寥落幾家人，猶依數株柳。","威靈絕想像，蕪沒空林藪。","野徑春草中，郊扉夕陽後。","逢君從此去，背楚方东走。","煙際指金陵，潮时過湓口。","行人已何在，臨水徒揮手。","惆悵不能归，孤帆沒云久。"]', '诗', 'shi', '', NULL, '孫權故城下懷古兼送友人歸建業 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d3ef9c7-dd5a-4a5b-ad56-0f0b5d60e40f', '宿雙峰寺寄盧七李十六', '宿雙峰寺寄盧七李十六', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["寥寥禪誦處，滿室蟲絲結。","獨與山中人，無心生復滅。","徘徊雙峰下，惆悵雙峰月。","杳杳暮猿深，蒼蒼古松列。","玩奇不可盡，漸遠更幽絕。","林暗僧獨歸，石寒泉且咽。","竹房響輕吹，蘿徑陰餘雪。","臥澗曉何遲，背巖春未發。","此遊誠多趣，獨往共誰閱。","得意空自歸，非君豈能說。"]', '["寥寥禪誦处，满室蟲絲結。","独與山中人，無心生复滅。","徘徊雙峰下，惆悵雙峰月。","杳杳暮猿深，蒼蒼古松列。","玩奇不可尽，漸远更幽絕。","林暗僧独归，石寒泉且咽。","竹房响轻吹，蘿徑陰餘雪。","臥澗晓何遲，背巖春未發。","此游誠多趣，独往共誰閱。","得意空自归，非君豈能说。"]', '诗', 'shi', '', NULL, '宿雙峰寺寄盧七李十六 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f2bade-8824-489a-a192-903f116c2b53', '京口懷洛陽舊居兼寄廣陵二三知己', '京口懷洛陽旧居兼寄廣陵二三知己', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["川闊悲無梁，藹然滄波夕。","天涯一飛鳥，日暮南徐客。","氣混京口雲，潮吞海門石。","孤帆候風進，夜色帶江白。","一水阻佳期，相望空脉脉。","那堪歲芳盡，更使春夢積。","故國胡塵飛，遠山楚雲隔。","家人想何在，庭草爲誰碧。","惆悵空傷情，滄浪有餘跡。","嚴陵七里灘，攜手同所適。"]', '["川闊悲無梁，藹然滄波夕。","天涯一飞鸟，日暮南徐客。","氣混京口云，潮吞海门石。","孤帆候风進，夜色带江白。","一水阻佳期，相望空脉脉。","那堪歲芳尽，更使春梦積。","故国胡塵飞，远山楚云隔。","家人想何在，庭草爲誰碧。","惆悵空傷情，滄浪有餘跡。","嚴陵七里灘，携手同所適。"]', '诗', 'shi', '', NULL, '京口懷洛陽舊居兼寄廣陵二三知己 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cbf14a2-39a2-4a43-bb6e-a5b09792363f', '登揚州栖靈寺塔', '登揚州栖靈寺塔', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["北塔凌空虛，雄觀壓川澤。","亭亭楚雲外，千里看不隔。","遙對黃金臺，浮輝亂相射。","盤梯接元氣，半壁棲夜魄。","稍登諸劫盡，若騁排霄翮。","向是滄洲人，已爲青雲客。","雨飛千栱霽，日在萬家夕。","鳥處高却低，天涯遠如迫。","江流入空翠，海嶠現微碧。","向暮期下來，誰堪復行役。"]', '["北塔凌空虛，雄观壓川澤。","亭亭楚云外，千里看不隔。","遙对黄金台，浮輝亂相射。","盤梯接元氣，半壁棲夜魄。","稍登諸劫尽，若騁排霄翮。","向是滄洲人，已爲青云客。","雨飞千栱霽，日在万家夕。","鸟处高却低，天涯远如迫。","江流入空翠，海嶠現微碧。","向暮期下来，誰堪复行役。"]', '诗', 'shi', '', NULL, '登揚州栖靈寺塔 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f4d926-2206-4134-a047-88ffedc5e6c2', '湖上遇鄭田', '湖上遇鄭田', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["故人青雲器，何意常窘迫。","三十猶布衣，憐君頭已白。","誰言此相見，暫得話疇昔。","舊業今已蕪，還鄉返爲客。","扁舟伊獨往，斗酒君自適。","滄洲不可涯，孤帆去無跡。","杯中忽復醉，湖上生月魄。","湛湛江色寒，濛濛水雲夕。","風波易迢遰，千里如咫尺。","回首人已遙，南看楚天隔。"]', '["故人青云器，何意常窘迫。","三十猶布衣，怜君头已白。","誰言此相见，暫得話疇昔。","旧業今已蕪，還乡返爲客。","扁舟伊独往，斗酒君自適。","滄洲不可涯，孤帆去無跡。","杯中忽复醉，湖上生月魄。","湛湛江色寒，濛濛水云夕。","风波易迢遰，千里如咫尺。","回首人已遙，南看楚天隔。"]', '诗', 'shi', '', NULL, '湖上遇鄭田 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c74f1d8-75e5-450e-84a2-99ec64b2a36e', '雨中登沛縣樓贈表兄郭少府', '雨中登沛縣楼贈表兄郭少府', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["楚澤秋更遠，雲雷有時作。","晚陂帶殘雨，白水昏漠漠。","佇立收煙氛，洗然靜寥廓。","卷簾高樓上，萬里看日落。","爲客頻改弦，辭家尚如昨。","故山今不見，此鳥那可託。","小邑務常閑，吾兄宦何薄。","高標青雲器，獨立滄江鶴。","惠愛原上情，慇懃丘中諾。","何當遂良願，歸臥青山郭。"]', '["楚澤秋更远，云雷有时作。","晚陂带殘雨，白水昏漠漠。","佇立收煙氛，洗然静寥廓。","卷簾高楼上，万里看日落。","爲客頻改弦，辞家尚如昨。","故山今不见，此鸟那可託。","小邑務常闲，吾兄宦何薄。","高標青云器，独立滄江鹤。","惠愛原上情，慇懃丘中諾。","何當遂良願，归臥青山郭。"]', '诗', 'shi', '', NULL, '雨中登沛縣樓贈表兄郭少府 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f68a9dc-0b04-4dd7-abe2-0036a2bc2a46', '灞東晚晴簡同行薛棄朱訓', '灞东晚晴簡同行薛棄朱訓', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["客心豁初霽，霽色暝玄灞。","西向看夕陽，曈曈映桑柘。","二賢誠逸足，千里陪征駕。","古樹枳道傍，人煙杜陵下。","伊余在羈束，且復隨造化。","好道當有心，營生苦無暇。","高賢幸茲偶，英達窮王霸。","迢遰客王程，裴回主人夜。","一薫知異質，片玉誰齊價。","同結丘中緣，塵埃自茲謝。"]', '["客心豁初霽，霽色暝玄灞。","西向看夕陽，曈曈映桑柘。","二賢誠逸足，千里陪征駕。","古樹枳道傍，人煙杜陵下。","伊余在羈束，且复隨造化。","好道當有心，營生苦無暇。","高賢幸茲偶，英達窮王霸。","迢遰客王程，裴回主人夜。","一薫知異質，片玉誰齊價。","同結丘中緣，塵埃自茲謝。"]', '诗', 'shi', '', NULL, '灞東晚晴簡同行薛棄朱訓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56119c41-80da-44ba-9f29-d65c54bcf8fc', '對雨贈濟陰馬少府考城蔣少府兼獻成武五兄南華二兄', '对雨贈濟陰马少府考城蔣少府兼獻成武五兄南华二兄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["繁雲兼家思，彌望連濟北。","日暮微雨中，州城帶秋色。","蕭條主人靜，落葉飛不息。","鄉夢寒更頻，蟲聲夜相逼。","二賢縱橫器，久滯徒勞職。","笑語和風騷，雍容事文墨。","吾兄即時彥，前路良未測。","秋水百丈清，寒松一枝直。","此心欲引託，誰爲生羽翼。","且復頓歸鞍，杯中雪胸臆。"]', '["繁云兼家思，彌望連濟北。","日暮微雨中，州城带秋色。","蕭條主人静，落葉飞不息。","乡梦寒更頻，蟲声夜相逼。","二賢縱橫器，久滯徒勞職。","笑語和风騷，雍容事文墨。","吾兄即时彥，前路良未測。","秋水百丈清，寒松一枝直。","此心欲引託，誰爲生羽翼。","且复頓归鞍，杯中雪胸臆。"]', '诗', 'shi', '', NULL, '對雨贈濟陰馬少府考城蔣少府兼獻成武五兄南華二兄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9edd5fa0-5202-4d49-9947-bd02db86134f', '李侍御河北使回至東京相訪', '李侍御河北使回至东京相訪', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["故人南臺秀，夙擅中朝美。","擁傳從北來，飛霜日千里。","貧居幸相訪，顧我柴門裏。","却訝繡衣人，仍交布衣士。","王程遽爾迫，別戀從此始。","濁酒未暇斟，清文頗垂示。","回瞻驄馬速，但見行塵起。","日暮汀洲寒，春風渡流水。","草色官道邊，桃花御溝裏。","天涯一鳥夕，惆悵知何已。"]', '["故人南台秀，夙擅中朝美。","擁傳從北来，飞霜日千里。","貧居幸相訪，顧我柴门裏。","却訝繡衣人，仍交布衣士。","王程遽爾迫，別戀從此始。","濁酒未暇斟，清文頗垂示。","回瞻驄马速，但见行塵起。","日暮汀洲寒，春风渡流水。","草色官道邊，桃花御溝裏。","天涯一鸟夕，惆悵知何已。"]', '诗', 'shi', '', NULL, '李侍御河北使回至東京相訪 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eda78000-f257-4563-ad06-5a6995adcac0', '吳中聞潼關失守因奉寄淮南蕭判官', '吳中闻潼关失守因奉寄淮南蕭判官', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["一鴈飛吳天，羈人傷暮律。","松江風嫋嫋，波上片帆疾。","木落姑蘇臺，霜收洞庭橘。","蕭條長洲外，唯見寒山出。","胡馬嘶秦雲，漢兵亂相失。","關中因竊據，天下共憂慄。","南楚有瓊枝，相思怨瑤瑟。","一身寄滄洲，萬里看白日。","赴敵甘負戈，論兵勇投筆。","臨風但攘臂，擇木將委質。","不如歸遠山，雲臥飯松栗。"]', '["一鴈飞吳天，羈人傷暮律。","松江风嫋嫋，波上片帆疾。","木落姑蘇台，霜收洞庭橘。","蕭條长洲外，唯见寒山出。","胡马嘶秦云，漢兵亂相失。","关中因竊據，天下共憂慄。","南楚有瓊枝，相思怨瑤瑟。","一身寄滄洲，万里看白日。","赴敵甘負戈，論兵勇投笔。","臨风但攘臂，擇木將委質。","不如归远山，云臥飯松栗。"]', '诗', 'shi', '', NULL, '吳中聞潼關失守因奉寄淮南蕭判官 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45fa39a7-d427-4f98-b029-ede01808adfa', '哭張員外繼', '哭張員外繼', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["慟哭鍾陵下，東流與別離。","二星來不返，雙劒沒相隨。","獨繼先賢傳，誰刊有道碑。","故園荒峴曲，旅櫬寄天涯。","白簡曾連拜，滄洲每共思。","撫孤憐齒穉，歎逝顧身衰。","泉壤成終古，雲山若在時。","秋風鄰笛發，寒日寢門悲。","世難愁歸路，家貧緩葬期。","舊賓傷未散，夕臨咽常遲。","自此辭張邵，何由見戴逵。","獨聞山吏部，流涕訪孤兒。"]', '["慟哭鍾陵下，东流與別離。","二星来不返，雙劒沒相隨。","独繼先賢傳，誰刊有道碑。","故园荒峴曲，旅櫬寄天涯。","白簡曾連拜，滄洲每共思。","撫孤怜齒穉，歎逝顧身衰。","泉壤成終古，云山若在时。","秋风鄰笛發，寒日寢门悲。","世难愁归路，家貧緩葬期。","旧賓傷未散，夕臨咽常遲。","自此辞張邵，何由见戴逵。","独闻山吏部，流涕訪孤兒。"]', '诗', 'shi', '', NULL, '哭張員外繼 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05c095ff-2f98-48d0-bc8f-af88d637dcbe', '登東海龍興寺高頂望海簡演公', '登东海龙兴寺高頂望海簡演公', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["朐山壓海口，永望開禪宮。","元氣遠相合，太陽生其中。","豁然萬里餘，獨爲百川雄。","白波走雷電，黑霧藏魚龍。","變化非一狀，晴明分衆容。","煙開秦帝橋，隱隱橫殘虹。","蓬島如在眼，羽人那可逢。","偶聞真僧言，甚與靜者同。","幽意頗相愜，賞心殊未窮。","花間午時梵，雲外春山鐘。","誰念遽成別，自憐歸所從。","他時相憶處，惆悵西南峯。"]', '["朐山壓海口，永望开禪宮。","元氣远相合，太陽生其中。","豁然万里餘，独爲百川雄。","白波走雷電，黑霧藏鱼龙。","变化非一狀，晴明分衆容。","煙开秦帝橋，隐隐橫殘虹。","蓬島如在眼，羽人那可逢。","偶闻真僧言，甚與静者同。","幽意頗相愜，賞心殊未窮。","花间午时梵，云外春山鐘。","誰念遽成別，自怜归所從。","他时相憶处，惆悵西南峯。"]', '诗', 'shi', '', NULL, '登東海龍興寺高頂望海簡演公 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6569f7e8-47e8-4fc4-9bcd-c394f68df336', '奉送從兄罷官之淮南', '奉送從兄罷官之淮南', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["何事浮溟渤，元戎棄鏌鎁。","漁竿吾道在，鷗鳥世情賒。","玄髮他鄉換，滄洲此路遐。","泝沿隨桂檝，醒醉任松華。","離別誰堪道，艱危更可嗟。","兵鋒搖海內，王命隔天涯。","鐘漏移長樂，衣冠接永嘉。","還當拂氛祲，那復臥雲霞。","溪路漫岡轉，夕陽歸鳥斜。","萬艘江縣郭，一樹海人家。","揮袂看朱紱，揚帆指白沙。","春風獨迴首，愁思極如麻。"]', '["何事浮溟渤，元戎棄鏌鎁。","漁竿吾道在，鷗鸟世情賒。","玄髮他乡換，滄洲此路遐。","泝沿隨桂檝，醒醉任松华。","離別誰堪道，艱危更可嗟。","兵鋒搖海內，王命隔天涯。","鐘漏移长乐，衣冠接永嘉。","還當拂氛祲，那复臥云霞。","溪路漫岡轉，夕陽归鸟斜。","万艘江縣郭，一樹海人家。","揮袂看朱紱，揚帆指白沙。","春风独迴首，愁思極如麻。"]', '诗', 'shi', '', NULL, '奉送從兄罷官之淮南 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a37270-db40-4693-aba6-8c85bb858af0', '落第贈楊侍御兼拜員外仍充安大夫判官赴范陽', '落第贈楊侍御兼拜員外仍充安大夫判官赴范陽', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["職副旌旄重，才兼識量通。","使車遙肅物，邊策遠和戎。","擲地金聲著，從軍寶劒雄。","官成稽古力，名達濟時功。","肅穆烏臺上，雍容粉署中。","含香初待漏，持簡舊生風。","黠吏偏驚隼，貪夫輒避驄。","且知榮已隔，誰謂道仍同。","念舊追連茹，謀生任轉蓬。","泣連三獻玉，瘡懼再傷弓。","戀土函關外，瞻塵灞水東。","他時書一札，猶冀問途窮。"]', '["職副旌旄重，才兼識量通。","使车遙肅物，邊策远和戎。","擲地金声著，從軍寶劒雄。","官成稽古力，名達濟时功。","肅穆烏台上，雍容粉署中。","含香初待漏，持簡旧生风。","黠吏偏驚隼，貪夫輒避驄。","且知榮已隔，誰謂道仍同。","念旧追連茹，謀生任轉蓬。","泣連三獻玉，瘡懼再傷弓。","戀土函关外，瞻塵灞水东。","他时书一札，猶冀问途窮。"]', '诗', 'shi', '', NULL, '落第贈楊侍御兼拜員外仍充安大夫判官赴范陽 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e40146d6-0947-4ab5-b02a-ad2e922ad560', '初貶南巴至鄱陽題李嘉祐江亭', '初貶南巴至鄱陽題李嘉祐江亭', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["巴嶠南行遠，長江萬里隨。","不才甘謫去，流水亦何之。","地遠明君棄，天高酷吏欺。","清山獨往路，芳草未歸時。","流落還相見，悲懽話所思。","猜嫌傷薏苡，愁暮向江籬。","柳色迎高塢，荷衣照下帷。","水雲初起重，暮鳥遠來遲。","白首看長劒，滄洲寄釣絲。","沙鷗驚小吏，湖月上高枝。","稚子能吳語，新文怨楚辭。","憐君不得意，川谷自逶迤。"]', '["巴嶠南行远，长江万里隨。","不才甘謫去，流水亦何之。","地远明君棄，天高酷吏欺。","清山独往路，芳草未归时。","流落還相见，悲懽話所思。","猜嫌傷薏苡，愁暮向江籬。","柳色迎高塢，荷衣照下帷。","水云初起重，暮鸟远来遲。","白首看长劒，滄洲寄釣絲。","沙鷗驚小吏，湖月上高枝。","稚子能吳語，新文怨楚辞。","怜君不得意，川谷自逶迤。"]', '诗', 'shi', '', NULL, '初貶南巴至鄱陽題李嘉祐江亭 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40843ec1-56da-4363-8f1c-c6d294b1ab0a', '初貶南巴至鄱陽題李嘉祐江亭', '初貶南巴至鄱陽題李嘉祐江亭', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["南出巴人徼，長江萬里隨。","不才甘謫去，流水亦何之。","地逺明君棄，天髙酷吏欺。","青山獨往路，芳草未歸時。","流落還相見，悲歡話所思。","猜讒傷薏苡，愁暮向江蘺。","淚盡㸔長劔，心閑寄釣𢇁。","水雲初起重，暮鳥逺來遲。","稚子能吳語，新文怨楚詞。","憐君不得意，客鬢老南枝。"]', '["南出巴人徼，长江万里隨。","不才甘謫去，流水亦何之。","地逺明君棄，天髙酷吏欺。","青山独往路，芳草未归时。","流落還相见，悲歡話所思。","猜讒傷薏苡，愁暮向江蘺。","泪尽㸔长劔，心闲寄釣𢇁。","水云初起重，暮鸟逺来遲。","稚子能吳語，新文怨楚词。","怜君不得意，客鬢老南枝。"]', '诗', 'shi', '', NULL, '初貶南巴至鄱陽題李嘉祐江亭 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56c7ff04-a62b-41c9-bb78-6b98789d9c4e', '自紫陽觀至華陽洞宿侯尊師草堂簡同遊李延年', '自紫陽观至华陽洞宿侯尊師草堂簡同游李延年', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["石門媚煙景，句曲盤江甸。","南向佳氣濃，數峰遙隱見。","漸臨華陽口，雲路入蔥蒨。","七曜懸洞宮，五雲抱仙殿。","銀函竟誰發，金液徒堪薦。","千載空桃花，秦人深不見。","東溪喜相遇，貞白如會面。","青鳥來去閑，紅霞朝夕變。","一從換仙骨，萬里乘飛電。","蘿月延步虛，松花醉閑宴。","幽人即長往，茂宰應交戰。","明發歸琴堂，知君嬾爲縣。"]', '["石门媚煙景，句曲盤江甸。","南向佳氣濃，數峰遙隐见。","漸臨华陽口，云路入蔥蒨。","七曜懸洞宮，五云抱仙殿。","銀函竟誰發，金液徒堪薦。","千載空桃花，秦人深不见。","东溪喜相遇，貞白如會面。","青鸟来去闲，紅霞朝夕变。","一從換仙骨，万里乘飞電。","蘿月延步虛，松花醉闲宴。","幽人即长往，茂宰應交戰。","明發归琴堂，知君嬾爲縣。"]', '诗', 'shi', '', NULL, '自紫陽觀至華陽洞宿侯尊師草堂簡同遊李延年 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('decb1f34-e449-483e-86eb-2c1748a556d2', '奉使新安自桐廬縣經嚴陵釣臺宿七里灘下寄使院諸公', '奉使新安自桐廬縣經嚴陵釣台宿七里灘下寄使院諸公', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["悠然釣臺下，懷古時一望。","江水自潺湲，行人獨惆悵。","新安從此始，桂檝方蕩漾。","回轉百里間，青山千萬狀。","連崖去不斷，對嶺遙相向。","夾岸黛色愁，沈沈綠波上。","夕陽留古木，水鳥拂寒浪。","月下扣舷聲，煙中採菱唱。","猶憐負羈束，未暇依清曠。","牽役徒自勞，近名非所向。","何時故山裏，却醉松花釀。","回首唯白雲，孤舟復誰訪。"]', '["悠然釣台下，懷古时一望。","江水自潺湲，行人独惆悵。","新安從此始，桂檝方蕩漾。","回轉百里间，青山千万狀。","連崖去不斷，对嶺遙相向。","夾岸黛色愁，沈沈綠波上。","夕陽留古木，水鸟拂寒浪。","月下扣舷声，煙中採菱唱。","猶怜負羈束，未暇依清曠。","牽役徒自勞，近名非所向。","何时故山裏，却醉松花釀。","回首唯白云，孤舟复誰訪。"]', '诗', 'shi', '', NULL, '奉使新安自桐廬縣經嚴陵釣臺宿七里灘下寄使院諸公 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31a3525b-78fa-43fe-a706-a176a082cca1', '題虎丘寺', '題虎丘寺', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["青林虎丘寺，林際翠微路。","仰見山僧來，遙從飛鳥處。","茲峰淪寶玉，千載唯丘墓。","埋劒人空傳，鑿山龍已去。","捫蘿披翳薈，路轉夕陽遽。","虎嘯崖谷寒，猿鳴杉松暮。","裴回北樓上，江海窮一顧。","日映千里帆，鴉歸萬家樹。","蹔因愜所適，果得損外慮。","庭暗棲閑雲，簷香滴甘露。","久迷空寂理，多爲繁華故。","永欲投死生，餘生豈能誤。"]', '["青林虎丘寺，林際翠微路。","仰见山僧来，遙從飞鸟处。","茲峰淪寶玉，千載唯丘墓。","埋劒人空傳，鑿山龙已去。","捫蘿披翳薈，路轉夕陽遽。","虎嘯崖谷寒，猿鳴杉松暮。","裴回北楼上，江海窮一顧。","日映千里帆，鴉归万家樹。","蹔因愜所適，果得損外慮。","庭暗棲闲云，簷香滴甘露。","久迷空寂理，多爲繁华故。","永欲投死生，餘生豈能誤。"]', '诗', 'shi', '', NULL, '題虎丘寺 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6bf0459-45f3-4bd8-82ce-bdbd323f5f09', '奉餞鄭中丞罷浙西節度還京', '奉餞鄭中丞罷浙西節度還京', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["天上移將星，元戎罷龍節。","三軍含怨慕，橫吹聲斷絕。","五馬嘶城隅，萬人臥車轍。","滄洲浮雲暮，杳杳去帆發。","回首不問家，歸心遙向闕。","煙波限吳楚，日夕事淮越。","弔影失所依，側身隨下列。","孤蓬飛不定，長劒光未滅。","綠綺爲誰彈，綠芳堪自擷。","悵然江南春，獨此湖上月。","千里懷去思，百憂變華髮。","頌聲滿江海，今古流不竭。"]', '["天上移將星，元戎罷龙節。","三軍含怨慕，橫吹声斷絕。","五马嘶城隅，万人臥车轍。","滄洲浮云暮，杳杳去帆發。","回首不问家，归心遙向闕。","煙波限吳楚，日夕事淮越。","弔影失所依，側身隨下列。","孤蓬飞不定，长劒光未滅。","綠綺爲誰彈，綠芳堪自擷。","悵然江南春，独此湖上月。","千里懷去思，百憂变华髮。","頌声满江海，今古流不竭。"]', '诗', 'shi', '', NULL, '奉餞鄭中丞罷浙西節度還京 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e93915f1-fb55-4fa8-8d41-3f56cee15cb7', '送裴四判官赴河西軍試', '送裴四判官赴河西軍試', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["吏道豈易愜，如君誰與儔。","逢時將騁驥，臨事無全牛。","鮑叔幸相知，田蘇頗同遊。","英資挺孤秀，清論含古流。","出塞佐持簡，辭家擁鳴騶。","憲臺貴公舉，幕府資良籌。","武士佇明試，皇華難久留。","陽關望天盡，洮水令人愁。","萬里看一鳥，曠然煙霞收。","晚花對古戍，春雪含邊州。","道路難暫隔，音塵那可求。","他時相望處，明月西南樓。"]', '["吏道豈易愜，如君誰與儔。","逢时將騁驥，臨事無全牛。","鲍叔幸相知，田蘇頗同游。","英資挺孤秀，清論含古流。","出塞佐持簡，辞家擁鳴騶。","憲台貴公舉，幕府資良籌。","武士佇明試，皇华难久留。","陽关望天尽，洮水令人愁。","万里看一鸟，曠然煙霞收。","晚花对古戍，春雪含邊州。","道路难暫隔，音塵那可求。","他时相望处，明月西南楼。"]', '诗', 'shi', '', NULL, '送裴四判官赴河西軍試 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2253e5f4-5e6a-4906-b808-3220cf8ecabe', '旅次丹陽郡遇康侍御宣慰召募兼別岑單父', '旅次丹陽郡遇康侍御宣慰召募兼別岑單父', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["客心暮千里，回首煙花繁。","楚水渡歸夢，春江連故園。","羈人懷上國，驕虜窺中原。","胡馬暫爲害，漢臣多負恩。","羽書晝夜飛，海內風塵昏。","雙鬢日已白，孤舟心且論。","繡衣從此來，汗馬宣王言。","憂憤激忠勇，悲歡動黎元。","南徐爭赴難，發卒如雲屯。","倚劒看太白，洗兵臨海門。","故人亦滄洲，少別堪傷魂。","積翠下京口，歸潮落山根。","如何天外帆，又此波上尊。","空使憶君處，鶯聲催淚痕。"]', '["客心暮千里，回首煙花繁。","楚水渡归梦，春江連故园。","羈人懷上国，驕虜窺中原。","胡马暫爲害，漢臣多負恩。","羽书晝夜飞，海內风塵昏。","雙鬢日已白，孤舟心且論。","繡衣從此来，汗马宣王言。","憂憤激忠勇，悲歡动黎元。","南徐爭赴难，發卒如云屯。","倚劒看太白，洗兵臨海门。","故人亦滄洲，少別堪傷魂。","積翠下京口，归潮落山根。","如何天外帆，又此波上尊。","空使憶君处，鶯声催泪痕。"]', '诗', 'shi', '', NULL, '旅次丹陽郡遇康侍御宣慰召募兼別岑單父 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8057519-a079-43ec-9faf-f0e9f3c4ca09', '客舍贈別韋九建赴任河南韋十七造赴任鄭縣就便覲省', '客舍贈別韋九建赴任河南韋十七造赴任鄭縣就便覲省', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["與子頗疇昔，常時仰英髦。","弟兄盡公器，詩賦凌風騷。","頃者遊上國，獨能光選曹。","香名冠二陸，精鑒逢山濤。","且副倚門望，莫辭趨府勞。","桃花照綵服，草色連青袍。","征馬臨素滻，離人傾濁醪。","華山微雨霽，祠上殘雲高。","而我倦棲屑，別君良鬱陶。","春風亦未已，旅思空滔滔。","拙分甘棄置，窮居長蓬蒿。","人生未鵾化，物議如鴻毛。","迢遞兩鄉別，殷勤一寶刀。"]', '["與子頗疇昔，常时仰英髦。","弟兄尽公器，诗賦凌风騷。","頃者游上国，独能光選曹。","香名冠二陸，精鑒逢山濤。","且副倚门望，莫辞趨府勞。","桃花照綵服，草色連青袍。","征马臨素滻，離人傾濁醪。","华山微雨霽，祠上殘云高。","而我倦棲屑，別君良鬱陶。","春风亦未已，旅思空滔滔。","拙分甘棄置，窮居长蓬蒿。","人生未鵾化，物議如鴻毛。","迢遞兩乡別，殷勤一寶刀。"]', '诗', 'shi', '', NULL, '客舍贈別韋九建赴任河南韋十七造赴任鄭縣就便覲省 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38a99ebe-b15e-4544-bf96-513eb55c1542', '送元八遊汝南', '送元八游汝南', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["元生實奇邁，幸此論疇昔。","刀筆素推高，鋒鋩久無敵。","縱橫濟時意，跌宕過人蹟。","破產供酒錢，盈門皆食客。","田園頃失計，資用深相迫。","生事誠可憂，嚴裝遠何適。","世情薄恩義，俗態輕窮厄。","四海金雖多，其如向人惜。","迢遞朗陵道，悵望都門夕。","向別伊水南，行看楚雲隔。","繁蟬動高柳，疋馬嘶平澤。","潢潦今正深，陂湖未澄碧。","人生不得已，自可甘形役。","勿復尊前酒，離居剩悽戚。"]', '["元生實奇邁，幸此論疇昔。","刀笔素推高，鋒鋩久無敵。","縱橫濟时意，跌宕過人蹟。","破產供酒錢，盈门皆食客。","田园頃失計，資用深相迫。","生事誠可憂，嚴裝远何適。","世情薄恩義，俗態轻窮厄。","四海金雖多，其如向人惜。","迢遞朗陵道，悵望都门夕。","向別伊水南，行看楚云隔。","繁蟬动高柳，疋马嘶平澤。","潢潦今正深，陂湖未澄碧。","人生不得已，自可甘形役。","勿复尊前酒，離居剩悽戚。"]', '诗', 'shi', '', NULL, '送元八遊汝南 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23dbe0e0-5103-450f-b619-a3c30308d416', '奉和李大夫同呂評事太行苦熱行兼寄院中諸公仍呈王員外', '奉和李大夫同呂評事太行苦熱行兼寄院中諸公仍呈王員外', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["迢遞太行路，自古稱險惡。","千騎儼欲前，羣峰望如削。","火雲從中出，仰視飛鳥落。","汗馬臥高原，危旌倚長薄。","清風竟不至，赤日方煎鑠。","石枯山木燋，鱗窮水泉涸。","九重今旰食，萬里傳明略。","諸將候軒車，元凶愁鼎鑊。","何勞短兵接，自有長纓縛。","通越事豈難，渡瀘功未博。","朝辭羊腸阪，夕望貝丘郭。","漳水斜遶營，常山遙入幕。","永懷姑蘇下，遙寄建安作。","白雪和難成，滄波意空託。","陳琳書記好，王粲從軍樂。","早晚歸漢廷，隨公上麟閣。"]', '["迢遞太行路，自古稱險惡。","千騎儼欲前，羣峰望如削。","火云從中出，仰視飞鸟落。","汗马臥高原，危旌倚长薄。","清风竟不至，赤日方煎鑠。","石枯山木燋，鱗窮水泉涸。","九重今旰食，万里傳明略。","諸將候軒车，元凶愁鼎鑊。","何勞短兵接，自有长纓縛。","通越事豈难，渡瀘功未博。","朝辞羊腸阪，夕望貝丘郭。","漳水斜遶營，常山遙入幕。","永懷姑蘇下，遙寄建安作。","白雪和难成，滄波意空託。","陳琳书記好，王粲從軍乐。","早晚归漢廷，隨公上麟閣。"]', '诗', 'shi', '', NULL, '奉和李大夫同呂評事太行苦熱行兼寄院中諸公仍呈王員外 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28c76401-3b91-4f73-976e-2643b9903b9e', '洛陽主簿叔知和驛承恩赴選伏辭一首', '洛陽主簿叔知和驛承恩赴選伏辞一首', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["仲父王佐材，屈身仇香位。","一從理京劇，萬事皆容易。","則知無不可，通變有餘地。","器宇溟渤寬，文鋒鏌铘利。","憧憧洛陽道，日夕皇華使。","二載出江亭，一心奉王事。","功成良可錄，道在知無愧。","天府留香名，銓闈就明試。","賦詩皆舊友，攀轍多新吏。","綵服辭高堂，青袍擁征騎。","此行季春月，時物正鮮媚。","官柳陰相連，桃花色如醉。","長安想在目，前路遙髣髴。","落日看華山，關門逼青翠。","行襜稍已隔，結戀無能慰。","誰念尊酒間，裴回竹林意。"]', '["仲父王佐材，屈身仇香位。","一從理京劇，万事皆容易。","則知無不可，通变有餘地。","器宇溟渤寬，文鋒鏌铘利。","憧憧洛陽道，日夕皇华使。","二載出江亭，一心奉王事。","功成良可錄，道在知無愧。","天府留香名，銓闈就明試。","賦诗皆旧友，攀轍多新吏。","綵服辞高堂，青袍擁征騎。","此行季春月，时物正鲜媚。","官柳陰相連，桃花色如醉。","长安想在目，前路遙髣髴。","落日看华山，关门逼青翠。","行襜稍已隔，結戀無能慰。","誰念尊酒间，裴回竹林意。"]', '诗', 'shi', '', NULL, '洛陽主簿叔知和驛承恩赴選伏辭一首 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa34c56f-f100-4a7f-8f79-2f5c52a4b6ec', '題冤句宋少府廳留別', '題冤句宋少府廳留別', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["宋侯人之秀，獨步南曹吏。","世上無此才，天生一公器。","尚甘黃綬屈，未適青雲意。","洞澈萬頃陂，昂藏千里驥。","從宦聞苦節，應物推高誼。","薄俸不自資，傾家共人費。","顧予倦棲託，終日憂窮匱。","開口即有求，私心豈無愧。","幸逢東道主，因輟西征騎。","對話堪息機，披文欲忘味。","壺觴招過客，几案無留事。","綠樹映層城，蒼苔覆閑地。","一言重然諾，累夕陪宴慰。","何意秋風來，颯然動歸思。","留歡殊自愜，去念能爲累。","草色愁別時，槐花落行次。","臨期仍把手，此會良不易。","他日瓊樹枝，相思勞夢寐。"]', '["宋侯人之秀，独步南曹吏。","世上無此才，天生一公器。","尚甘黄綬屈，未適青云意。","洞澈万頃陂，昂藏千里驥。","從宦闻苦節，應物推高誼。","薄俸不自資，傾家共人費。","顧予倦棲託，終日憂窮匱。","开口即有求，私心豈無愧。","幸逢东道主，因輟西征騎。","对話堪息機，披文欲忘味。","壺觴招過客，几案無留事。","綠樹映層城，蒼苔覆闲地。","一言重然諾，累夕陪宴慰。","何意秋风来，颯然动归思。","留歡殊自愜，去念能爲累。","草色愁別时，槐花落行次。","臨期仍把手，此會良不易。","他日瓊樹枝，相思勞梦寐。"]', '诗', 'shi', '', NULL, '題冤句宋少府廳留別 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e44342c3-069f-4a4a-88c0-2d36a761e0ea', '罷攝官後將還舊居留辭李侍御', '罷攝官後將還旧居留辞李侍御', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["江海今爲客，風波失所依。","白雲心已負，黃綬計仍非。","累辱羣公薦，頻霑一尉微。","去緣焚玉石，來爲采葑菲。","州縣名何在，漁樵事亦違。","故山桃李月，初服薜蘿衣。","熊軾分朝寄，龍韜解賊圍。","風謠傳吏體，雲物助兵威。","白雲飄辭律，青春發禮闈。","引軍橫吹動，援翰捷書揮。","草映翻營綠，花臨檄羽飛。","全吳爭轉戰，狂虜怯知機。","憶昨趨金節，臨時廢玉徽。","俗流應不厭，靜者或相譏。","世難慵干謁，時閑喜放歸。","潘郎悲白髮，謝客愛清輝。","樗散材因棄，交親迹已稀。","獨愁看五柳，無事掩雙扉。","世累多行路，生涯向釣磯。","榜連溪水碧，家羨渚田肥。","旅食傷飄梗，巖棲憶采薇。","悠然獨歸去，回首望旌旗。"]', '["江海今爲客，风波失所依。","白云心已負，黄綬計仍非。","累辱羣公薦，頻霑一尉微。","去緣焚玉石，来爲采葑菲。","州縣名何在，漁樵事亦違。","故山桃李月，初服薜蘿衣。","熊軾分朝寄，龙韜解賊圍。","风謠傳吏體，云物助兵威。","白云飄辞律，青春發禮闈。","引軍橫吹动，援翰捷书揮。","草映翻營綠，花臨檄羽飞。","全吳爭轉戰，狂虜怯知機。","憶昨趨金節，臨时廢玉徽。","俗流應不厭，静者或相譏。","世难慵干謁，时闲喜放归。","潘郎悲白髮，謝客愛清輝。","樗散材因棄，交親迹已稀。","独愁看五柳，無事掩雙扉。","世累多行路，生涯向釣磯。","榜連溪水碧，家羨渚田肥。","旅食傷飄梗，巖棲憶采薇。","悠然独归去，回首望旌旗。"]', '诗', 'shi', '', NULL, '罷攝官後將還舊居留辭李侍御 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a1d814c-c861-469d-9f1a-53860e4f03ce', '贈別于羣投筆赴安西', '贈別于羣投笔赴安西', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["風流一才子，經史仍滿腹。","心鏡萬象生，文鋒衆人服。","頃遊靈臺下，頻棄荆山玉。","蹭蹬空數年，裴回冀微祿。","朅來投筆硯，長揖謝親族。","且欲圖變通，安能守拘束。","本持鄉曲譽，肯料泥塗辱。","誰謂命迍邅，還令計反覆。","西戎今未弭，胡騎屯山谷。","坐恃龍豹韜，全輕蜂蠆毒。","拂衣從此去，擁傳一何速。","元帥許提攜，他人佇瞻矚。","出門寡儔侶，矧乃無僮僕。","黠虜時相逢，黃沙暮愁宿。","蕭條遠回首，萬里如在目。","漢境天西窮，[胡]山海邊綠。","想聞羌笛處，淚盡關山曲。","地闊鳥飛遲，風寒馬毛縮。","邊愁殊浩蕩，離思空斷續。","塞上歸限賒，尊前別期促。","知君志不小，一舉凌鴻鵠。","且願樂從軍，功名在殊俗。"]', '["风流一才子，經史仍满腹。","心镜万象生，文鋒衆人服。","頃游靈台下，頻棄荆山玉。","蹭蹬空數年，裴回冀微祿。","朅来投笔硯，长揖謝親族。","且欲圖变通，安能守拘束。","本持乡曲譽，肯料泥塗辱。","誰謂命迍邅，還令計反覆。","西戎今未弭，胡騎屯山谷。","坐恃龙豹韜，全轻蜂蠆毒。","拂衣從此去，擁傳一何速。","元帥許提携，他人佇瞻矚。","出门寡儔侶，矧乃無僮僕。","黠虜时相逢，黄沙暮愁宿。","蕭條远回首，万里如在目。","漢境天西窮，[胡]山海邊綠。","想闻羌笛处，泪尽关山曲。","地闊鸟飞遲，风寒马毛縮。","邊愁殊浩蕩，離思空斷續。","塞上归限賒，尊前別期促。","知君志不小，一舉凌鴻鵠。","且願乐從軍，功名在殊俗。"]', '诗', 'shi', '', NULL, '贈別于羣投筆赴安西 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a09c1fb-69c2-46c4-a242-d811823d1df0', '送薛據宰涉縣', '送薛據宰涉縣', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["故人河山秀，獨立風神異。","人許白眉長，天姿青雲器。","雄辭變文名，高價喧時議。","下筆盈萬言，皆合古人意。","一從負能名，數載猶卑位。","寶劒誠可用，烹鮮是虛棄。","昔聞在河上，高臥自無事。","几案終日閑，蒲鞭使人畏。","頃因歲月滿，方謝風塵吏。","頌德有輿人，薦賢逢八使。","棲鸞往已屈，馴雀今可嗣。","此道如不移，雲霄坐應致。","縣前漳水綠，郭外晉山翠。","日得謝客遊，時堪陶令醉。","前期今尚遠，握手空宴慰。","驛路疎柳長，春城百花媚。","裴回白日隱，暝色含天地。","一鳥向灞陵，孤雲送行騎。","夫君多述作，而我常諷味。","賴有瓊瑤資，能寬別離思。","槐陰覆堂殿，苔色上階砌。","鳥倦自歸飛，雲閑獨空㵝。","既將慕幽絕，兼欲看定慧。","遇物忘世緣，還家嬾生計。","無生妄已息，有妄心可制。","心鏡常虛明，時人自淪翳。"]', '["故人河山秀，独立风神異。","人許白眉长，天姿青云器。","雄辞变文名，高價喧时議。","下笔盈万言，皆合古人意。","一從負能名，數載猶卑位。","寶劒誠可用，烹鲜是虛棄。","昔闻在河上，高臥自無事。","几案終日闲，蒲鞭使人畏。","頃因歲月满，方謝风塵吏。","頌德有輿人，薦賢逢八使。","棲鸾往已屈，馴雀今可嗣。","此道如不移，云霄坐應致。","縣前漳水綠，郭外晉山翠。","日得謝客游，时堪陶令醉。","前期今尚远，握手空宴慰。","驛路疎柳长，春城百花媚。","裴回白日隐，暝色含天地。","一鸟向灞陵，孤云送行騎。","夫君多述作，而我常諷味。","賴有瓊瑤資，能寬別離思。","槐陰覆堂殿，苔色上階砌。","鸟倦自归飞，云闲独空㵝。","既將慕幽絕，兼欲看定慧。","遇物忘世緣，還家嬾生計。","無生妄已息，有妄心可制。","心镜常虛明，时人自淪翳。"]', '诗', 'shi', '', NULL, '送薛據宰涉縣 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a0f5b42-0e13-4f68-8ef4-571f4fe4ffdc', '早春贈別趙居士還江左時長卿下第歸嵩陽舊居', '早春贈別趙居士還江左时长卿下第归嵩陽旧居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["見君風塵裏，意出風塵外。","自有滄洲期，含情十餘載。","深居鳳城曲，日預龍華會。","果得僧家緣，能遺俗人態。","一身今已適，萬物知何愛。","悟法電已空，看心水無礙。","且將窮妙理，兼欲尋勝概。","何獨謝客遊，當爲遠公輩。","放舟馳楚郭，負杖辭秦塞。","目送南飛雲，令人想吳會。","遙思舊遊處，髣髴疑相對。","夜火金陵城，春煙石頭瀨。","滄波極天末，萬里明如帶。","一片孤客帆，飄然向青靄。","楚天合江氣，雲色常霮䨴。","隱見湖中山，相連數州內。","君行意可得，全與時人背。","歸路隨楓林，還鄉念蓴菜。","顧予尚羈束，何幸承眄睞。","素願徒自勤，清機本難逮。","累幸忝賓薦，末路逢沙汰。","濩落名不成，裴回意空大。","逢時雖貴達，守道甘易退。","逆旅鄉夢頻，春風客心碎。","別君日已遠，離念無明晦。","予亦返柴荆，山田事耕耒。"]', '["见君风塵裏，意出风塵外。","自有滄洲期，含情十餘載。","深居鳳城曲，日預龙华會。","果得僧家緣，能遺俗人態。","一身今已適，万物知何愛。","悟法電已空，看心水無礙。","且將窮妙理，兼欲尋勝概。","何独謝客游，當爲远公輩。","放舟驰楚郭，負杖辞秦塞。","目送南飞云，令人想吳會。","遙思旧游处，髣髴疑相对。","夜火金陵城，春煙石头瀨。","滄波極天末，万里明如带。","一片孤客帆，飄然向青靄。","楚天合江氣，云色常霮䨴。","隐见湖中山，相連數州內。","君行意可得，全與时人背。","归路隨楓林，還乡念蓴菜。","顧予尚羈束，何幸承眄睞。","素願徒自勤，清機本难逮。","累幸忝賓薦，末路逢沙汰。","濩落名不成，裴回意空大。","逢时雖貴達，守道甘易退。","逆旅乡梦頻，春风客心碎。","別君日已远，離念無明晦。","予亦返柴荆，山田事耕耒。"]', '诗', 'shi', '', NULL, '早春贈別趙居士還江左時長卿下第歸嵩陽舊居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03857755-ded7-4098-9d07-94ad24cd20f2', '夜宴洛陽程九主簿宅送楊三山人往天台尋智者禪師隱居', '夜宴洛陽程九主簿宅送楊三山人往天台尋智者禪師隐居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["東林問逋客，何處棲幽偏？","滿腹萬餘卷，息機三十年。","志圖良已久，鬢髮空蒼然。","調嘯寄疎曠，形骸如棄捐。","本家關西族，別業嵩陽田。","雲臥能獨往，山棲幸周旋。","垂竿不在魚，賣藥不爲錢。","藜杖閑倚壁，松花常醉眠。","頃辭青溪隱，來訪赤縣仙。","南畝自甘賤，中朝唯愛賢。","仍空世諦法，遠結天台緣。","魏闕從此去，滄洲知所便。","主人瓊枝秀，寵別瑤華篇。","落日掃塵榻，春風吹客船。","此行頗自適，物外誰能牽。","弄棹白蘋裏，挂帆飛鳥邊。","落潮見孤嶼，徹底觀澄漣。","雁過湖上月，猿聲峰際天。","羣峰趨海嶠，千里黛相連。","遙倚赤城上，曈曈初日圓。","昔聞智公隱，此地常安禪。","千載已如夢，一燈今尚傳。","雲龕閉遺影，石窟無人煙。","古寺暗喬木，春崖鳴細泉。","流塵既寂寞，緬想增嬋娟。","山鳥怨庭樹，門人思步蓮。","夷猶懷永路，悵望臨清川。","漁人來夢裏，沙鷗飛眼前。","獨遊豈易愜，羣動多相纏。","羨爾五湖夜，往來閑扣舷。"]', '["东林问逋客，何处棲幽偏？","满腹万餘卷，息機三十年。","志圖良已久，鬢髮空蒼然。","調嘯寄疎曠，形骸如棄捐。","本家关西族，別業嵩陽田。","云臥能独往，山棲幸周旋。","垂竿不在鱼，賣藥不爲錢。","藜杖闲倚壁，松花常醉眠。","頃辞青溪隐，来訪赤縣仙。","南畝自甘賤，中朝唯愛賢。","仍空世諦法，远結天台緣。","魏闕從此去，滄洲知所便。","主人瓊枝秀，寵別瑤华篇。","落日掃塵榻，春风吹客船。","此行頗自適，物外誰能牽。","弄棹白蘋裏，挂帆飞鸟邊。","落潮见孤嶼，徹底观澄漣。","雁過湖上月，猿声峰際天。","羣峰趨海嶠，千里黛相連。","遙倚赤城上，曈曈初日圓。","昔闻智公隐，此地常安禪。","千載已如梦，一灯今尚傳。","云龕閉遺影，石窟無人煙。","古寺暗喬木，春崖鳴細泉。","流塵既寂寞，緬想增嬋娟。","山鸟怨庭樹，门人思步蓮。","夷猶懷永路，悵望臨清川。","漁人来梦裏，沙鷗飞眼前。","独游豈易愜，羣动多相纏。","羨爾五湖夜，往来闲扣舷。"]', '诗', 'shi', '', NULL, '夜宴洛陽程九主簿宅送楊三山人往天台尋智者禪師隱居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97dfdf56-aa86-4e99-a5fd-d7273ddf8146', '瓜洲驛奉餞張侍御公拜膳部郎中却復憲臺充賀蘭大夫留後使之嶺南時侍御先在淮南幕府', '瓜洲驛奉餞張侍御公拜膳部郎中却复憲台充賀蘭大夫留後使之嶺南时侍御先在淮南幕府', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["太華高標峻，青陽淑氣盤。","屬辭傾渤澥，稱價掩琅玕。","楊葉頻推中，芸香早拜官。","後來慚轍跡，先達仰門闌。","佐劇勞黃綬，提綱疾素餐。","風生趨府步，筆偃觸邪冠。","骨鯁知難屈，鋒鋩豈易干。","佇將調玉鉉，翻自落金丸。","異議那容直，專權本畏彈。","寸心寧有負，三黜竟無端。","適喜鴻私降，旋驚羽檄攢。","國憐朝市易，人怨虎狼殘。","天地龍初見，風塵虜未殫。","隨川歸少海，就日背長安。","副相榮分寄，輸忠義不刊。","擊胡馳汗馬，遷蜀扈鳴鑾。","月罷名卿署，星懸上將壇。","三軍搖斾出，百越畫圖觀。","茅茹能相引，泥沙肯再蟠。","兼榮知任重，交辟許才難。","勁直隨臺柏，芳香動省蘭。","璧從全趙去，鵬自北溟摶。","星象銜新寵，風霜帶舊寒。","是非生倚伏，榮辱繫悲歡。","疇昔偏殊眄，屯蒙獨永歎。","不才成擁腫，失計似邯鄲。","江國傷移律，家山憶考槃。","一爲鷗鳥誤，三見露華團。","回首青雲裏，應憐濁水瀾。","愧將生事托，羞向鬢毛看。","知己傷愆素，他人自好丹。","鄉春連楚越，旅宿寄風湍。","世路東流水，滄江一釣竿。","松聲伯禹穴，草色子陵灘。","度嶺情何遽，臨流興未闌。","梅花分路遠，揚子上潮寬。","夢想懷依倚，煙波限渺漫。","且愁無去雁，寧翼少回鸞。","極浦春帆迥，空郊晚騎單。","獨憐南渡月，今夕送歸鞍。"]', '["太华高標峻，青陽淑氣盤。","屬辞傾渤澥，稱價掩琅玕。","楊葉頻推中，芸香早拜官。","後来慚轍跡，先達仰门闌。","佐劇勞黄綬，提綱疾素餐。","风生趨府步，笔偃觸邪冠。","骨鯁知难屈，鋒鋩豈易干。","佇將調玉鉉，翻自落金丸。","異議那容直，專權本畏彈。","寸心寧有負，三黜竟無端。","適喜鴻私降，旋驚羽檄攢。","国怜朝市易，人怨虎狼殘。","天地龙初见，风塵虜未殫。","隨川归少海，就日背长安。","副相榮分寄，輸忠義不刊。","擊胡驰汗马，遷蜀扈鳴鑾。","月罷名卿署，星懸上將壇。","三軍搖斾出，百越畫圖观。","茅茹能相引，泥沙肯再蟠。","兼榮知任重，交辟許才难。","勁直隨台柏，芳香动省蘭。","璧從全趙去，鵬自北溟摶。","星象銜新寵，风霜带旧寒。","是非生倚伏，榮辱繫悲歡。","疇昔偏殊眄，屯蒙独永歎。","不才成擁腫，失計似邯鄲。","江国傷移律，家山憶考槃。","一爲鷗鸟誤，三见露华團。","回首青云裏，應怜濁水瀾。","愧將生事托，羞向鬢毛看。","知己傷愆素，他人自好丹。","乡春連楚越，旅宿寄风湍。","世路东流水，滄江一釣竿。","松声伯禹穴，草色子陵灘。","度嶺情何遽，臨流兴未闌。","梅花分路远，揚子上潮寬。","梦想懷依倚，煙波限渺漫。","且愁無去雁，寧翼少回鸾。","極浦春帆迥，空郊晚騎單。","独怜南渡月，今夕送归鞍。"]', '诗', 'shi', '', NULL, '瓜洲驛奉餞張侍御公拜膳部郎中却復憲臺充賀蘭大夫留後使之嶺南時侍御先在淮南幕府 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde2f525-95e4-4dec-8e58-95f8ee53cfe8', '至德三年春正月時謬蒙差攝海鹽令聞王師收二京因書事寄上浙西節度李侍郎中丞行營五十韻', '至德三年春正月时謬蒙差攝海鹽令闻王師收二京因书事寄上浙西節度李侍郎中丞行營五十韻', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["天上胡星孛，人間反氣橫。","風塵生汗馬，河洛縱長鯨。","本謂才非據，誰知禍已萌。","食參將可待，誅錯輙爲名。","萬里兵鋒接，三時羽檄驚。","負恩殊鳥獸，流毒遍黎氓。","朝市成蕪沒，干戈起戰爭。","人心懸反覆，天道暫虛盈。","略地侵中土，傳烽到上京。","王師陷魑魅，帝座逼欃槍。","渭水嘶胡馬，秦山泣漢兵。","關原馳萬騎，煙火亂千甍。","鳳駕瞻西幸，龍樓議北征。","自將行破竹，誰學去吹笙。","白日重輪慶，玄穹再造榮。","鬼神潛釋憤，夷狄遠輸誠。","海內戎衣卷，關中賊壘平。","山川隨轉戰，草木困橫行。","區宇神功立，謳歌帝業成。","天回萬象慶，龍見五雲迎。","小苑春猶在，長安日更明。","星辰歸正位，雷雨發殘生。","文物登前古，簫韶下太清。","未央新柳色，長樂舊鐘聲。","八使推邦彥，中司案國程。","蒼生屬伊呂，明主仗韓彭。","兇醜將除蔓，姦豪已負荆。","世危看柱石，時難識忠貞。","薄伐徵貔虎，長驅擁斾旌。","吳山依重鎮，江月帶行營。","金石懸詞律，煙雲動筆精。","運籌初減竈，調鼎未和羹。","北虜傳初解，東人望已傾。","池塘催謝客，花木待春卿。","昔忝登龍首，能傷困驥鳴。","艱難悲伏劒，提握喜懸衡。","巴曲誰堪聽，秦臺自有情。","遂令辭短褐，仍欲請長纓。","久客田園廢，初官印綬輕。","榛蕪上國路，苔蘚北山楹。","嬾慢羞趨府，驅馳憶退耕。","榴花無暇醉，蓬髮帶愁縈。","地僻方言異，身微俗慮幷。","家憐雙鯉斷，才媿小鱗烹。","滄海今猶滯，青陽歲又更。","洲香生杜若，谿煖戲鵁鶄。","煙水宜春候，褰關值晚晴。","潮聲來萬井，山色映孤城。","旅夢親喬木，歸心亂早鶯。","倘無知己在，今已訪蓬瀛。"]', '["天上胡星孛，人间反氣橫。","风塵生汗马，河洛縱长鯨。","本謂才非據，誰知禍已萌。","食參將可待，誅錯輙爲名。","万里兵鋒接，三时羽檄驚。","負恩殊鸟獸，流毒遍黎氓。","朝市成蕪沒，干戈起戰爭。","人心懸反覆，天道暫虛盈。","略地侵中土，傳烽到上京。","王師陷魑魅，帝座逼欃槍。","渭水嘶胡马，秦山泣漢兵。","关原驰万騎，煙火亂千甍。","鳳駕瞻西幸，龙楼議北征。","自將行破竹，誰学去吹笙。","白日重輪慶，玄穹再造榮。","鬼神潛釋憤，夷狄远輸誠。","海內戎衣卷，关中賊壘平。","山川隨轉戰，草木困橫行。","區宇神功立，謳歌帝業成。","天回万象慶，龙见五云迎。","小苑春猶在，长安日更明。","星辰归正位，雷雨發殘生。","文物登前古，簫韶下太清。","未央新柳色，长乐旧鐘声。","八使推邦彥，中司案国程。","蒼生屬伊呂，明主仗韓彭。","兇醜將除蔓，姦豪已負荆。","世危看柱石，时难識忠貞。","薄伐徵貔虎，长驱擁斾旌。","吳山依重鎮，江月带行營。","金石懸词律，煙云动笔精。","運籌初減竈，調鼎未和羹。","北虜傳初解，东人望已傾。","池塘催謝客，花木待春卿。","昔忝登龙首，能傷困驥鳴。","艱难悲伏劒，提握喜懸衡。","巴曲誰堪听，秦台自有情。","遂令辞短褐，仍欲請长纓。","久客田园廢，初官印綬轻。","榛蕪上国路，苔蘚北山楹。","嬾慢羞趨府，驱驰憶退耕。","榴花無暇醉，蓬髮带愁縈。","地僻方言異，身微俗慮幷。","家怜雙鯉斷，才媿小鱗烹。","滄海今猶滯，青陽歲又更。","洲香生杜若，谿煖戲鵁鶄。","煙水宜春候，褰关值晚晴。","潮声来万井，山色映孤城。","旅梦親喬木，归心亂早鶯。","倘無知己在，今已訪蓬瀛。"]', '诗', 'shi', '', NULL, '至德三年春正月時謬蒙差攝海鹽令聞王師收二京因書事寄上浙西節度李侍郎中丞行營五十韻 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c832dd32-6f9f-46e4-ad67-5ce87da562b5', '尋張逸人山居', '尋張逸人山居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["危石纔通鳥道，空山更有人家。","桃源定在深處，澗水浮來落花。"]', '["危石纔通鸟道，空山更有人家。","桃源定在深处，澗水浮来落花。"]', '诗', 'shi', '', NULL, '尋張逸人山居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc4c89f7-437b-42d0-8362-b30a029b6a93', '發越州赴潤州使院留別鮑侍御', '發越州赴潤州使院留別鲍侍御', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["對水看山別離，孤舟日暮行遲。","江南江北春草，獨向金陵去時。"]', '["对水看山別離，孤舟日暮行遲。","江南江北春草，独向金陵去时。"]', '诗', 'shi', '', NULL, '發越州赴潤州使院留別鮑侍御 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff7cb898-487d-4ffa-8261-edf0bfabe31a', '送陸[澧]還吳中', '送陸[澧]還吳中', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["瓜步寒潮送客，楊柳暮雨沾衣。","故山南望何處，秋草連天獨歸。"]', '["瓜步寒潮送客，楊柳暮雨沾衣。","故山南望何处，秋草連天独归。"]', '诗', 'shi', '', NULL, '送陸[澧]還吳中 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1e365ee-c288-4279-9a84-3c0007144fe2', '苕溪酬梁耿別後見寄', '苕溪酬梁耿別後见寄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["清川永路何極，落日孤舟解攜。","鳥向平蕪遠近，人隨流水東西。","白雲千里萬里，明月前溪後溪。","惆悵長沙謫去，江潭芳草萋萋。"]', '["清川永路何極，落日孤舟解携。","鸟向平蕪远近，人隨流水东西。","白云千里万里，明月前溪後溪。","惆悵长沙謫去，江潭芳草萋萋。"]', '诗', 'shi', '', NULL, '苕溪酬梁耿別後見寄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bfabdb6-574e-4a38-9d55-28ea0a213c01', '蛇浦橋下重送嚴維', '蛇浦橋下重送嚴維', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["秋風颯颯鳴條，風月相和寂寥。","黃葉一離一別，青山暮暮朝朝。","寒江漸出高岸，古木猶依斷橋。","明日行人已遠，空餘淚滴回潮。"]', '["秋风颯颯鳴條，风月相和寂寥。","黄葉一離一別，青山暮暮朝朝。","寒江漸出高岸，古木猶依斷橋。","明日行人已远，空餘泪滴回潮。"]', '诗', 'shi', '', NULL, '蛇浦橋下重送嚴維 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cbf611f-031c-4fab-989d-a24645e7f46a', '七里灘重送', '七里灘重送', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["秋江渺渺水空波，越客孤舟欲榜歌。","手折衰楊悲老大，故人零落已無多。"]', '["秋江渺渺水空波，越客孤舟欲榜歌。","手折衰楊悲老大，故人零落已無多。"]', '诗', 'shi', '', NULL, '七里灘重送 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4081cc15-d180-49bf-97f2-0d27f01695a5', '家園瓜熟是故蕭相公所遺瓜種悽然感舊因賦此詩', '家园瓜熟是故蕭相公所遺瓜種悽然感旧因賦此诗', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["事去人亡跡自留，黃花綠蒂不勝愁。","誰能更向青門外，秋草茫茫覓故侯。"]', '["事去人亡跡自留，黄花綠蒂不勝愁。","誰能更向青门外，秋草茫茫覓故侯。"]', '诗', 'shi', '', NULL, '家園瓜熟是故蕭相公所遺瓜種悽然感舊因賦此詩 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3a427a0-3821-4310-aaf6-123c4ec020e4', '重送裴郎中貶吉州', '重送裴郎中貶吉州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["猿啼客散暮江頭，人自傷心水自流。","同作逐臣君更遠，青山萬里一孤舟。"]', '["猿啼客散暮江头，人自傷心水自流。","同作逐臣君更远，青山万里一孤舟。"]', '诗', 'shi', '', NULL, '重送裴郎中貶吉州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4514a4e0-b491-43d8-8eb2-475c818ed4c5', '尋盛禪師蘭若', '尋盛禪師蘭若', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["秋草黃花覆古阡，隔林何處起人煙。","山僧獨在山中老，唯有寒松見少年。"]', '["秋草黄花覆古阡，隔林何处起人煙。","山僧独在山中老，唯有寒松见少年。"]', '诗', 'shi', '', NULL, '尋盛禪師蘭若 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b87ec62-ac72-447a-bea0-002579c3d6be', '寄許尊師', '寄許尊師', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["獨上雲梯入翠微，蒙蒙煙雪映巖扉。","世人知在中峰裏，遙禮青山恨不歸。"]', '["独上云梯入翠微，蒙蒙煙雪映巖扉。","世人知在中峰裏，遙禮青山恨不归。"]', '诗', 'shi', '', NULL, '寄許尊師 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3e453ce-b591-4a18-91ea-b9df0a17c500', '酬李穆見寄', '酬李穆见寄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["孤舟相訪至天涯，萬轉雲山路更賒。","欲掃柴門迎遠客，青苔黃葉滿貧家。"]', '["孤舟相訪至天涯，万轉云山路更賒。","欲掃柴门迎远客，青苔黄葉满貧家。"]', '诗', 'shi', '', NULL, '酬李穆見寄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1898b1c7-c1ed-4790-8248-68c794d4c7d3', '送王司馬秩滿西歸', '送王司马秩满西归', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["漢主何時放逐臣？江邊幾度送歸人。","同官歲歲先辭滿，唯有青山伴老身。"]', '["漢主何时放逐臣？江邊幾度送归人。","同官歲歲先辞满，唯有青山伴老身。"]', '诗', 'shi', '', NULL, '送王司馬秩滿西歸 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa701a5e-8666-4100-a5be-f53ace69bdc5', '送王司馬秩滿西歸', '送王司马秩满西归', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["漢代何人訪逐臣，江邊幾度送歸人。","同官歲歲先辭滿，唯有青山伴老身。"]', '["漢代何人訪逐臣，江邊幾度送归人。","同官歲歲先辞满，唯有青山伴老身。"]', '诗', 'shi', '', NULL, '送王司馬秩滿西歸 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('439b19f5-2b3b-400f-99cb-f3245715ebf0', '寄別朱拾遺', '寄別朱拾遺', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["天書遠召滄浪客，幾度臨岐病未能。","江海茫茫春欲遍，行人一騎發金陵。"]', '["天书远召滄浪客，幾度臨岐病未能。","江海茫茫春欲遍，行人一騎發金陵。"]', '诗', 'shi', '', NULL, '寄別朱拾遺 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b493aef4-d26b-4db6-912e-9b41401a825e', '會赦後酬主簿所問', '會赦後酬主簿所问', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["江南海北長相憶，淺水深山獨掩扉。","重見太平身已老，桃源久住不能歸。"]', '["江南海北长相憶，淺水深山独掩扉。","重见太平身已老，桃源久住不能归。"]', '诗', 'shi', '', NULL, '會赦後酬主簿所問 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6a825a6-a414-4e25-bbb0-5b0ffb707b1d', '贈秦系', '贈秦系', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["向風長嘯戴紗巾，野鶴由來不可親。","明日東歸變名姓，五湖煙水覓何人。"]', '["向风长嘯戴紗巾，野鹤由来不可親。","明日东归变名姓，五湖煙水覓何人。"]', '诗', 'shi', '', NULL, '贈秦系 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98d85c6-5b82-45a1-9b18-f64d24828165', '酬靈徹公相招', '酬靈徹公相招', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["石磵泉聲久不聞，獨臨長路雪紛紛。","如今漸欲生黃髮，願脫頭冠與白雲。"]', '["石磵泉声久不闻，独臨长路雪紛紛。","如今漸欲生黄髮，願脫头冠與白云。"]', '诗', 'shi', '', NULL, '酬靈徹公相招 劉長卿 shi');
